diffs.replacement:
{
  "name": "Musaic Creator",
  "description": "A premium music management platform inspired by Spotify and Apple Music, featuring a sleek modern interface for managing artists, albums, and tracks with AI-powered enhancements.",
  "requestFramePermissions": [
    "camera"
  ]
}

export interface Artist {
  id: string;
  name: string;
  bio: string;
  imageUrl: string;
  genre: string;
  followers: number;
  verified: boolean;
}

export interface Album {
  id: string;
  title: string;
  artistId: string;
  artistName: string;
  coverUrl: string;
  releaseYear: number;
  genre: string;
  isLiked: boolean;
}

export interface Track {
  id: string;
  title: string;
  artistId: string;
  artistName: string;
  albumId: string;
  albumTitle: string;
  duration: string;
  plays: number;
  likes: number;
  isLiked: boolean;
}

export type ViewType = 'home' | 'search' | 'library' | 'artist' | 'album' | 'creator';

export interface NavigationState {
  view: ViewType;
  params?: {
    id?: string;
  };
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Home, 
  Search, 
  Library, 
  PlusCircle, 
  Heart, 
  Play, 
  MoreHorizontal, 
  Mic2, 
  Disc, 
  Music,
  ChevronLeft,
  ChevronRight,
  User,
  Sparkles,
  CheckCircle2,
  ListMusic,
  Clock,
  ThumbsUp
} from 'lucide-react';
import { GoogleGenAI } from '@google/genai';
import { Artist, Album, Track, ViewType, NavigationState } from './types';

// Initial Mock Data
const INITIAL_ARTISTS: Artist[] = [
  { id: '1', name: 'Lumina Echo', bio: 'Ethereal synth-pop architect from Helsinki.', imageUrl: 'https://picsum.photos/seed/artist1/600/600', genre: 'Dream Pop', followers: 1240000, verified: true },
  { id: '2', name: 'Velvet Horizon', bio: 'Cinematic jazz and soulful grooves.', imageUrl: 'https://picsum.photos/seed/artist2/600/600', genre: 'Nu-Jazz', followers: 850200, verified: true },
];

const INITIAL_ALBUMS: Album[] = [
  { id: 'a1', title: 'Midnight Mirage', artistId: '1', artistName: 'Lumina Echo', coverUrl: 'https://picsum.photos/seed/album1/600/600', releaseYear: 2024, genre: 'Dream Pop', isLiked: false },
  { id: 'a2', title: 'Silver Lining', artistId: '2', artistName: 'Velvet Horizon', coverUrl: 'https://picsum.photos/seed/album2/600/600', releaseYear: 2023, genre: 'Nu-Jazz', isLiked: true },
];

const INITIAL_TRACKS: Track[] = [
  { id: 't1', title: 'Starlight Drift', artistId: '1', artistName: 'Lumina Echo', albumId: 'a1', albumTitle: 'Midnight Mirage', duration: '3:45', plays: 1540300, likes: 82000, isLiked: false },
  { id: 't2', title: 'Neon Pulse', artistId: '1', artistName: 'Lumina Echo', albumId: 'a1', albumTitle: 'Midnight Mirage', duration: '4:12', plays: 980400, likes: 45000, isLiked: true },
  { id: 't3', title: 'Midnight Waltz', artistId: '2', artistName: 'Velvet Horizon', albumId: 'a2', albumTitle: 'Silver Lining', duration: '5:02', plays: 430200, likes: 21000, isLiked: false },
];

export default function App() {
  const [nav, setNav] = useState<NavigationState>({ view: 'home' });
  const [artists, setArtists] = useState<Artist[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [history, setHistory] = useState<NavigationState[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  // Persist Data
  useEffect(() => {
    const savedArtists = localStorage.getItem('musaic_artists');
    const savedAlbums = localStorage.getItem('musaic_albums');
    const savedTracks = localStorage.getItem('musaic_tracks');

    setArtists(savedArtists ? JSON.parse(savedArtists) : INITIAL_ARTISTS);
    setAlbums(savedAlbums ? JSON.parse(savedAlbums) : INITIAL_ALBUMS);
    setTracks(savedTracks ? JSON.parse(savedTracks) : INITIAL_TRACKS);
  }, []);

  useEffect(() => {
    if (artists.length) localStorage.setItem('musaic_artists', JSON.stringify(artists));
    if (albums.length) localStorage.setItem('musaic_albums', JSON.stringify(albums));
    if (tracks.length) localStorage.setItem('musaic_tracks', JSON.stringify(tracks));
  }, [artists, albums, tracks]);

  const navigateTo = (view: ViewType, params?: { id?: string }) => {
    setHistory(prev => [...prev, nav]);
    setNav({ view, params });
  };

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setNav(prev);
    }
  };

  const toggleLikeTrack = (id: string) => {
    setTracks(prev => prev.map(t => t.id === id ? { ...t, isLiked: !t.isLiked, likes: t.isLiked ? t.likes - 1 : t.likes + 1 } : t));
  };

  const toggleLikeAlbum = (id: string) => {
    setAlbums(prev => prev.map(a => a.id === id ? { ...a, isLiked: !a.isLiked } : a));
  };

  // UI Components
  const SidebarItem = ({ icon: Icon, label, active, onClick }: { icon: any, label: string, active: boolean, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-300 group ${
        active ? 'bg-zinc-800 text-white' : 'text-zinc-400 hover:text-white hover:bg-zinc-900/50'
      }`}
    >
      <Icon className={`w-6 h-6 ${active ? 'text-green-400' : 'group-hover:text-green-400'}`} />
      <span className="font-semibold text-sm">{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-black text-zinc-100 select-none overflow-hidden">
      {/* Sidebar */}
      <aside className="w-64 bg-black p-3 flex flex-col gap-2 border-right border-zinc-900">
        <div className="p-4 mb-2">
          <h1 className="text-2xl font-bold flex items-center gap-2 tracking-tighter">
            <Sparkles className="text-green-400 fill-green-400" />
            MUSAIC
          </h1>
        </div>

        <div className="space-y-1">
          <SidebarItem icon={Home} label="Home" active={nav.view === 'home'} onClick={() => navigateTo('home')} />
          <SidebarItem icon={Search} label="Search" active={nav.view === 'search'} onClick={() => navigateTo('search')} />
          <SidebarItem icon={Library} label="Your Library" active={nav.view === 'library'} onClick={() => navigateTo('library')} />
        </div>

        <div className="mt-6 space-y-1">
          <h3 className="px-4 text-[11px] font-bold text-zinc-500 uppercase tracking-widest mb-2">Editor Tools</h3>
          <SidebarItem icon={PlusCircle} label="Creator Hub" active={nav.view === 'creator'} onClick={() => navigateTo('creator')} />
        </div>

        <div className="mt-auto p-4 bg-zinc-900/40 rounded-3xl border border-zinc-800/50">
          <p className="text-xs text-zinc-500 font-medium">Currently Editing</p>
          <div className="flex items-center gap-3 mt-2">
            <div className="w-10 h-10 bg-gradient-to-br from-green-400 to-emerald-600 rounded-full flex items-center justify-center shadow-lg shadow-green-900/20">
              <User className="text-black w-5 h-5" />
            </div>
            <div>
              <p className="text-sm font-bold truncate">Admin Artist</p>
              <div className="flex items-center gap-1">
                <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                <p className="text-[10px] text-zinc-400">Sync Active</p>
              </div>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col bg-gradient-to-b from-zinc-900 to-black overflow-hidden relative">
        {/* Navigation Header */}
        <header className="h-16 flex items-center justify-between px-8 sticky top-0 z-50 bg-transparent">
          <div className="flex items-center gap-3">
            <button onClick={goBack} className="p-2 bg-black/40 rounded-full hover:bg-black/60 transition-colors">
              <ChevronLeft className="w-6 h-6" />
            </button>
            <button className="p-2 bg-black/40 rounded-full opacity-50 cursor-not-allowed">
              <ChevronRight className="w-6 h-6" />
            </button>
            {nav.view === 'search' && (
              <div className="relative ml-4">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
                <input 
                  type="text" 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="What do you want to listen to?" 
                  className="bg-zinc-800/80 hover:bg-zinc-800 border-none rounded-full py-2 pl-10 pr-6 w-80 text-sm focus:ring-2 focus:ring-white/10 transition-all outline-none"
                />
              </div>
            )}
          </div>

          <div className="flex items-center gap-4">
            <button className="bg-white text-black text-sm font-bold px-4 py-1.5 rounded-full hover:scale-105 transition-transform">
              Premium
            </button>
            <button className="w-9 h-9 bg-zinc-800 rounded-full flex items-center justify-center hover:bg-zinc-700 transition-colors">
              <User className="w-5 h-5" />
            </button>
          </div>
        </header>

        {/* Dynamic View Rendering */}
        <div className="flex-1 overflow-y-auto pb-32">
          {nav.view === 'home' && <HomeView artists={artists} albums={albums} navigateTo={navigateTo} />}
          {nav.view === 'artist' && <ArtistView id={nav.params?.id || ''} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'album' && <AlbumView id={nav.params?.id || ''} albums={albums} tracks={tracks} toggleLikeTrack={toggleLikeTrack} toggleLikeAlbum={toggleLikeAlbum} />}
          {nav.view === 'creator' && <CreatorHub artists={artists} setArtists={setArtists} albums={albums} setAlbums={setAlbums} tracks={tracks} setTracks={setTracks} />}
          {nav.view === 'library' && <LibraryView albums={albums} artists={artists} navigateTo={navigateTo} />}
          {nav.view === 'search' && <SearchView query={searchQuery} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} />}
        </div>

        {/* Player Visualization Footer */}
        <div className="absolute bottom-0 left-0 right-0 h-24 bg-black border-t border-zinc-900 flex items-center justify-between px-6 z-[60]">
          <div className="flex items-center gap-4 w-1/3">
            <div className="w-14 h-14 bg-zinc-800 rounded-lg overflow-hidden flex-shrink-0 shadow-lg">
              <img src="https://picsum.photos/seed/current/100/100" alt="Current" className="w-full h-full object-cover" />
            </div>
            <div>
              <p className="text-sm font-bold hover:underline cursor-pointer">Echoes of Tomorrow</p>
              <p className="text-xs text-zinc-400 hover:underline cursor-pointer">Lumina Echo</p>
            </div>
            <Heart className="w-5 h-5 text-zinc-400 hover:text-green-400 cursor-pointer ml-2 transition-colors" />
          </div>

          <div className="flex flex-col items-center gap-2 w-1/3">
            <div className="flex items-center gap-6">
              <Disc className="w-5 h-5 text-zinc-400 hover:text-white cursor-pointer" />
              <button className="w-10 h-10 bg-white rounded-full flex items-center justify-center hover:scale-105 transition-transform">
                <Play className="w-6 h-6 text-black fill-black ml-1" />
              </button>
              <MoreHorizontal className="w-5 h-5 text-zinc-400 hover:text-white cursor-pointer" />
            </div>
            <div className="w-full max-w-md flex items-center gap-2 text-[10px] text-zinc-500">
              <span>1:23</span>
              <div className="flex-1 h-1 bg-zinc-800 rounded-full overflow-hidden">
                <div className="w-1/3 h-full bg-white group hover:bg-green-400 cursor-pointer"></div>
              </div>
              <span>3:45</span>
            </div>
          </div>

          <div className="flex items-center justify-end gap-4 w-1/3">
            <Mic2 className="w-4 h-4 text-zinc-400" />
            <ListMusic className="w-4 h-4 text-zinc-400" />
            <div className="flex items-center gap-2">
              <Music className="w-4 h-4 text-zinc-400" />
              <div className="w-24 h-1 bg-zinc-800 rounded-full">
                <div className="w-3/4 h-full bg-white"></div>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

// --- Views ---

function HomeView({ artists, albums, navigateTo }: { artists: Artist[], albums: Album[], navigateTo: any }) {
  return (
    <div className="p-8">
      <h2 className="text-3xl font-extrabold mb-8">Good evening</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-10">
        {albums.slice(0, 6).map(album => (
          <div 
            key={album.id}
            onClick={() => navigateTo('album', { id: album.id })}
            className="group flex items-center gap-4 bg-zinc-800/40 hover:bg-zinc-700/60 transition-all rounded-xl overflow-hidden cursor-pointer shadow-sm"
          >
            <div className="w-20 h-20 shadow-lg">
              <img src={album.coverUrl} className="w-full h-full object-cover" />
            </div>
            <p className="font-bold text-sm flex-1">{album.title}</p>
            <div className="mr-4 w-12 h-12 bg-green-500 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0 shadow-xl">
               <Play className="text-black fill-black ml-1 w-6 h-6" />
            </div>
          </div>
        ))}
      </div>

      <SectionTitle title="Featured Artists" onClick={() => navigateTo('library')} />
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6 mb-10">
        {artists.map(artist => (
          <div 
            key={artist.id}
            onClick={() => navigateTo('artist', { id: artist.id })}
            className="bg-zinc-900/40 p-5 rounded-2xl hover:bg-zinc-800/60 transition-all duration-300 cursor-pointer group shadow-lg border border-transparent hover:border-zinc-800"
          >
            <div className="relative mb-4">
              <img src={artist.imageUrl} className="w-full aspect-square object-cover rounded-full shadow-2xl" />
              <div className="absolute bottom-2 right-2 w-12 h-12 bg-green-500 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0 shadow-xl">
                 <Play className="text-black fill-black ml-1 w-6 h-6" />
              </div>
            </div>
            <p className="font-bold truncate text-base mb-1">{artist.name}</p>
            <p className="text-zinc-500 text-sm font-medium">Artist</p>
          </div>
        ))}
      </div>

      <SectionTitle title="Recent Albums" onClick={() => navigateTo('library')} />
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6">
        {albums.map(album => (
          <div 
            key={album.id}
            onClick={() => navigateTo('album', { id: album.id })}
            className="bg-zinc-900/40 p-5 rounded-2xl hover:bg-zinc-800/60 transition-all duration-300 cursor-pointer group shadow-lg border border-transparent hover:border-zinc-800"
          >
            <div className="relative mb-4">
              <img src={album.coverUrl} className="w-full aspect-square object-cover rounded-2xl shadow-2xl" />
              <div className="absolute bottom-2 right-2 w-12 h-12 bg-green-500 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0 shadow-xl">
                 <Play className="text-black fill-black ml-1 w-6 h-6" />
              </div>
            </div>
            <p className="font-bold truncate text-base mb-1">{album.title}</p>
            <p className="text-zinc-500 text-sm font-medium">{album.artistName}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

function SectionTitle({ title, onClick }: { title: string, onClick?: () => void }) {
  return (
    <div className="flex items-center justify-between mb-6">
      <h3 className="text-2xl font-bold tracking-tight">{title}</h3>
      {onClick && <button onClick={onClick} className="text-zinc-400 font-bold text-sm hover:underline">Show all</button>}
    </div>
  );
}

function ArtistView({ id, artists, albums, tracks, navigateTo, toggleLikeTrack }: any) {
  const artist = artists.find((a: any) => a.id === id);
  if (!artist) return <div className="p-10 text-center text-zinc-500">Artist not found</div>;

  const artistAlbums = albums.filter((a: any) => a.artistId === id);
  const artistTracks = tracks.filter((t: any) => t.artistId === id).slice(0, 5);

  return (
    <div className="relative">
      <div className="h-80 bg-gradient-to-t from-zinc-900 via-zinc-800 to-zinc-700 p-8 flex flex-col justify-end relative overflow-hidden">
        <img src={artist.imageUrl} className="absolute inset-0 w-full h-full object-cover opacity-30 mix-blend-overlay" />
        <div className="relative z-10">
          <div className="flex items-center gap-2 mb-2">
            <CheckCircle2 className="w-5 h-5 text-blue-400 fill-blue-400" />
            <span className="text-sm font-bold">Verified Artist</span>
          </div>
          <h1 className="text-8xl font-black mb-6 tracking-tighter drop-shadow-2xl">{artist.name}</h1>
          <p className="text-sm font-bold text-zinc-100 drop-shadow-md">{artist.followers.toLocaleString()} monthly listeners</p>
        </div>
      </div>

      <div className="p-8 bg-zinc-900/30 backdrop-blur-xl">
        <div className="flex items-center gap-8 mb-10">
          <button className="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center hover:scale-105 transition-transform shadow-xl">
            <Play className="text-black fill-black ml-1 w-8 h-8" />
          </button>
          <button className="border border-zinc-600 px-6 py-1.5 rounded-full font-bold hover:border-white transition-colors">Follow</button>
          <MoreHorizontal className="w-8 h-8 text-zinc-400 cursor-pointer hover:text-white" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
          <div className="lg:col-span-2">
            <h3 className="text-xl font-bold mb-6">Popular</h3>
            <div className="space-y-1">
              {artistTracks.map((track: any, i: number) => (
                <TrackRow key={track.id} track={track} index={i} toggleLike={toggleLikeTrack} />
              ))}
            </div>
          </div>
          <div>
            <h3 className="text-xl font-bold mb-6">About</h3>
            <div className="bg-zinc-800/40 rounded-3xl p-6 relative group overflow-hidden cursor-pointer shadow-lg border border-zinc-800/50">
               <img src={artist.imageUrl} className="absolute inset-0 w-full h-full object-cover opacity-40 group-hover:scale-110 transition-transform duration-700" />
               <div className="relative z-10 h-64 flex flex-col justify-end">
                 <p className="text-sm line-clamp-4 font-medium mb-4 text-zinc-100">{artist.bio}</p>
                 <div className="flex items-center gap-2">
                   <div className="w-10 h-10 bg-zinc-900 rounded-full flex items-center justify-center font-bold text-xs">#{artist.genre}</div>
                 </div>
               </div>
            </div>
          </div>
        </div>

        <h3 className="text-xl font-bold mt-12 mb-6">Discography</h3>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-6">
          {artistAlbums.map((album: any) => (
            <div key={album.id} onClick={() => navigateTo('album', { id: album.id })} className="group cursor-pointer">
              <img src={album.coverUrl} className="w-full aspect-square object-cover rounded-2xl mb-3 shadow-xl hover:shadow-2xl transition-shadow" />
              <p className="font-bold truncate text-sm">{album.title}</p>
              <p className="text-zinc-500 text-xs font-medium">{album.releaseYear} • Album</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function AlbumView({ id, albums, tracks, toggleLikeTrack, toggleLikeAlbum }: any) {
  const album = albums.find((a: any) => a.id === id);
  if (!album) return <div className="p-10 text-center text-zinc-500">Album not found</div>;

  const albumTracks = tracks.filter((t: any) => t.albumId === id);

  return (
    <div className="bg-gradient-to-b from-zinc-800/50 to-zinc-900 min-h-full">
      <div className="p-8 pt-12 flex flex-col md:flex-row items-end gap-8 bg-zinc-900/30">
        <div className="w-60 h-60 md:w-72 md:h-72 shadow-[0_35px_60px_-15px_rgba(0,0,0,0.6)] rounded-3xl overflow-hidden">
          <img src={album.coverUrl} className="w-full h-full object-cover" />
        </div>
        <div className="flex flex-col">
          <span className="text-xs font-bold uppercase tracking-widest mb-2">Album</span>
          <h1 className="text-6xl md:text-8xl font-black mb-6 tracking-tight drop-shadow-xl">{album.title}</h1>
          <div className="flex items-center gap-2 text-sm font-bold">
            <span className="hover:underline cursor-pointer">{album.artistName}</span>
            <span className="text-zinc-500">•</span>
            <span>{album.releaseYear}</span>
            <span className="text-zinc-500">•</span>
            <span>{albumTracks.length} songs</span>
          </div>
        </div>
      </div>

      <div className="p-8">
        <div className="flex items-center gap-8 mb-8">
           <button className="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center hover:scale-105 transition-transform shadow-xl">
             <Play className="text-black fill-black ml-1 w-8 h-8" />
           </button>
           <Heart 
            onClick={() => toggleLikeAlbum(album.id)} 
            className={`w-8 h-8 cursor-pointer transition-colors ${album.isLiked ? 'text-green-500 fill-green-500' : 'text-zinc-400 hover:text-white'}`} 
           />
           <MoreHorizontal className="w-8 h-8 text-zinc-400 cursor-pointer hover:text-white" />
        </div>

        <div className="grid grid-cols-[16px_1fr_120px_40px] gap-4 px-4 py-2 text-zinc-400 text-xs font-bold uppercase tracking-widest border-b border-zinc-800 mb-4">
          <span>#</span>
          <span>Title</span>
          <span className="text-right flex items-center justify-end gap-1"><ThumbsUp className="w-3 h-3" /> Plays</span>
          <span className="flex items-center justify-center"><Clock className="w-3 h-3" /></span>
        </div>

        <div className="space-y-1">
          {albumTracks.map((track: any, i: number) => (
            <TrackRow key={track.id} track={track} index={i} toggleLike={toggleLikeTrack} />
          ))}
        </div>
      </div>
    </div>
  );
}

function TrackRow({ track, index, toggleLike }: { track: Track, index: number, toggleLike: (id: string) => void }) {
  return (
    <div className="group grid grid-cols-[16px_1fr_120px_40px] gap-4 items-center px-4 py-2 hover:bg-zinc-800/40 rounded-xl transition-colors cursor-pointer">
      <div className="text-zinc-400 group-hover:hidden text-sm font-medium">{index + 1}</div>
      <Play className="hidden group-hover:block w-4 h-4 fill-white text-white" />

      <div className="flex flex-col">
        <span className={`font-medium ${track.isLiked ? 'text-green-400' : 'text-zinc-100'} group-hover:text-white`}>{track.title}</span>
        <span className="text-xs text-zinc-400 group-hover:text-zinc-300">{track.artistName}</span>
      </div>

      <div className="text-zinc-400 text-sm text-right font-medium">
        {track.plays.toLocaleString()}
      </div>

      <div className="flex items-center justify-center gap-4">
        <Heart 
          onClick={(e) => { e.stopPropagation(); toggleLike(track.id); }}
          className={`w-4 h-4 transition-colors ${track.isLiked ? 'text-green-500 fill-green-500' : 'opacity-0 group-hover:opacity-100 text-zinc-400 hover:text-white'}`} 
        />
        <span className="text-zinc-400 text-sm font-medium">{track.duration}</span>
      </div>
