  );
}

function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks }: any) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track'>('artist');
  const [formData, setFormData] = useState<any>({});
  const [loading, setLoading] = useState(false);

  const handleCreate = async () => {
    setLoading(true);
    // Simulate API delay
    await new Promise(r => setTimeout(r, 800));

    if (activeTab === 'artist') {
      const newArtist: Artist = {
        id: Math.random().toString(36).substr(2, 9),
        name: formData.name || 'Unknown Artist',
        bio: formData.bio || 'New artist joining Musaic.',
        imageUrl: `https://picsum.photos/seed/${Math.random()}/600/600`,
        genre: formData.genre || 'Various',
        followers: 0,
        verified: true
      };
      setArtists([...artists, newArtist]);
    } else if (activeTab === 'album') {
      const artist = artists.find((a: any) => a.id === formData.artistId) || artists[0];
      const newAlbum: Album = {
        id: Math.random().toString(36).substr(2, 9),
        title: formData.title || 'Untitled Album',
        artistId: artist.id,
        artistName: artist.name,
        coverUrl: `https://picsum.photos/seed/${Math.random()}/600/600`,
        releaseYear: new Date().getFullYear(),
        genre: artist.genre,
        isLiked: false
      };
      setAlbums([...albums, newAlbum]);
    } else {
      const album = albums.find((a: any) => a.id === formData.albumId) || albums[0];
      const newTrack: Track = {
        id: Math.random().toString(36).substr(2, 9),
        title: formData.title || 'New Song',
        artistId: album.artistId,
        artistName: album.artistName,
        albumId: album.id,
        albumTitle: album.title,
        duration: '3:00',
        plays: 0,
        likes: 0,
        isLiked: false
      };
      setTracks([...tracks, newTrack]);
    }

    setFormData({});
    setLoading(false);
    alert('Successfully created!');
  };

  const generateBio = async () => {
    if (!formData.name) return alert('Enter artist name first');
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Write a short professional musician biography (2-3 sentences) for an artist named "${formData.name}" who plays ${formData.genre || 'music'}.`
      });
      setFormData({ ...formData, bio: response.text?.trim() });
    } catch (e) {
      console.error(e);
      setFormData({ ...formData, bio: "Failed to generate bio, please try again." });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-8 max-w-2xl mx-auto">
      <div className="flex items-center gap-3 mb-2">
        <Sparkles className="text-green-400 fill-green-400 w-8 h-8" />
        <h2 className="text-4xl font-black tracking-tighter">Creator Hub</h2>
      </div>
      <p className="text-zinc-500 font-medium mb-8">Bring your music vision to life by adding metadata to Musaic.</p>

      <div className="flex gap-2 p-1 bg-zinc-900 rounded-2xl mb-8 border border-zinc-800">
        {['artist', 'album', 'track'].map((t: any) => (
          <button 
            key={t}
            onClick={() => setActiveTab(t)}
            className={`flex-1 py-2.5 rounded-xl font-bold text-sm transition-all capitalize ${activeTab === t ? 'bg-zinc-700 text-white shadow-lg' : 'text-zinc-400 hover:text-white'}`}
          >
            {t}
          </button>
        ))}
      </div>

      <div className="space-y-6 bg-zinc-900/40 p-8 rounded-3xl border border-zinc-800/50 backdrop-blur-md">
        {activeTab === 'artist' && (
          <>
            <div className="space-y-2">
              <label className="text-sm font-bold text-zinc-300">Artist Name</label>
              <input 
                type="text" 
                value={formData.name || ''} 
                onChange={e => setFormData({...formData, name: e.target.value})}
                placeholder="e.g. Neon Horizon" 
                className="w-full bg-zinc-800/50 border border-zinc-700 rounded-xl p-3 focus:ring-2 focus:ring-green-400 outline-none transition-all"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-bold text-zinc-300">Genre</label>
              <input 
                type="text" 
                value={formData.genre || ''} 
                onChange={e => setFormData({...formData, genre: e.target.value})}
                placeholder="e.g. Synth-wave" 
                className="w-full bg-zinc-800/50 border border-zinc-700 rounded-xl p-3 focus:ring-2 focus:ring-green-400 outline-none transition-all"
              />
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center">
                <label className="text-sm font-bold text-zinc-300">Biography</label>
                <button 
                  onClick={generateBio}
                  className="text-xs font-bold text-green-400 flex items-center gap-1 hover:underline"
                >
                  <Sparkles className="w-3 h-3" /> Magic Bio
                </button>
              </div>
              <textarea 
                value={formData.bio || ''} 
                onChange={e => setFormData({...formData, bio: e.target.value})}
                rows={4} 
                placeholder="Tell the world about this artist..." 
                className="w-full bg-zinc-800/50 border border-zinc-700 rounded-xl p-3 focus:ring-2 focus:ring-green-400 outline-none transition-all"
              />
            </div>
          </>
        )}

        {activeTab === 'album' && (
          <>
            <div className="space-y-2">
              <label className="text-sm font-bold text-zinc-300">Album Title</label>
              <input 
                type="text" 
                value={formData.title || ''} 
                onChange={e => setFormData({...formData, title: e.target.value})}
                placeholder="e.g. Electric Dreams" 
                className="w-full bg-zinc-800/50 border border-zinc-700 rounded-xl p-3 focus:ring-2 focus:ring-green-400 outline-none transition-all"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-bold text-zinc-300">Artist</label>
              <select 
                value={formData.artistId || ''} 
                onChange={e => setFormData({...formData, artistId: e.target.value})}
                className="w-full bg-zinc-800/50 border border-zinc-700 rounded-xl p-3 focus:ring-2 focus:ring-green-400 outline-none transition-all appearance-none"
              >
                <option value="">Select Artist</option>
                {artists.map((a: any) => <option key={a.id} value={a.id}>{a.name}</option>)}
              </select>
            </div>
          </>
        )}

        {activeTab === 'track' && (
          <>
            <div className="space-y-2">
              <label className="text-sm font-bold text-zinc-300">Track Title</label>
              <input 
                type="text" 
                value={formData.title || ''} 
                onChange={e => setFormData({...formData, title: e.target.value})}
                placeholder="e.g. Midnight Highway" 
                className="w-full bg-zinc-800/50 border border-zinc-700 rounded-xl p-3 focus:ring-2 focus:ring-green-400 outline-none transition-all"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-bold text-zinc-300">Album</label>
              <select 
                value={formData.albumId || ''} 
                onChange={e => setFormData({...formData, albumId: e.target.value})}
                className="w-full bg-zinc-800/50 border border-zinc-700 rounded-xl p-3 focus:ring-2 focus:ring-green-400 outline-none transition-all appearance-none"
              >
                <option value="">Select Album</option>
                {albums.map((a: any) => <option key={a.id} value={a.id}>{a.title} ({a.artistName})</option>)}
              </select>
            </div>
          </>
        )}

        <button 
          onClick={handleCreate}
          disabled={loading}
          className="w-full py-4 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-xl shadow-white/5"
        >
          {loading ? 'Creating...' : `Publish ${activeTab}`}
        </button>
      </div>
    </div>
  );
}

