function SearchView({ query, artists, albums, tracks, navigateTo }: any) {
  const filteredArtists = artists.filter((a: any) => a.name.toLowerCase().includes(query.toLowerCase()));
  const filteredAlbums = albums.filter((a: any) => a.title.toLowerCase().includes(query.toLowerCase()));
  const filteredTracks = tracks.filter((t: any) => t.title.toLowerCase().includes(query.toLowerCase()));

  if (!query) {
    return (
      <div className="p-8">
        <SectionTitle title="Browse All" />
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-6">
          {['Pop', 'Rock', 'Electronic', 'Jazz', 'Chill', 'Workout', 'Party', 'Acoustic'].map(genre => (
            <div key={genre} className="bg-zinc-800/80 aspect-video rounded-3xl p-6 relative overflow-hidden group cursor-pointer shadow-lg hover:bg-zinc-700 transition-colors">
              <span className="text-2xl font-black relative z-10">{genre}</span>
              <img src={`https://picsum.photos/seed/${genre}/300/200`} className="absolute bottom-0 right-0 w-32 h-32 rotate-[25deg] translate-x-4 translate-y-4 group-hover:scale-110 transition-transform shadow-2xl" />
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-8">
      {filteredArtists.length > 0 && (
        <div className="mb-10">
          <SectionTitle title="Artists" />
          <div className="flex gap-6 overflow-x-auto pb-4 scrollbar-hide">
            {filteredArtists.map((a: any) => (
              <div key={a.id} onClick={() => navigateTo('artist', { id: a.id })} className="flex-shrink-0 w-48 bg-zinc-900/40 p-5 rounded-2xl hover:bg-zinc-800/60 transition-all cursor-pointer">
                <img src={a.imageUrl} className="w-full aspect-square object-cover rounded-full mb-3 shadow-lg" />
                <p className="font-bold truncate text-sm">{a.name}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {filteredTracks.length > 0 && (
        <div className="mb-10">
          <SectionTitle title="Songs" />
          <div className="space-y-1">
            {filteredTracks.map((t: any, i: number) => (
              <TrackRow key={t.id} track={t} index={i} toggleLike={() => {}} />
            ))}
          </div>
        </div>
      )}

      {filteredAlbums.length > 0 && (
        <div>
          <SectionTitle title="Albums" />
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-6">
            {filteredAlbums.map((a: any) => (
              <div key={a.id} onClick={() => navigateTo('album', { id: a.id })} className="bg-zinc-900/40 p-5 rounded-2xl hover:bg-zinc-800/60 transition-all cursor-pointer">
                <img src={a.coverUrl} className="w-full aspect-square object-cover rounded-xl mb-3 shadow-lg" />
                <p className="font-bold truncate text-sm">{a.title}</p>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

