export default function App() {
  const [nav, setNav] = useState<NavigationState>({ view: 'home' });
  const [artists, setArtists] = useState<Artist[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [history, setHistory] = useState<NavigationState[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  // Persist Data
  useEffect(() => {
    const savedArtists = localStorage.getItem('musaic_artists');
    const savedAlbums = localStorage.getItem('musaic_albums');
    const savedTracks = localStorage.getItem('musaic_tracks');

    setArtists(savedArtists ? JSON.parse(savedArtists) : INITIAL_ARTISTS);
    setAlbums(savedAlbums ? JSON.parse(savedAlbums) : INITIAL_ALBUMS);
    setTracks(savedTracks ? JSON.parse(savedTracks) : INITIAL_TRACKS);
  }, []);

  useEffect(() => {
    if (artists.length) localStorage.setItem('musaic_artists', JSON.stringify(artists));
    if (albums.length) localStorage.setItem('musaic_albums', JSON.stringify(albums));
    if (tracks.length) localStorage.setItem('musaic_tracks', JSON.stringify(tracks));
  }, [artists, albums, tracks]);

  const navigateTo = (view: ViewType, params?: { id?: string }) => {
    setHistory(prev => [...prev, nav]);
    setNav({ view, params });
  };

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setNav(prev);
    }
  };

  const toggleLikeTrack = (id: string) => {
    setTracks(prev => prev.map(t => t.id === id ? { ...t, isLiked: !t.isLiked, likes: t.isLiked ? t.likes - 1 : t.likes + 1 } : t));
  };

  const toggleLikeAlbum = (id: string) => {
    setAlbums(prev => prev.map(a => a.id === id ? { ...a, isLiked: !a.isLiked } : a));
  };

  // Sidebar item component
  const SidebarItem = ({ icon: Icon, label, active, onClick }: { icon: any, label: string, active: boolean, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-300 group ${
        active ? 'bg-zinc-800 text-white' : 'text-zinc-400 hover:text-white hover:bg-zinc-900/50'
      }`}
    >
      <Icon className={`w-6 h-6 ${active ? 'text-green-400' : 'group-hover:text-green-400'}`} />
      <span className="font-semibold text-sm">{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-black text-zinc-100 select-none overflow-hidden">
      {/* Sidebar */}
      <aside className="w-64 bg-black p-3 flex flex-col gap-2 border-right border-zinc-900">
        <div className="p-4 mb-2">
          <h1 className="text-2xl font-bold flex items-center gap-2 tracking-tighter">
            <Sparkles className="text-green-400 fill-green-400" />
            MUSAIC
          </h1>
        </div>

        <div className="space-y-1">
          <SidebarItem icon={Home} label="Home" active={nav.view === 'home'} onClick={() => navigateTo('home')} />
          <SidebarItem icon={Search} label="Search" active={nav.view === 'search'} onClick={() => navigateTo('search')} />
          <SidebarItem icon={Library} label="Your Library" active={nav.view === 'library'} onClick={() => navigateTo('library')} />
        </div>

        <div className="mt-6 space-y-1">
          <h3 className="px-4 text-[11px] font-bold text-zinc-500 uppercase tracking-widest mb-2">Editor Tools</h3>
          <SidebarItem icon={PlusCircle} label="Creator Hub" active={nav.view === 'creator'} onClick={() => navigateTo('creator')} />
        </div>

        <div className="mt-auto p-4 bg-zinc-900/40 rounded-3xl border border-zinc-800/50">
          <p className="text-xs text-zinc-500 font-medium">Currently Editing</p>
          <div className="flex items-center gap-3 mt-2">
            <div className="w-10 h-10 bg-gradient-to-br from-green-400 to-emerald-600 rounded-full flex items-center justify-center shadow-lg shadow-green-900/20">
              <User className="text-black w-5 h-5" />
            </div>
            <div>
              <p className="text-sm font-bold truncate">Admin Artist</p>
              <div className="flex items-center gap-1">
                <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                <p className="text-[10px] text-zinc-400">Sync Active</p>
              </div>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col bg-gradient-to-b from-zinc-900 to-black overflow-hidden relative">
        {/* Navigation Header */}
        <header className="h-16 flex items-center justify-between px-8 sticky top-0 z-50 bg-transparent">
          <div className="flex items-center gap-3">
            <button onClick={goBack} className="p-2 bg-black/40 rounded-full hover:bg-black/60 transition-colors">
              <ChevronLeft className="w-6 h-6" />
            </button>
            <button className="p-2 bg-black/40 rounded-full opacity-50 cursor-not-allowed">
              <ChevronRight className="w-6 h-6" />
            </button>
            {nav.view === 'search' && (
              <div className="relative ml-4">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
                <input 
                  type="text" 
                  value={searchQuery}
