} from 'lucide-react';
import { GoogleGenAI } from '@google/genai';
import { Artist, Album, Track, ViewType, NavigationState } from './types';

// --- Interfaces for Props ---

interface HomeViewProps {
  artists: Artist[];
  albums: Album[];
  navigateTo: (view: ViewType, params?: { id?: string }) => void;
}

interface ArtistViewProps {
  id: string;
  artists: Artist[];
  albums: Album[];
  tracks: Track[];
  navigateTo: (view: ViewType, params?: { id?: string }) => void;
  toggleLikeTrack: (id: string) => void;
}

interface AlbumViewProps {
  id: string;
  albums: Album[];
  tracks: Track[];
  toggleLikeTrack: (id: string) => void;
  toggleLikeAlbum: (id: string) => void;
}

interface CreatorHubProps {
  artists: Artist[];
  setArtists: React.Dispatch<React.SetStateAction<Artist[]>>;
  albums: Album[];
  setAlbums: React.Dispatch<React.SetStateAction<Album[]>>;
  tracks: Track[];
  setTracks: React.Dispatch<React.SetStateAction<Track[]>>;
}

interface LibraryViewProps {
  albums: Album[];
  artists: Artist[];
  navigateTo: (view: ViewType, params?: { id?: string }) => void;
}

interface SearchViewProps {
  query: string;
  artists: Artist[];
  albums: Album[];
  tracks: Track[];
  navigateTo: (view: ViewType, params?: { id?: string }) => void;
}

interface TrackRowProps {
  track: Track;
  index: number;
  toggleLike: (id: string) => void;
}

// --- Helper Functions ---

const formatNumber = (num: number) => {
  if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
  return num.toString();
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// --- Sub-components ---

const TrackRow: React.FC<TrackRowProps> = ({ track, index, toggleLike }) => {
  return (
    <div className="group grid grid-cols-[16px_1fr_120px_40px] gap-4 items-center px-4 py-2 hover:bg-zinc-800/40 rounded-xl transition-colors cursor-pointer">
      <div className="text-zinc-400 group-hover:hidden text-sm font-medium">{index + 1}</div>
      <Play className="hidden group-hover:block w-4 h-4 fill-white text-white" />

      <div className="flex flex-col">
        <span className={`font-medium ${track.isLiked ? 'text-green-400' : 'text-zinc-100'} group-hover:text-white`}>{track.title}</span>
        <span className="text-xs text-zinc-400 group-hover:text-zinc-300">{track.artistName}</span>
      </div>

      <div className="text-zinc-400 text-sm text-right font-medium">
        {formatNumber(track.plays)}
      </div>

      <div className="flex items-center justify-center gap-4">
        <Heart 
          onClick={(e) => { e.stopPropagation(); toggleLike(track.id); }}
          className={`w-4 h-4 transition-colors ${track.isLiked ? 'text-green-500 fill-green-500' : 'opacity-0 group-hover:opacity-100 text-zinc-400 hover:text-white'}`} 
        />
        <span className="text-zinc-400 text-sm font-medium">{track.duration}</span>
      </div>
    </div>
  );
};

// --- Main App ---

export default function App() {
  const [nav, setNav] = useState<NavigationState>({ view: 'home' });
  const [artists, setArtists] = useState<Artist[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [history, setHistory] = useState<NavigationState[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  // Persist Data
  useEffect(() => {
    const savedArtists = localStorage.getItem('musaic_artists');
    const savedAlbums = localStorage.getItem('musaic_albums');
    const savedTracks = localStorage.getItem('musaic_tracks');

    if (savedArtists) setArtists(JSON.parse(savedArtists));
    if (savedAlbums) setAlbums(JSON.parse(savedAlbums));
    if (savedTracks) setTracks(JSON.parse(savedTracks));
  }, []);

  useEffect(() => {
    localStorage.setItem('musaic_artists', JSON.stringify(artists));
    localStorage.setItem('musaic_albums', JSON.stringify(albums));
