              <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
              <span className="text-[10px] text-zinc-400 uppercase font-bold">Live</span>
            </div>
          </div>
          <div className="space-y-1 text-xs text-zinc-300">
            <div className="flex justify-between"><span>Artists:</span> <span>{artists.length}</span></div>
            <div className="flex justify-between"><span>Albums:</span> <span>{albums.length}</span></div>
            <div className="flex justify-between"><span>Tracks:</span> <span>{tracks.length}</span></div>
