              <button onClick={() => navigateTo('creator')} className="mt-6 bg-white text-black px-6 py-2 rounded-full font-bold hover:scale-105 transition-transform">
                Start Creating
              </button>
            </div>
          )}
        </div>

        {/* Mini Player */}
        <div className="absolute bottom-0 left-0 right-0 h-24 bg-black/90 backdrop-blur-lg border-t border-zinc-900 flex items-center justify-between px-6 z-[60]">
           <div className="flex items-center gap-4 w-1/3">
            <div className="w-14 h-14 bg-zinc-800 rounded-xl overflow-hidden shadow-lg">
