// --- Creator Hub Overhaul ---

function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks }: CreatorHubProps) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>('artist');
  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: 0, artistVerified: true, artistImg: '',
    albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumSelectedTracks: [],
    trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: 0, trackLikes: 0
  });
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetForm = () => {
    setFormData({
      artistName: '', artistBio: '', artistGenre: '', artistFollowers: 0, artistVerified: true, artistImg: '',
      albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumSelectedTracks: [],
      trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: 0, trackLikes: 0
    });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const base64 = await fileToBase64(file);
      const field = activeTab === 'artist' ? 'artistImg' : 'albumImg';
      setFormData({ ...formData, [field]: base64 });
    }
  };

  const createArtist = () => {
    if (!formData.artistName) return;
    const newArtist: Artist = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.artistName,
      bio: formData.artistBio || 'A rising star on Musaic.',
      imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
      genre: formData.artistGenre || 'Various',
      followers: Number(formData.artistFollowers) || 0,
      verified: formData.artistVerified
    };
    setArtists([...artists, newArtist]);
    resetForm();
    alert('Artist created!');
  };

  const createAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId)!;
    const albumId = Math.random().toString(36).substr(2, 9);

    const newAlbum: Album = {
      id: albumId,
      title: formData.albumTitle,
      artistId: artist.id,
      artistName: artist.name,
      coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`,
      releaseYear: Number(formData.albumYear) || new Date().getFullYear(),
      genre: formData.albumGenre || artist.genre,
      isLiked: false
    };

    // Update tracks that were selected to belong to this new album
    if (formData.albumSelectedTracks.length > 0) {
      setTracks(prev => prev.map(t => 
        formData.albumSelectedTracks.includes(t.id) ? { ...t, albumId: albumId, albumTitle: newAlbum.title } : t
      ));
    }

    setAlbums([...albums, newAlbum]);
    resetForm();
    alert('Album created!');
  };

  const createTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId)!;
    const album = albums.find(a => a.id === formData.trackAlbumId);

    const newTrack: Track = {
      id: Math.random().toString(36).substr(2, 9),
      title: formData.trackTitle,
      artistId: artist.id,
      artistName: artist.name,
      albumId: album?.id || 'single',
      albumTitle: album?.title || 'Single',
      duration: formData.trackDuration,
      plays: Number(formData.trackPlays) || 0,
      likes: Number(formData.trackLikes) || 0,
      isLiked: false
    };
    setTracks([...tracks, newTrack]);
    resetForm();
    alert('Track created!');
  };

  const deleteItem = (type: 'artist' | 'album' | 'track', id: string) => {
    if (type === 'artist') setArtists(prev => prev.filter(a => a.id !== id));
    if (type === 'album') setAlbums(prev => prev.filter(a => a.id !== id));
    if (type === 'track') setTracks(prev => prev.filter(t => t.id !== id));
  };

  const generateAIBio = async () => {
    if (!formData.artistName) return alert("Enter artist name first");
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Write a cool, 2-sentence Spotify-style biography for an artist named "${formData.artistName}" who plays ${formData.artistGenre || 'various music styles'}.`
      });
      setFormData({ ...formData, artistBio: response.text?.trim() });
    } catch (e) {
      console.error(e);
      setFormData({ ...formData, artistBio: "A mysterious artist with a sound like no other." });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-8 max-w-4xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h2 className="text-4xl font-black tracking-tight mb-2">Creator Hub</h2>
          <p className="text-zinc-500 font-medium">Build, manage, and scale your music library.</p>
        </div>
        <div className="flex gap-2 p-1 bg-zinc-900 rounded-2xl border border-zinc-800">
          {['artist', 'album', 'track', 'manage'].map((t) => (
            <button 
              key={t}
              onClick={() => { setActiveTab(t as any); resetForm(); }}
              className={`px-6 py-2 rounded-xl font-bold text-sm transition-all capitalize ${activeTab === t ? 'bg-zinc-700 text-white shadow-lg' : 'text-zinc-400 hover:text-white'}`}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-6">
            {/* Form Fields - Generic styling for reuse */}
            <div className="bg-zinc-900/50 backdrop-blur-md p-8 rounded-[2.5rem] border border-zinc-800/50 space-y-6 shadow-2xl">
              {activeTab === 'artist' && (
                <>
                  <InputGroup label="Artist Name" placeholder="e.g. Moonlight Drive" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                  <div className="grid grid-cols-2 gap-4">
                    <InputGroup label="Main Genre" placeholder="e.g. Synthpop" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                    <InputGroup label="Followers" type="number" value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                  </div>
                  <div className="space-y-2">
                    <div className="flex justify-between items-center">
                      <label className="text-sm font-bold text-zinc-400">Artist Biography</label>
                      <button onClick={generateAIBio} disabled={loading} className="text-xs font-bold text-green-400 flex items-center gap-1 hover:underline disabled:opacity-50">
                        {loading ? 'Thinking...' : <><Sparkles className="w-3 h-3" /> AI Bio Generator</>}
                      </button>
                    </div>
                    <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} rows={3} placeholder="Write something about the artist..." className="w-full bg-zinc-800/40 border border-zinc-700/50 rounded-2xl p-4 focus:ring-2 focus:ring-green-400 outline-none transition-all resize-none text-sm" />
                  </div>
                  <div className="flex items-center gap-4">
                    <label className="flex items-center gap-2 cursor-pointer group">
                      <div className={`w-5 h-5 rounded border border-zinc-700 flex items-center justify-center transition-colors ${formData.artistVerified ? 'bg-green-500 border-green-500' : 'bg-transparent'}`}>
                        {formData.artistVerified && <Check className="w-3 h-3 text-black font-bold" />}
                      </div>
                      <input type="checkbox" className="hidden" checked={formData.artistVerified} onChange={e => setFormData({...formData, artistVerified: e.target.checked})} />
                      <span className="text-sm font-bold text-zinc-400 group-hover:text-white transition-colors">Verified Artist Account</span>
                    </label>
                  </div>
                  <button onClick={createArtist} className="w-full py-4 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] active:scale-[0.98] transition-all shadow-xl">Create Artist</button>
                </>
              )}

              {activeTab === 'album' && (
                <>
                  <InputGroup label="Album Title" placeholder="e.g. Digital Sunrise" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-zinc-400">Artist</label>
                    <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-zinc-800/40 border border-zinc-700/50 rounded-2xl p-4 focus:ring-2 focus:ring-green-400 outline-none appearance-none">
                      <option value="">Select Artist</option>
                      {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <InputGroup label="Release Year" type="number" value={formData.albumYear} onChange={v => setFormData({...formData, albumYear: v})} />
                    <InputGroup label="Album Genre" placeholder="e.g. Electronic" value={formData.albumGenre} onChange={v => setFormData({...formData, albumGenre: v})} />
                  </div>

                  {/* Track Selection within Album */}
                  <div className="space-y-3">
                    <label className="text-sm font-bold text-zinc-400 flex items-center justify-between">
                      Select Tracks for this Album
                      <span className="text-[10px] text-zinc-500 font-bold uppercase">Only shows unassigned tracks</span>
                    </label>
                    <div className="max-h-48 overflow-y-auto space-y-1 pr-2 custom-scrollbar">
                      {tracks.filter(t => t.albumId === 'single' || !t.albumId).map(t => (
                        <div key={t.id} onClick={() => {
                          const exists = formData.albumSelectedTracks.includes(t.id);
                          setFormData({...formData, albumSelectedTracks: exists ? formData.albumSelectedTracks.filter((id: string) => id !== t.id) : [...formData.albumSelectedTracks, t.id]});
                        }} className={`flex items-center justify-between p-3 rounded-xl border cursor-pointer transition-all ${formData.albumSelectedTracks.includes(t.id) ? 'bg-green-500/10 border-green-500/50 text-white' : 'bg-zinc-800/20 border-zinc-700/50 text-zinc-500'}`}>
                          <div className="flex items-center gap-3">
                            <Music className="w-4 h-4" />
                            <div className="text-sm font-bold">{t.title} <span className="text-[10px] opacity-60 ml-2">by {t.artistName}</span></div>
                          </div>
                          {formData.albumSelectedTracks.includes(t.id) && <Check className="w-4 h-4 text-green-500" />}
                        </div>
                      ))}
                      {tracks.filter(t => t.albumId === 'single' || !t.albumId).length === 0 && <p className="text-xs text-zinc-500 italic text-center p-4">No unassigned tracks found. Create some in the Track tab!</p>}
                    </div>
                  </div>

                  <button onClick={createAlbum} className="w-full py-4 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] active:scale-[0.98] transition-all shadow-xl">Publish Album</button>
                </>
              )}

              {activeTab === 'track' && (
                <>
                  <InputGroup label="Track Title" placeholder="e.g. Midnight Highway" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-zinc-400">Artist</label>
                      <select value={formData.trackArtistId} onChange={e => {
                        const artistId = e.target.value;
                        setFormData({...formData, trackArtistId: artistId, trackAlbumId: ''});
                      }} className="w-full bg-zinc-800/40 border border-zinc-700/50 rounded-2xl p-4 focus:ring-2 focus:ring-green-400 outline-none appearance-none">
                        <option value="">Select Artist</option>
                        {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-zinc-400">Album (Optional)</label>
                      <select value={formData.trackAlbumId} onChange={e => setFormData({...formData, trackAlbumId: e.target.value})} className="w-full bg-zinc-800/40 border border-zinc-700/50 rounded-2xl p-4 focus:ring-2 focus:ring-green-400 outline-none appearance-none">
                        <option value="">No Album (Single)</option>
                        {albums.filter(a => a.artistId === formData.trackArtistId).map(a => <option key={a.id} value={a.id}>{a.title}</option>)}
                      </select>
                    </div>
                  </div>
                  <div className="grid grid-cols-3 gap-4">
                    <InputGroup label="Duration" placeholder="3:30" value={formData.trackDuration} onChange={v => setFormData({...formData, trackDuration: v})} />
                    <InputGroup label="Plays" type="number" value={formData.trackPlays} onChange={v => setFormData({...formData, trackPlays: v})} />
                    <InputGroup label="Likes" type="number" value={formData.trackLikes} onChange={v => setFormData({...formData, trackLikes: v})} />
                  </div>
                  <button onClick={createTrack} className="w-full py-4 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] active:scale-[0.98] transition-all shadow-xl">Release Track</button>
                </>
              )}
            </div>
          </div>
        )}

        {/* Media Preview / Upload sidebar for Forms */}
        {activeTab !== 'manage' && (
          <div className="space-y-6">
            <div className="bg-zinc-900/50 backdrop-blur-md p-6 rounded-[2.5rem] border border-zinc-800/50 text-center shadow-xl">
              <h3 className="text-sm font-bold text-zinc-400 mb-4 uppercase tracking-widest">Media Preview</h3>
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="w-full aspect-square bg-zinc-800/50 rounded-[2rem] border-2 border-dashed border-zinc-700 flex flex-col items-center justify-center cursor-pointer hover:border-green-500/50 hover:bg-zinc-800/80 transition-all group overflow-hidden relative"
              >
                {(activeTab === 'artist' ? formData.artistImg : formData.albumImg) ? (
                  <img src={activeTab === 'artist' ? formData.artistImg : formData.albumImg} className="w-full h-full object-cover" />
                ) : (
                  <>
                    <ImageIcon className="w-12 h-12 text-zinc-600 mb-2 group-hover:scale-110 transition-transform" />
                    <p className="text-xs font-bold text-zinc-500">Click to Upload Cover</p>
                  </>
                )}
                <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                   <Upload className="w-8 h-8 text-white" />
                </div>
              </div>
              <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
              <p className="mt-4 text-[10px] text-zinc-500 leading-relaxed px-2">High resolution PNG or JPEG recommended. Max 2MB for storage performance.</p>
            </div>

            <div className="bg-gradient-to-br from-green-500/10 to-emerald-500/10 p-6 rounded-[2.5rem] border border-green-500/20">
               <div className="flex items-center gap-3 mb-3">
                 <div className="p-2 bg-green-500 rounded-lg">
                   <Sparkles className="w-4 h-4 text-black" />
                 </div>
                 <h4 className="font-bold text-sm">Pro Tip</h4>
               </div>
               <p className="text-xs text-zinc-400 leading-relaxed">
                 Albums created without tracks will appear empty. You can add tracks later by selecting this album in the "Track" tab.
               </p>
            </div>
          </div>
        )}

        {/* Management Tab Content */}
        {activeTab === 'manage' && (
          <div className="col-span-1 md:col-span-3 space-y-8">
            <ManagementSection title="Artists" items={artists} onDelete={id => deleteItem('artist', id)} icon={User} />
            <ManagementSection title="Albums" items={albums} onDelete={id => deleteItem('album', id)} icon={Disc} />
            <ManagementSection title="Tracks" items={tracks} onDelete={id => deleteItem('track', id)} icon={Music} />

            <div className="p-8 bg-red-500/5 border border-red-500/20 rounded-[2.5rem] flex items-center justify-between">
              <div>
                <h4 className="text-lg font-bold text-red-400">Danger Zone</h4>
                <p className="text-sm text-zinc-500">Reset your entire library to initial state. This cannot be undone.</p>
              </div>
              <button 
                onClick={() => {
                   if(confirm('Are you sure you want to clear EVERYTHING?')) {
                     setArtists([]); setAlbums([]); setTracks([]);
                     localStorage.clear();
                     window.location.reload();
                   }
                }}
                className="px-6 py-2 bg-red-500 text-white font-bold rounded-xl hover:bg-red-600 transition-colors"
              >
                Wipe All Data
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

const InputGroup = ({ label, type = 'text', placeholder, value, onChange }: { label: string, type?: string, placeholder?: string, value: any, onChange: (v: string) => void }) => (
  <div className="space-y-2">
    <label className="text-sm font-bold text-zinc-400">{label}</label>
    <input 
      type={type} 
      value={value} 
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder} 
      className="w-full bg-zinc-800/40 border border-zinc-700/50 rounded-2xl p-4 focus:ring-2 focus:ring-green-400 outline-none transition-all text-sm"
    />
  </div>
);

const ManagementSection = ({ title, items, onDelete, icon: Icon }: { title: string, items: any[], onDelete: (id: string) => void, icon: any }) => (
  <div className="space-y-4">
    <h3 className="text-xl font-bold flex items-center gap-2">
      <Icon className="w-5 h-5 text-zinc-500" />
      {title} <span className="text-sm text-zinc-600 font-medium">({items.length})</span>
    </h3>
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
      {items.map(item => (
        <div key={item.id} className="bg-zinc-900/40 p-4 rounded-3xl border border-zinc-800/50 flex items-center gap-4 group">
          <div className="w-12 h-12 bg-zinc-800 rounded-xl overflow-hidden shadow-md flex-shrink-0">
            <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/100/100`} className="w-full h-full object-cover" />
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-bold truncate">{item.name || item.title}</p>
            <p className="text-[10px] text-zinc-500 font-bold uppercase">{item.genre || item.artistName || 'Creator Item'}</p>
          </div>
          <button onClick={() => onDelete(item.id)} className="p-2 text-zinc-600 hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-all opacity-0 group-hover:opacity-100">
            <Trash2 className="w-4 h-4" />
          </button>
        </div>
      ))}
      {items.length === 0 && <p className="text-xs text-zinc-500 italic p-4">No {title.toLowerCase()} yet.</p>}
    </div>
  </div>
);

