  const artistTracks = tracks.filter((t) => t.artistId === id).slice(0, 5);

  return (
    <div className="relative">
      <div className="h-80 bg-zinc-800 p-8 flex flex-col justify-end relative overflow-hidden">
        <img src={artist.imageUrl} className="absolute inset-0 w-full h-full object-cover" alt={artist.name} />
