          <h1 className="text-7xl md:text-9xl font-black mb-6 tracking-tighter drop-shadow-2xl">{artist.name}</h1>
          <p className="text-sm font-bold text-zinc-100 drop-shadow-md">{artist.followers.toLocaleString()} monthly listeners</p>
        </div>
      </div>

      <div className="p-8 bg-black">
        <div className="flex items-center gap-8 mb-10">
          <button className="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center hover:scale-105 transition-transform shadow-xl">
            <Play className="text-black fill-black ml-1 w-8 h-8" />
          </button>
          <button className="border border-zinc-600 px-6 py-1.5 rounded-full font-bold hover:border-white transition-colors">Follow</button>
          <MoreHorizontal className="w-8 h-8 text-zinc-400 cursor-pointer hover:text-white" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
          <div className="lg:col-span-2">
            <h3 className="text-2xl font-bold mb-6">Popular</h3>
            <div className="space-y-1">
              {artistTracks.map((track, i) => (
                <TrackRow key={track.id} track={track} index={i} toggleLike={toggleLikeTrack} />
              ))}
            </div>
          </div>
          <div className="space-y-8">
            <h3 className="text-2xl font-bold">About</h3>
            <div className="bg-zinc-800/40 rounded-[2.5rem] p-8 relative group overflow-hidden shadow-lg border border-zinc-800/50">
               <div className="relative z-10 min-h-[200px] flex flex-col">
                 <p className="text-zinc-100 font-medium leading-relaxed mb-6">{artist.bio}</p>
                 <div className="mt-auto flex items-center gap-2">
