        </div>

        <h3 className="text-2xl font-bold mt-16 mb-8">Discography</h3>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-6">
          {artistAlbums.map((album) => (
            <div key={album.id} onClick={() => navigateTo('album', { id: album.id })} className="group cursor-pointer">
              <img src={album.coverUrl} className="w-full aspect-square object-cover rounded-3xl mb-3 shadow-xl hover:shadow-2xl transition-all" alt={album.title} />
