           <MoreHorizontal className="w-8 h-8 text-zinc-400 cursor-pointer hover:text-white" />
        </div>

        <div className="grid grid-cols-[16px_1fr_120px_40px] gap-4 px-6 py-3 text-zinc-500 text-[10px] font-black uppercase tracking-[0.15em] border-b border-zinc-800/50 mb-4">
          <span>#</span>
          <span>Title</span>
          <span className="text-right">Plays</span>
          <span className="flex justify-center"><Clock className="w-4 h-4" /></span>
        </div>

        <div className="space-y-1">
          {albumTracks.map((track, i) => (
            <TrackRow key={track.id} track={track} index={i} toggleLike={toggleLikeTrack} />
          ))}
          {albumTracks.length === 0 && <p className="text-zinc-500 italic text-sm p-8 text-center bg-zinc-900/20 rounded-3xl border border-dashed border-zinc-800">This album has no tracks yet. Add some in the Creator Hub.</p>}
        </div>
      </div>
    </div>
  );
}

