function SearchView({ query, artists, albums, tracks, navigateTo }: SearchViewProps) {
  const filteredArtists = artists.filter((a) => a.name.toLowerCase().includes(query.toLowerCase()));
  const filteredAlbums = albums.filter((a) => a.title.toLowerCase().includes(query.toLowerCase()));
