  return (
    <div className="p-8">
      {filteredArtists.length > 0 && (
        <div className="mb-12">
          <SectionTitle title="Artists" />
          <div className="flex gap-6 overflow-x-auto pb-4 custom-scrollbar">
            {filteredArtists.map((a) => (
              <div key={a.id} onClick={() => navigateTo('artist', { id: a.id })} className="flex-shrink-0 w-48 bg-zinc-900/40 p-5 rounded-[2rem] hover:bg-zinc-800/60 transition-all cursor-pointer">
                <img src={a.imageUrl} className="w-full aspect-square object-cover rounded-full mb-3 shadow-lg" alt={a.name} />
                <p className="font-bold truncate text-sm">{a.name}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {filteredTracks.length > 0 && (
        <div className="mb-12">
          <SectionTitle title="Tracks" />
          <div className="space-y-1">
            {filteredTracks.map((t, i) => (
              <TrackRow key={t.id} track={t} index={i} toggleLike={() => {}} />
            ))}
          </div>
        </div>
      )}

      {filteredAlbums.length > 0 && (
        <div>
          <SectionTitle title="Albums" />
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-6">
            {filteredAlbums.map((a) => (
              <div key={a.id} onClick={() => navigateTo('album', { id: a.id })} className="bg-zinc-900/40 p-5 rounded-[2rem] hover:bg-zinc-800/60 transition-all cursor-pointer">
                <img src={a.coverUrl} className="w-full aspect-square object-cover rounded-[1.5rem] mb-3 shadow-lg" alt={a.title} />
                <p className="font-bold truncate text-sm">{a.title}</p>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

