function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks }: CreatorHubProps) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage' | 'ideas'>('artist');
  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: 0, artistVerified: true, artistImg: '',
    albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumSelectedTracks: [],
    trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: 0, trackLikes: 0
  });
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetForm = () => {
    setFormData({
      artistName: '', artistBio: '', artistGenre: '', artistFollowers: 0, artistVerified: true, artistImg: '',
      albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumSelectedTracks: [],
      trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: 0, trackLikes: 0
    });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const base64 = await fileToBase64(file);
      const field = activeTab === 'artist' ? 'artistImg' : 'albumImg';
      setFormData({ ...formData, [field]: base64 });
    }
  };

  const createArtist = () => {
    if (!formData.artistName) return;
    const newArtist: Artist = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.artistName,
      bio: formData.artistBio || 'A rising star on Musaic.',
      imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
      genre: formData.artistGenre || 'Various',
      followers: Number(formData.artistFollowers) || 0,
      verified: formData.artistVerified
    };
    setArtists([...artists, newArtist]);
    resetForm();
    alert('Artist Published!');
  };

  const createAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId)!;
    const albumId = Math.random().toString(36).substr(2, 9);

    const newAlbum: Album = {
      id: albumId,
      title: formData.albumTitle,
      artistId: artist.id,
      artistName: artist.name,
      coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`,
      releaseYear: Number(formData.albumYear) || new Date().getFullYear(),
      genre: formData.albumGenre || artist.genre,
      isLiked: false
    };

    if (formData.albumSelectedTracks.length > 0) {
      setTracks(prev => prev.map(t => 
        formData.albumSelectedTracks.includes(t.id) ? { ...t, albumId: albumId, albumTitle: newAlbum.title } : t
      ));
    }

    setAlbums([...albums, newAlbum]);
    resetForm();
    alert('Album Published!');
  };

  const createTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId)!;
    const album = albums.find(a => a.id === formData.trackAlbumId);

    const newTrack: Track = {
      id: Math.random().toString(36).substr(2, 9),
      title: formData.trackTitle,
      artistId: artist.id,
      artistName: artist.name,
      albumId: album?.id || 'single',
      albumTitle: album?.title || 'Single',
      duration: formData.trackDuration,
      plays: Number(formData.trackPlays) || 0,
      likes: Number(formData.trackLikes) || 0,
      isLiked: false
    };
    setTracks([...tracks, newTrack]);
    resetForm();
    alert('Track Released!');
  };

  const generateAIBio = async () => {
    if (!formData.artistName) return alert("Enter artist name first");
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Write a high-end, punchy biography for an artist named "${formData.artistName}" who plays ${formData.artistGenre || 'various music styles'}. 2 sentences max.`
      });
      setFormData({ ...formData, artistBio: response.text?.trim() });
    } catch (e) {
      console.error(e);
      setFormData({ ...formData, artistBio: "A legend in the making." });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-12 max-w-6xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-16 bg-zinc-900/40 p-10 rounded-[4rem] border border-zinc-800/50 backdrop-blur-3xl shadow-3xl">
        <div>
          <h2 className="text-6xl font-black tracking-tighter mb-4">Creator Hub</h2>
          <p className="text-xl text-zinc-500 font-bold tracking-tight">Sculpt your music universe with precision.</p>
        </div>
        <div className="flex gap-2 p-2 bg-black rounded-[2rem] border border-zinc-800 shadow-inner">
          {['artist', 'album', 'track', 'manage', 'ideas'].map((t) => (
            <button 
              key={t}
              onClick={() => { setActiveTab(t as any); resetForm(); }}
              className={`px-8 py-3 rounded-[1.5rem] font-black text-sm transition-all capitalize ${activeTab === t ? 'bg-zinc-700 text-white shadow-xl' : 'text-zinc-500 hover:text-white'}`}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      {activeTab === 'ideas' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-10 duration-700">
           <IdeaCard icon={Layout} title="Visualizer Engine" desc="Add CSS-based reactive audio waves to track pages for an immersive experience." />
           <IdeaCard icon={BarChart3} title="Artist Studio Analytics" desc="See fake real-time listener counts and 'hot spots' on a world map." />
           <IdeaCard icon={Languages} title="Lyric Sync Editor" desc="Type and timestamp lyrics so they highlight in time with the music." />
           <IdeaCard icon={Sparkles} title="AI Album Art" desc="Connect to image generation models to create unique covers for every release." />
           <IdeaCard icon={GripVertical} title="Custom Sorting" desc="Drag and drop tracks to reorder them within albums manually." />
           <IdeaCard icon={CheckCircle2} title="Verified Badges" desc="Apply for and manage custom verified statuses for your artists." />
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
          {activeTab !== 'manage' && (
            <div className="md:col-span-2 space-y-8">
              <div className="bg-zinc-900/30 backdrop-blur-md p-10 rounded-[4rem] border border-zinc-800/50 space-y-8 shadow-2xl">
                {activeTab === 'artist' && (
                  <>
                    <InputGroup label="Artist Name" placeholder="e.g. SOLARA" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                    <div className="grid grid-cols-2 gap-6">
                      <InputGroup label="Genre" placeholder="Future Bass" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                      <InputGroup label="Monthly Listeners" type="number" value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                    </div>
                    <div className="space-y-3">
                      <div className="flex justify-between items-center">
                        <label className="text-sm font-black text-zinc-500 uppercase tracking-widest px-2">Artist Story</label>
                        <button onClick={generateAIBio} disabled={loading} className="text-xs font-black text-green-400 flex items-center gap-2 hover:brightness-125 transition-all">
                          {loading ? 'WEAVING...' : <><Sparkles className="w-4 h-4" /> AI MAGIC BIO</>}
                        </button>
                      </div>
                      <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} rows={4} className="w-full bg-zinc-800/40 border-2 border-zinc-700/50 rounded-[2rem] p-6 focus:border-green-400/50 outline-none transition-all resize-none text-lg font-bold tracking-tight" />
                    </div>
                    <button onClick={createArtist} className="w-full py-6 bg-white text-black font-black text-2xl rounded-[2.5rem] hover:scale-[1.03] active:scale-[0.97] transition-all shadow-2xl shadow-white/5">Publish Artist</button>
                  </>
                )}

                {activeTab === 'album' && (
                  <>
                    <InputGroup label="Album Title" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                    <div className="space-y-3">
                      <label className="text-sm font-black text-zinc-500 uppercase tracking-widest px-2">Linked Artist</label>
                      <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-zinc-800/40 border-2 border-zinc-700/50 rounded-[2rem] p-6 font-black text-lg appearance-none focus:border-green-400/50 outline-none">
                        <option value="">Choose your creator...</option>
                        {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                      </select>
                    </div>
                    <div className="grid grid-cols-2 gap-6">
                      <InputGroup label="Year" type="number" value={formData.albumYear} onChange={v => setFormData({...formData, albumYear: v})} />
                      <InputGroup label="Sub-Genre" value={formData.albumGenre} onChange={v => setFormData({...formData, albumGenre: v})} />
                    </div>
                    <button onClick={createAlbum} className="w-full py-6 bg-white text-black font-black text-2xl rounded-[2.5rem] hover:scale-[1.03] active:scale-[0.97] transition-all shadow-2xl">Drop Album</button>
                  </>
                )}

                {activeTab === 'track' && (
                  <>
                    <InputGroup label="Track Name" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                    <div className="grid grid-cols-2 gap-6">
                       <InputGroup label="Plays" type="number" value={formData.trackPlays} onChange={v => setFormData({...formData, trackPlays: v})} />
                       <InputGroup label="Likes" type="number" value={formData.trackLikes} onChange={v => setFormData({...formData, trackLikes: v})} />
                    </div>
                    <button onClick={createTrack} className="w-full py-6 bg-white text-black font-black text-2xl rounded-[2.5rem] hover:scale-[1.03] active:scale-[0.97] transition-all shadow-2xl">Release Track</button>
                  </>
                )}
              </div>
            </div>
          )}

          {activeTab !== 'manage' && (
            <div className="space-y-10">
              <div className="bg-zinc-900/30 backdrop-blur-md p-10 rounded-[3.5rem] border border-zinc-800/50 text-center shadow-2xl">
                <h3 className="text-sm font-black text-zinc-500 mb-8 uppercase tracking-[0.3em]">Art Direction</h3>
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full aspect-square bg-zinc-800/40 rounded-[3rem] border-4 border-dashed border-zinc-700/50 flex flex-col items-center justify-center cursor-pointer hover:border-green-500/50 hover:bg-zinc-800/60 transition-all group overflow-hidden relative shadow-inner"
                >
                  {(activeTab === 'artist' ? formData.artistImg : formData.albumImg) ? (
                    <img src={activeTab === 'artist' ? formData.artistImg : formData.albumImg} className="w-full h-full object-cover" />
                  ) : (
                    <>
                      <ImageIcon className="w-16 h-16 text-zinc-700 mb-4 group-hover:scale-110 transition-transform" />
                      <p className="text-sm font-black text-zinc-500 uppercase tracking-widest">Upload Cover</p>
                    </>
