              </div>
            </div>
          )}

          {activeTab === 'manage' && (
            <div className="col-span-1 md:col-span-3 space-y-12 animate-in fade-in duration-500">
               <ManagementSection title="Legacy Artists" items={artists} onDelete={id => setArtists(prev => prev.filter(a => a.id !== id))} icon={User} />
               <ManagementSection title="Full Length Albums" items={albums} onDelete={id => setAlbums(prev => prev.filter(a => a.id !== id))} icon={Disc} />
               <ManagementSection title="Singles & Tracks" items={tracks} onDelete={id => setTracks(prev => prev.filter(t => t.id !== id))} icon={Music} />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

const InputGroup = ({ label, type = 'text', placeholder, value, onChange }: { label: string, type?: string, placeholder?: string, value: any, onChange: (v: string) => void }) => (
  <div className="space-y-3">
    <label className="text-sm font-black text-zinc-500 uppercase tracking-widest px-2">{label}</label>
    <input 
      type={type} 
      value={value} 
      onChange={e => onChange(e.target.value)}
