              >
                {(activeTab === 'artist' ? formData.artistImg : formData.albumImg) ? (
                  <img src={activeTab === 'artist' ? formData.artistImg : formData.albumImg} className="w-full h-full object-cover" />
                ) : (
                  <>
                    <ImageIcon className="w-20 h-20 text-zinc-700 mb-6 group-hover:scale-125 transition-transform" />
                    <p className="text-xs font-black text-zinc-600 uppercase tracking-widest">Select Image</p>
                  </>
                )}
                <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                   <Upload className="w-12 h-12 text-white" />
                </div>
              </div>
              <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
            </div>

            <div className="bg-gradient-to-br from-green-500/10 to-transparent p-12 rounded-[4rem] border border-green-500/20 shadow-2xl">
              <h4 className="text-2xl font-black mb-4 flex items-center gap-4 italic tracking-tighter">
                <Dices className="text-green-400" />
                Chaos Metrics
              </h4>
              <p className="text-zinc-500 font-black mb-8 leading-relaxed italic opacity-80">Generate unpredictable popularity data for your entire music network instantly.</p>
              <button onClick={randomizeAllStats} className="w-full py-5 bg-green-500 text-black font-black text-xl rounded-[2rem] hover:scale-105 active:scale-95 transition-all shadow-2xl shadow-green-500/20">
                Randomize Metrics
              </button>
            </div>
          </div>
        )}

        {activeTab === 'manage' && (
          <div className="col-span-1 xl:col-span-3 space-y-20 animate-in fade-in duration-500">
             <ManagementSection title="Legacy Artists" items={artists} onDelete={id => setArtists(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('artist', id)} icon={User} />
             <ManagementSection title="Full Length Archives" items={albums} onDelete={id => setAlbums(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('album', id)} icon={Disc} />
             <ManagementSection title="Broadcasting Signals" items={tracks} onDelete={id => setTracks(prev => prev.filter(t => t.id !== id))} onEdit={id => handleEdit('track', id)} icon={Music} />
          </div>
        )}
      </div>
    </div>
  );
}

const InputGroup = ({ label, type = 'text', placeholder, value, onChange }: { label: string, type?: string, placeholder?: string, value: any, onChange: (v: string) => void }) => (
  <div className="space-y-4">
    <label className="text-xs font-black text-zinc-500 uppercase tracking-[0.3em] px-4">{label}</label>
    <input 
      type={type} 
      value={value} 
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder} 
      className="w-full bg-zinc-800/40 border-2 border-zinc-700/50 rounded-[2.5rem] p-8 focus:border-green-400/50 outline-none transition-all text-3xl font-black tracking-tighter"
    />
  </div>
);

const ManagementSection = ({ title, items, onDelete, onEdit, icon: Icon }: { title: string, items: any[], onDelete: (id: string) => void, onEdit: (id: string) => void, icon: any }) => (
  <div className="space-y-8 px-4">
    <h3 className="text-5xl font-black flex items-center gap-6 tracking-tighter italic">
      <Icon className="w-10 h-10 text-zinc-700" />
