    </h3>
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
      {items.map(item => (
        <div key={item.id} className="bg-zinc-900/40 p-8 rounded-[3.5rem] border border-zinc-800/50 flex flex-col gap-6 group hover:bg-zinc-800/60 transition-all relative overflow-hidden">
          <div className="w-full aspect-square bg-zinc-800 rounded-[2.5rem] overflow-hidden shadow-2xl">
            <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/400/400`} className="w-full h-full object-cover transition-all group-hover:scale-110" />
          </div>
          <div className="min-w-0">
            <p className="text-2xl font-black truncate tracking-tighter mb-1">{item.name || item.title}</p>
            <p className="text-xs text-zinc-600 font-black uppercase tracking-widest">{item.genre || item.artistName || 'Creator'}</p>
          </div>
          <div className="flex gap-4 mt-auto">
            <button onClick={() => onEdit(item.id)} className="flex-1 py-3 bg-zinc-800 rounded-2xl font-black text-sm hover:bg-white hover:text-black transition-all">Edit</button>
            <button onClick={() => onDelete(item.id)} className="p-3 bg-red-500/10 text-red-500 rounded-2xl hover:bg-red-500 hover:text-white transition-all">
              <Trash2 className="w-5 h-5" />
            </button>
          </div>
        </div>
      ))}
      {items.length === 0 && <p className="text-xl font-black text-zinc-700 italic opacity-40">Section Empty.</p>}
    </div>
