  if (!artist) return <div className="p-20 text-center text-4xl font-black">Artist Offline</div>;

  const artistAlbums = albums.filter((a) => a.artistId === id);
  const artistTracks = tracks.filter((t) => t.artistId === id).slice(0, 8);

  return (
    <div className="relative animate-in fade-in duration-700">
      <div className="h-[600px] bg-zinc-800 flex flex-col justify-end p-16 relative overflow-hidden">
        <img src={artist.imageUrl} className="absolute inset-0 w-full h-full object-cover" alt={artist.name} />
        <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent"></div>
        <div className="relative z-10">
          <div className="flex items-center gap-4 mb-6">
            {artist.verified && <CheckCircle2 className="w-10 h-10 text-blue-400 fill-blue-400" />}
            <span className="text-xl font-black uppercase tracking-[0.4em] text-white/80">Authorized Creator</span>
          </div>
          <h1 className="text-[12vw] font-black mb-10 tracking-tighter leading-[0.8] drop-shadow-3xl italic">{artist.name}</h1>
          <p className="text-2xl font-black text-zinc-300 tracking-tighter">{formatNumber(artist.followers)} Listeners reaching the frequency</p>
        </div>
      </div>

      <div className="p-16 bg-black">
        <div className="flex items-center gap-12 mb-24">
          <button className="w-24 h-24 bg-green-500 rounded-full flex items-center justify-center hover:scale-110 active:scale-90 transition-all shadow-2xl shadow-green-500/20">
            <Play className="text-black fill-black ml-1 w-12 h-12" />
          </button>
          <button className="border-4 border-zinc-800 px-16 py-5 rounded-[2rem] font-black text-2xl hover:border-white transition-all italic tracking-tighter">Follow Signal</button>
