          {artistAlbums.map((album) => (
            <div key={album.id} onClick={() => navigateTo('album', { id: album.id })} className="group cursor-pointer">
              <div className="relative mb-6">
                <img src={album.coverUrl} className="w-full aspect-square object-cover rounded-[3rem] shadow-2xl border-4 border-white/5 group-hover:scale-105 transition-all" alt={album.title} />
