          <Heart className="w-16 h-16 mb-auto fill-white drop-shadow-2xl relative z-10" />
          <p className="text-4xl font-black mb-4 tracking-tighter italic relative z-10">Signals</p>
          <p className="text-xs font-black uppercase tracking-widest opacity-60 relative z-10">Personalized Collection</p>
