}

function SearchView({ query, artists, albums, tracks, navigateTo }: SearchViewProps) {
  const filteredArtists = artists.filter((a) => a.name.toLowerCase().includes(query.toLowerCase()));
  const filteredAlbums = albums.filter((a) => a.title.toLowerCase().includes(query.toLowerCase()));
  const filteredTracks = tracks.filter((t) => t.title.toLowerCase().includes(query.toLowerCase()));

  if (!query) {
    return (
      <div className="p-16">
        <h3 className="text-6xl font-black tracking-tighter italic mb-16 px-2">Broad Frequencies</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-12">
          {['Cybersynth', 'Neuro-Jazz', 'Hyper-Signal', 'Glitch-Core', 'Neo-Pop', 'Void-Bass', 'Acid-Indie', 'Bio-Acoustic'].map(genre => (
            <div key={genre} className="bg-zinc-800/40 aspect-video rounded-[4rem] p-12 relative overflow-hidden group cursor-pointer shadow-3xl hover:bg-zinc-700/40 transition-all border border-white/5">
              <span className="text-4xl xl:text-5xl font-black relative z-10 tracking-tighter italic">{genre}</span>
              <img src={`https://picsum.photos/seed/${genre}/800/600`} className="absolute bottom-0 right-0 w-64 h-64 rotate-[30deg] translate-x-16 translate-y-16 group-hover:scale-125 transition-transform shadow-2xl opacity-40 group-hover:opacity-100 mix-blend-screen" alt={genre} />
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-16">
      {filteredArtists.length > 0 && (
        <div className="mb-24">
          <SectionTitle title="Artists Detected" />
          <div className="flex gap-12 overflow-x-auto pb-12 custom-scrollbar">
            {filteredArtists.map((a) => (
              <div key={a.id} onClick={() => navigateTo('artist', { id: a.id })} className="flex-shrink-0 w-72 bg-zinc-900/30 p-10 rounded-[4rem] hover:bg-zinc-800/50 transition-all cursor-pointer shadow-2xl">
                <img src={a.imageUrl} className="w-full aspect-square object-cover rounded-full mb-8 shadow-2xl" alt={a.name} />
                <p className="font-black truncate text-2xl tracking-tighter text-center">{a.name}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {filteredTracks.length > 0 && (
        <div className="mb-24">
          <SectionTitle title="Captured Signals" />
          <div className="space-y-4">
            {filteredTracks.map((t, i) => (
              <TrackRow key={t.id} track={t} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: t.id })} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

