function TrackPage({ id, tracks, albums, toggleLikeTrack, navigateTo }: TrackViewProps) {
  const track = tracks.find(t => t.id === id);
  if (!track) return <div className="p-20 text-center text-4xl font-black">Track not found</div>;
  const album = albums.find(a => a.id === track.albumId);

  return (
    <div className="min-h-full flex flex-col p-12 bg-gradient-to-b from-zinc-800/40 to-black animate-in zoom-in-95 duration-500">
      <div className="flex flex-col xl:flex-row items-center gap-20 mt-20">
        <div className="w-96 h-96 xl:w-[600px] xl:h-[600px] shadow-[0_80px_160px_-40px_rgba(0,0,0,1)] rounded-[4rem] overflow-hidden border-8 border-white/5">
          <img src={album?.coverUrl || 'https://picsum.photos/seed/default/600/600'} className="w-full h-full object-cover" />
        </div>
        <div className="flex flex-col items-center xl:items-start text-center xl:text-left">
          <span className="text-xs font-black uppercase tracking-[0.5em] mb-6 text-green-400">Now Inspecting</span>
          <h1 className="text-8xl xl:text-[10vw] font-black mb-10 tracking-tighter leading-[0.8] drop-shadow-3xl italic">{track.title}</h1>
          <div 
            onClick={() => navigateTo('artist', { id: track.artistId })}
            className="flex items-center gap-6 text-3xl font-black hover:text-green-400 cursor-pointer transition-all tracking-tighter mb-12"
          >
            <div className="w-16 h-16 bg-zinc-800 rounded-full overflow-hidden border-2 border-white/10">
              <img src="https://picsum.photos/seed/artist/200/200" className="w-full h-full object-cover" />
            </div>
            {track.artistName}
          </div>
          <div className="flex gap-12 items-center text-zinc-500 font-black uppercase tracking-widest text-sm">
             <div className="flex flex-col gap-2">
               <span className="opacity-40">Plays</span>
               <span className="text-white text-3xl tabular-nums">{formatNumber(track.plays)}</span>
             </div>
             <div className="flex flex-col gap-2">
               <span className="opacity-40">Duration</span>
               <span className="text-white text-3xl tabular-nums">{track.duration}</span>
             </div>
             <div className="flex flex-col gap-2">
               <span className="opacity-40">Album</span>
               <span className="text-white text-3xl hover:underline cursor-pointer" onClick={() => navigateTo('album', { id: track.albumId })}>{track.albumTitle}</span>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks }: CreatorHubProps) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>('artist');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: 0, artistVerified: true, artistImg: '',
    albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '',
    trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: 0, trackLikes: 0
  });
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetForm = () => {
    setFormData({
      artistName: '', artistBio: '', artistGenre: '', artistFollowers: 0, artistVerified: true, artistImg: '',
      albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '',
      trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: 0, trackLikes: 0
    });
    setEditingId(null);
  };

  const handleEdit = (type: string, id: string) => {
    setEditingId(id);
    setActiveTab(type as any);
    if (type === 'artist') {
      const a = artists.find(i => i.id === id)!;
      setFormData({...formData, artistName: a.name, artistBio: a.bio, artistGenre: a.genre, artistFollowers: a.followers, artistVerified: a.verified, artistImg: a.imageUrl});
    } else if (type === 'album') {
      const a = albums.find(i => i.id === id)!;
      setFormData({...formData, albumTitle: a.title, albumArtistId: a.artistId, albumImg: a.coverUrl, albumYear: a.releaseYear, albumGenre: a.genre});
    } else if (type === 'track') {
      const a = tracks.find(i => i.id === id)!;
      setFormData({...formData, trackTitle: a.title, trackArtistId: a.artistId, trackAlbumId: a.albumId, trackDuration: a.duration, trackPlays: a.plays, trackLikes: a.likes});
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const base64 = await fileToBase64(file);
      const field = activeTab === 'artist' ? 'artistImg' : 'albumImg';
      setFormData({ ...formData, [field]: base64 });
    }
  };

  const saveArtist = () => {
    if (!formData.artistName) return;
    if (editingId) {
      setArtists(prev => prev.map(a => a.id === editingId ? { ...a, name: formData.artistName, bio: formData.artistBio, genre: formData.artistGenre, followers: Number(formData.artistFollowers), verified: formData.artistVerified, imageUrl: formData.artistImg || a.imageUrl } : a));
    } else {
      const newArtist: Artist = {
        id: Math.random().toString(36).substr(2, 9),
        name: formData.artistName,
        bio: formData.artistBio,
        imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
        genre: formData.artistGenre,
        followers: Number(formData.artistFollowers),
        verified: formData.artistVerified
      };
      setArtists([...artists, newArtist]);
    }
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId)!;
    if (editingId) {
      setAlbums(prev => prev.map(a => a.id === editingId ? { ...a, title: formData.albumTitle, artistId: artist.id, artistName: artist.name, coverUrl: formData.albumImg || a.coverUrl, releaseYear: Number(formData.albumYear), genre: formData.albumGenre } : a));
    } else {
      const newAlbum: Album = {
        id: Math.random().toString(36).substr(2, 9),
        title: formData.albumTitle,
        artistId: artist.id,
        artistName: artist.name,
        coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`,
        releaseYear: Number(formData.albumYear),
        genre: formData.albumGenre,
        isLiked: false
      };
      setAlbums([...albums, newAlbum]);
    }
    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId)!;
    const album = albums.find(a => a.id === formData.trackAlbumId);
    if (editingId) {
      setTracks(prev => prev.map(t => t.id === editingId ? { ...t, title: formData.trackTitle, artistId: artist.id, artistName: artist.name, albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays: Number(formData.trackPlays), likes: Number(formData.trackLikes) } : t));
    } else {
      const newTrack: Track = {
        id: Math.random().toString(36).substr(2, 9),
        title: formData.trackTitle,
        artistId: artist.id,
        artistName: artist.name,
        albumId: album?.id || 'single',
        albumTitle: album?.title || 'Single',
        duration: formData.trackDuration,
        plays: Number(formData.trackPlays),
        likes: Number(formData.trackLikes),
        isLiked: false
      };
      setTracks([...tracks, newTrack]);
    }
    resetForm();
  };

  const randomizeAllStats = () => {
    setArtists(prev => prev.map(a => ({ ...a, followers: getRandomStats(50000, 5000000) })));
    setTracks(prev => prev.map(t => ({ ...t, plays: getRandomStats(100000, 100000000), likes: getRandomStats(1000, 500000) })));
    alert('Global metrics recalculated.');
  };

  const generateAIBio = async () => {
    if (!formData.artistName) return;
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Write a high-end, futuristic 2-sentence musician bio for an artist named "${formData.artistName}" who plays ${formData.artistGenre || 'experimental music'}.`
      });
      setFormData({ ...formData, artistBio: response.text?.trim() });
    } catch (e) {
      setFormData({ ...formData, artistBio: "A legend from the neon shadows." });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-12 max-w-7xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-20 bg-zinc-900/40 p-12 rounded-[5rem] border border-zinc-800/50 backdrop-blur-3xl shadow-3xl">
        <div>
          <h2 className="text-7xl font-black tracking-tighter mb-4 italic">Editor Hub</h2>
          <p className="text-2xl text-zinc-600 font-black tracking-tight">Real-time library manipulation.</p>
        </div>
        <div className="flex gap-4 p-3 bg-black rounded-[3rem] border border-zinc-800">
          {['artist', 'album', 'track', 'manage'].map((t) => (
            <button 
              key={t}
              onClick={() => { setActiveTab(t as any); resetForm(); }}
              className={`px-10 py-4 rounded-[2.5rem] font-black text-lg transition-all capitalize ${activeTab === t ? 'bg-zinc-700 text-white shadow-2xl' : 'text-zinc-500 hover:text-white'}`}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-16">
        {activeTab !== 'manage' && (
          <div className="xl:col-span-2 space-y-12">
            <div className="bg-zinc-900/30 backdrop-blur-md p-12 rounded-[5rem] border border-zinc-800/50 space-y-10 shadow-3xl">
              {activeTab === 'artist' && (
                <>
                  <InputGroup label="Artist Identity" placeholder="e.g. SOLARA" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                  <div className="grid grid-cols-2 gap-10">
                    <InputGroup label="Core Genre" placeholder="Deep Tech" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                    <InputGroup label="Followers" type="number" value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                  </div>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center px-4">
                      <label className="text-xs font-black text-zinc-500 uppercase tracking-[0.3em]">Biography</label>
                      <button onClick={generateAIBio} disabled={loading} className="text-sm font-black text-green-400 flex items-center gap-3 hover:scale-105 transition-all">
                        {loading ? 'WEAVING...' : <><Sparkles className="w-5 h-5" /> GENERATE BIO</>}
                      </button>
                    </div>
                    <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} rows={5} className="w-full bg-zinc-800/40 border-2 border-zinc-700/50 rounded-[2.5rem] p-8 focus:border-green-400/50 outline-none transition-all resize-none text-2xl font-black tracking-tighter" />
                  </div>
                  <button onClick={saveArtist} className="w-full py-8 bg-white text-black font-black text-3xl rounded-[3rem] hover:scale-[1.03] active:scale-[0.97] transition-all shadow-2xl">
                    {editingId ? 'Update Identity' : 'Publish Identity'}
                  </button>
                </>
              )}

              {activeTab === 'album' && (
                <>
                  <InputGroup label="Album Title" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                  <div className="space-y-4">
                    <label className="text-xs font-black text-zinc-500 uppercase tracking-[0.3em] px-4">Executive Producer (Artist)</label>
                    <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-zinc-800/40 border-2 border-zinc-700/50 rounded-[2.5rem] p-8 font-black text-2xl appearance-none focus:border-green-400/50 outline-none cursor-pointer">
                      <option value="">Select Creator...</option>
                      {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-10">
                    <InputGroup label="Release Cycle (Year)" type="number" value={formData.albumYear} onChange={v => setFormData({...formData, albumYear: v})} />
                    <InputGroup label="Sub-Genre" value={formData.albumGenre} onChange={v => setFormData({...formData, albumGenre: v})} />
                  </div>
                  <button onClick={saveAlbum} className="w-full py-8 bg-white text-black font-black text-3xl rounded-[3rem] hover:scale-[1.03] active:scale-[0.97] transition-all shadow-2xl">
                    {editingId ? 'Commit Album Edits' : 'Deploy Full Length'}
                  </button>
                </>
              )}

              {activeTab === 'track' && (
                <>
                  <InputGroup label="Signal Title (Track)" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                  <div className="grid grid-cols-2 gap-10">
                    <div className="space-y-4">
                      <label className="text-xs font-black text-zinc-500 uppercase tracking-[0.3em] px-4">Primary Artist</label>
                      <select value={formData.trackArtistId} onChange={e => setFormData({...formData, trackArtistId: e.target.value, trackAlbumId: ''})} className="w-full bg-zinc-800/40 border-2 border-zinc-700/50 rounded-[2.5rem] p-8 font-black text-2xl appearance-none focus:border-green-400/50 outline-none cursor-pointer">
                        <option value="">Select Artist...</option>
                        {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-4">
                      <label className="text-xs font-black text-zinc-500 uppercase tracking-[0.3em] px-4">Assigned Album</label>
                      <select value={formData.trackAlbumId} onChange={e => setFormData({...formData, trackAlbumId: e.target.value})} className="w-full bg-zinc-800/40 border-2 border-zinc-700/50 rounded-[2.5rem] p-8 font-black text-2xl appearance-none focus:border-green-400/50 outline-none cursor-pointer">
                        <option value="single">Single Release</option>
                        {albums.filter(a => a.artistId === formData.trackArtistId).map(a => <option key={a.id} value={a.id}>{a.title}</option>)}
                      </select>
                    </div>
                  </div>
                  <div className="grid grid-cols-3 gap-10">
                    <InputGroup label="Duration" placeholder="3:30" value={formData.trackDuration} onChange={v => setFormData({...formData, trackDuration: v})} />
                    <InputGroup label="Plays" type="number" value={formData.trackPlays} onChange={v => setFormData({...formData, trackPlays: v})} />
                    <InputGroup label="Likes" type="number" value={formData.trackLikes} onChange={v => setFormData({...formData, trackLikes: v})} />
                  </div>
                  <button onClick={saveTrack} className="w-full py-8 bg-white text-black font-black text-3xl rounded-[3rem] hover:scale-[1.03] active:scale-[0.97] transition-all shadow-2xl">
                    {editingId ? 'Modify Signal' : 'Broadcast Track'}
                  </button>
                </>
              )}
            </div>
          </div>
        )}

        {activeTab !== 'manage' && (
          <div className="space-y-12">
            <div className="bg-zinc-900/30 backdrop-blur-md p-12 rounded-[4rem] border border-zinc-800/50 text-center shadow-3xl">
              <h3 className="text-xs font-black text-zinc-600 mb-10 uppercase tracking-[0.4em]">Visual Identification</h3>
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="w-full aspect-square bg-zinc-800/40 rounded-[3rem] border-4 border-dashed border-zinc-700/50 flex flex-col items-center justify-center cursor-pointer hover:border-green-500 transition-all group overflow-hidden relative"
              >
                {(activeTab === 'artist' ? formData.artistImg : formData.albumImg) ? (
                  <img src={activeTab === 'artist' ? formData.artistImg : formData.albumImg} className="w-full h-full object-cover" />
                ) : (
                  <>
                    <ImageIcon className="w-20 h-20 text-zinc-700 mb-6 group-hover:scale-125 transition-transform" />
                    <p className="text-xs font-black text-zinc-600 uppercase tracking-widest">Select Image</p>
                  </>
                )}
                <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                   <Upload className="w-12 h-12 text-white" />
                </div>
              </div>
              <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
            </div>

            <div className="bg-gradient-to-br from-green-500/10 to-transparent p-12 rounded-[4rem] border border-green-500/20 shadow-2xl">
              <h4 className="text-2xl font-black mb-4 flex items-center gap-4 italic tracking-tighter">
                <Dices className="text-green-400" />
                Chaos Metrics
              </h4>
              <p className="text-zinc-500 font-black mb-8 leading-relaxed italic opacity-80">Generate unpredictable popularity data for your entire music network instantly.</p>
              <button onClick={randomizeAllStats} className="w-full py-5 bg-green-500 text-black font-black text-xl rounded-[2rem] hover:scale-105 active:scale-95 transition-all shadow-2xl shadow-green-500/20">
                Randomize Metrics
              </button>
            </div>
          </div>
        )}

        {activeTab === 'manage' && (
          <div className="col-span-1 xl:col-span-3 space-y-20 animate-in fade-in duration-500">
             <ManagementSection title="Legacy Artists" items={artists} onDelete={id => setArtists(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('artist', id)} icon={User} />
             <ManagementSection title="Full Length Archives" items={albums} onDelete={id => setAlbums(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('album', id)} icon={Disc} />
             <ManagementSection title="Broadcasting Signals" items={tracks} onDelete={id => setTracks(prev => prev.filter(t => t.id !== id))} onEdit={id => handleEdit('track', id)} icon={Music} />
          </div>
        )}
      </div>
    </div>
  );
}

const InputGroup = ({ label, type = 'text', placeholder, value, onChange }: { label: string, type?: string, placeholder?: string, value: any, onChange: (v: string) => void }) => (
  <div className="space-y-4">
    <label className="text-xs font-black text-zinc-500 uppercase tracking-[0.3em] px-4">{label}</label>
    <input 
      type={type} 
      value={value} 
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder} 
      className="w-full bg-zinc-800/40 border-2 border-zinc-700/50 rounded-[2.5rem] p-8 focus:border-green-400/50 outline-none transition-all text-3xl font-black tracking-tighter"
    />
  </div>
);

const ManagementSection = ({ title, items, onDelete, onEdit, icon: Icon }: { title: string, items: any[], onDelete: (id: string) => void, onEdit: (id: string) => void, icon: any }) => (
  <div className="space-y-8 px-4">
    <h3 className="text-5xl font-black flex items-center gap-6 tracking-tighter italic">
      <Icon className="w-10 h-10 text-zinc-700" />
      {title} <span className="text-2xl text-zinc-800 font-black">({items.length})</span>
    </h3>
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
      {items.map(item => (
        <div key={item.id} className="bg-zinc-900/40 p-8 rounded-[3.5rem] border border-zinc-800/50 flex flex-col gap-6 group hover:bg-zinc-800/60 transition-all relative overflow-hidden">
          <div className="w-full aspect-square bg-zinc-800 rounded-[2.5rem] overflow-hidden shadow-2xl">
            <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/400/400`} className="w-full h-full object-cover transition-all group-hover:scale-110" />
          </div>
          <div className="min-w-0">
            <p className="text-2xl font-black truncate tracking-tighter mb-1">{item.name || item.title}</p>
            <p className="text-xs text-zinc-600 font-black uppercase tracking-widest">{item.genre || item.artistName || 'Creator'}</p>
          </div>
          <div className="flex gap-4 mt-auto">
            <button onClick={() => onEdit(item.id)} className="flex-1 py-3 bg-zinc-800 rounded-2xl font-black text-sm hover:bg-white hover:text-black transition-all">Edit</button>
            <button onClick={() => onDelete(item.id)} className="p-3 bg-red-500/10 text-red-500 rounded-2xl hover:bg-red-500 hover:text-white transition-all">
              <Trash2 className="w-5 h-5" />
            </button>
          </div>
        </div>
      ))}
      {items.length === 0 && <p className="text-xl font-black text-zinc-700 italic opacity-40">Section Empty.</p>}
    </div>
  </div>
);

function ArtistView({ id, artists, albums, tracks, navigateTo, toggleLikeTrack }: ArtistViewProps) {
  const artist = artists.find((a) => a.id === id);
  if (!artist) return <div className="p-20 text-center text-4xl font-black">Artist Offline</div>;

  const artistAlbums = albums.filter((a) => a.artistId === id);
  const artistTracks = tracks.filter((t) => t.artistId === id).slice(0, 8);

  return (
    <div className="relative animate-in fade-in duration-700">
      <div className="h-[600px] bg-zinc-800 flex flex-col justify-end p-16 relative overflow-hidden">
        <img src={artist.imageUrl} className="absolute inset-0 w-full h-full object-cover" alt={artist.name} />
        <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent"></div>
        <div className="relative z-10">
          <div className="flex items-center gap-4 mb-6">
            {artist.verified && <CheckCircle2 className="w-10 h-10 text-blue-400 fill-blue-400" />}
            <span className="text-xl font-black uppercase tracking-[0.4em] text-white/80">Authorized Creator</span>
          </div>
          <h1 className="text-[12vw] font-black mb-10 tracking-tighter leading-[0.8] drop-shadow-3xl italic">{artist.name}</h1>
          <p className="text-2xl font-black text-zinc-300 tracking-tighter">{formatNumber(artist.followers)} Listeners reaching the frequency</p>
        </div>
      </div>

      <div className="p-16 bg-black">
        <div className="flex items-center gap-12 mb-24">
          <button className="w-24 h-24 bg-green-500 rounded-full flex items-center justify-center hover:scale-110 active:scale-90 transition-all shadow-2xl shadow-green-500/20">
            <Play className="text-black fill-black ml-1 w-12 h-12" />
          </button>
          <button className="border-4 border-zinc-800 px-16 py-5 rounded-[2rem] font-black text-2xl hover:border-white transition-all italic tracking-tighter">Follow Signal</button>
          <MoreHorizontal className="w-12 h-12 text-zinc-600 cursor-pointer hover:text-white transition-colors" />
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-3 gap-24">
          <div className="xl:col-span-2">
            <h3 className="text-6xl font-black mb-16 tracking-tighter italic">High Frequency Peaks</h3>
            <div className="space-y-4">
              {artistTracks.map((track, i) => (
                <TrackRow 
                  key={track.id} 
                  track={track} 
                  index={i} 
                  toggleLike={toggleLikeTrack} 
                  onPlay={() => navigateTo('track', { id: track.id })} 
                />
              ))}
            </div>
          </div>
          <div className="space-y-16">
            <h3 className="text-6xl font-black tracking-tighter italic">Data Narrative</h3>
            <div className="bg-zinc-900/40 rounded-[4rem] p-12 border border-zinc-800/50 shadow-3xl">
               <p className="text-zinc-200 text-2xl font-bold leading-relaxed mb-12 italic opacity-90">{artist.bio}</p>
               <div className="flex flex-wrap gap-4">
                  <div className="px-8 py-3 bg-zinc-800/60 rounded-full font-black text-sm uppercase tracking-widest border border-white/10 italic">#{artist.genre}</div>
                  <div className="px-8 py-3 bg-zinc-800/60 rounded-full font-black text-sm uppercase tracking-widest border border-white/10 italic">Verified</div>
               </div>
            </div>
          </div>
