          <h1 className="text-xl font-black flex items-center gap-3 tracking-tighter uppercase italic">
            <Sparkles className="text-green-400 fill-green-400 w-6 h-6" />
            MUSAIC
          </h1>
        </div>

        <div className="space-y-1">
          <SidebarItem icon={Home} label="Home" active={nav.view === 'home'} onClick={() => navigateTo('home')} />
          <SidebarItem icon={Search} label="Search" active={nav.view === 'search'} onClick={() => navigateTo('search')} />
          <SidebarItem icon={Library} label="Library" active={nav.view === 'library'} onClick={() => navigateTo('library')} />
        </div>

        <div className="mt-8 space-y-1">
          <h3 className="px-4 text-[10px] font-black text-zinc-600 uppercase tracking-[0.2em] mb-2">Mastering</h3>
          <SidebarItem icon={Settings2} label="Editor Hub" active={nav.view === 'creator'} onClick={() => navigateTo('creator')} />
        </div>

        <div className="mt-auto p-4 bg-zinc-900/40 rounded-3xl border border-zinc-800/50 backdrop-blur-xl">
          <div className="flex items-center justify-between mb-3">
            <p className="text-[8px] text-zinc-500 font-black uppercase tracking-widest">Active Database</p>
            <div className="flex items-center gap-1.5">
              <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
              <span className="text-[8px] text-zinc-400 font-black uppercase tracking-widest">Live</span>
            </div>
          </div>
          <div className="space-y-1 text-xs text-zinc-400 font-bold">
            <div className="flex justify-between"><span>Artists</span> <span className="text-white">{artists.length}</span></div>
            <div className="flex justify-between"><span>Albums</span> <span className="text-white">{albums.length}</span></div>
            <div className="flex justify-between"><span>Tracks</span> <span className="text-white">{tracks.length}</span></div>
          </div>
        </div>

        <div 
