              Creator Mode
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto pb-40 scroll-smooth custom-scrollbar">
          {nav.view === 'home' && <HomeView artists={artists} albums={albums} navigateTo={navigateTo} />}
          {nav.view === 'artist' && <ArtistView id={nav.params?.id || ''} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'album' && <AlbumView id={nav.params?.id || ''} albums={albums} tracks={tracks} toggleLikeTrack={toggleLikeTrack} toggleLikeAlbum={toggleLikeAlbum} />}
          {nav.view === 'track' && <TrackPage id={nav.params?.id || ''} tracks={tracks} albums={albums} toggleLikeTrack={toggleLikeTrack} navigateTo={navigateTo} />}
          {nav.view === 'creator' && <CreatorHub artists={artists} setArtists={setArtists} albums={albums} setAlbums={setAlbums} tracks={tracks} setTracks={setTracks} />}
          {nav.view === 'library' && <LibraryView albums={albums} artists={artists} navigateTo={navigateTo} />}
          {nav.view === 'search' && <SearchView query={searchQuery} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
        </div>

        <div className="absolute bottom-0 left-0 right-0 h-24 bg-black/80 backdrop-blur-2xl border-t border-zinc-800/50 flex items-center justify-between px-8 z-[60]">
