              <div className="w-16 h-16 shadow-lg flex-shrink-0">
                <img src={album.coverUrl} className="w-full h-full object-cover" alt={album.title} />
              </div>
              <p className="font-bold text-sm flex-1 truncate pr-2">{album.title}</p>
              <div className="mr-4 w-10 h-10 bg-green-500 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0">
                 <Play className="text-black fill-black ml-0.5 w-5 h-5" />
              </div>
            </div>
          ))}
