                <div className="relative mb-4">
                  <img src={artist.imageUrl} className="w-full aspect-square object-cover rounded-full shadow-lg border-2 border-zinc-800/50" alt={artist.name} />
                  <div className="absolute bottom-1 right-1 w-10 h-10 bg-green-500 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all scale-75 group-hover:scale-100">
                    <Play className="text-black fill-black ml-0.5 w-5 h-5" />
