}

function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks }: CreatorHubProps) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>('artist');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '',
    albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '',
    trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false
  });
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetForm = () => {
    setFormData({
      artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '',
      albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '',
      trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false
    });
    setEditingId(null);
  };

  const handleEdit = (type: string, id: string) => {
    setEditingId(id);
    setActiveTab(type as any);
    if (type === 'artist') {
      const a = artists.find(i => i.id === id)!;
      setFormData({...formData, artistName: a.name, artistBio: a.bio, artistGenre: a.genre, artistFollowers: formatNumber(a.followers), artistVerified: a.verified, artistImg: a.imageUrl});
    } else if (type === 'album') {
      const a = albums.find(i => i.id === id)!;
      setFormData({...formData, albumTitle: a.title, albumArtistId: a.artistId, albumImg: a.coverUrl, albumYear: a.releaseYear, albumGenre: a.genre, albumLabel: a.label || ''});
    } else if (type === 'track') {
      const a = tracks.find(i => i.id === id)!;
      setFormData({...formData, trackTitle: a.title, trackArtistId: a.artistId, trackAlbumId: a.albumId, trackDuration: a.duration, trackPlays: formatNumber(a.plays), trackLikes: formatNumber(a.likes), trackComposer: a.composer || '', trackExplicit: a.isExplicit || false});
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const base64 = await fileToBase64(file);
      const field = activeTab === 'artist' ? 'artistImg' : 'albumImg';
      setFormData({ ...formData, [field]: base64 });
    }
  };

  const saveArtist = () => {
    if (!formData.artistName) return;
    const followers = parseFormattedNumber(formData.artistFollowers);
    if (editingId) {
      setArtists(prev => prev.map(a => a.id === editingId ? { ...a, name: formData.artistName, bio: formData.artistBio, genre: formData.artistGenre, followers, verified: formData.artistVerified, imageUrl: formData.artistImg || a.imageUrl } : a));
    } else {
      const newArtist: Artist = {
        id: Math.random().toString(36).substr(2, 9),
        name: formData.artistName, bio: formData.artistBio, imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
        genre: formData.artistGenre, followers, verified: formData.artistVerified
      };
      setArtists([...artists, newArtist]);
    }
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId)!;
    if (editingId) {
      setAlbums(prev => prev.map(a => a.id === editingId ? { ...a, title: formData.albumTitle, artistId: artist.id, artistName: artist.name, coverUrl: formData.albumImg || a.coverUrl, releaseYear: Number(formData.albumYear), genre: formData.albumGenre, label: formData.albumLabel } : a));
    } else {
      const newAlbum: Album = {
        id: Math.random().toString(36).substr(2, 9), title: formData.albumTitle, artistId: artist.id, artistName: artist.name,
        coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`, releaseYear: Number(formData.albumYear),
        genre: formData.albumGenre, isLiked: false, label: formData.albumLabel
      };
      setAlbums([...albums, newAlbum]);
    }
    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId)!;
    const album = albums.find(a => a.id === formData.trackAlbumId);
    const plays = parseFormattedNumber(formData.trackPlays);
    const likes = parseFormattedNumber(formData.trackLikes);

    if (editingId) {
      setTracks(prev => prev.map(t => t.id === editingId ? { ...t, title: formData.trackTitle, artistId: artist.id, artistName: artist.name, albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays, likes, composer: formData.trackComposer, isExplicit: formData.trackExplicit } : t));
    } else {
      const newTrack: Track = {
        id: Math.random().toString(36).substr(2, 9), title: formData.trackTitle, artistId: artist.id, artistName: artist.name,
        albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays, likes,
        isLiked: false, composer: formData.trackComposer, isExplicit: formData.trackExplicit
      };
      setTracks([...tracks, newTrack]);
    }
    resetForm();
  };

  const fillRealisticStats = () => {
    if (activeTab === 'artist') {
      setFormData({...formData, artistFollowers: formatNumber(getRandomValue(1000, 5000000))});
    } else if (activeTab === 'track') {
      const plays = getRandomValue(50000, 10000000);
      const likes = Math.floor(plays * (getRandomValue(1, 5) / 100)); // 1-5% like ratio
      setFormData({...formData, trackPlays: formatNumber(plays), trackLikes: formatNumber(likes)});
    }
  };

  const generateAIBio = async () => {
    if (!formData.artistName) return;
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Write a futuristic musician bio for "${formData.artistName}" (${formData.artistGenre}). Max 2 short sentences.`
      });
      setFormData({ ...formData, artistBio: response.text?.trim() });
    } catch (e) {
      setFormData({ ...formData, artistBio: "A mysterious force in the digital soundscape." });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-8 max-w-5xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-12 bg-zinc-900/30 p-8 rounded-[3rem] border border-zinc-800/50 backdrop-blur-2xl">
        <div>
          <h2 className="text-3xl font-black tracking-tighter italic">Studio Hub</h2>
          <p className="text-sm text-zinc-600 font-bold">Refining the library signal.</p>
        </div>
        <div className="flex gap-2 p-1 bg-black rounded-2xl border border-zinc-800">
          {['artist', 'album', 'track', 'manage'].map((t) => (
            <button 
              key={t}
              onClick={() => { setActiveTab(t as any); resetForm(); }}
              className={`px-6 py-2 rounded-xl font-bold text-sm transition-all capitalize ${activeTab === t ? 'bg-zinc-700 text-white' : 'text-zinc-500 hover:text-white'}`}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-8">
            <div className="bg-zinc-900/20 backdrop-blur-md p-8 rounded-[3rem] border border-zinc-800/50 space-y-6 shadow-2xl">
              {activeTab === 'artist' && (
                <>
                  <InputGroup label="Name" placeholder="Creator Name" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                  <div className="grid grid-cols-2 gap-6">
                    <InputGroup label="Main Genre" placeholder="Synth" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                    <InputGroup label="Followers" type="text" numeric value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                  </div>
                  <div className="space-y-3">
                    <div className="flex justify-between items-center px-2">
                      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Artist Story</label>
                      <button onClick={generateAIBio} disabled={loading} className="text-[10px] font-black text-green-400 flex items-center gap-2 hover:scale-105 transition-all">
                        {loading ? 'WEAVING...' : <><Sparkles className="w-3 h-3" /> AI BIO</>}
                      </button>
                    </div>
                    <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} rows={3} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 focus:border-green-400/50 outline-none transition-all resize-none text-base font-bold tracking-tight" />
                  </div>
                  <button onClick={saveArtist} className="w-full py-4 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] active:scale-[0.98] transition-all shadow-xl">
                    {editingId ? 'Update Record' : 'Publish Creator'}
                  </button>
                </>
              )}

              {activeTab === 'album' && (
                <>
                  <InputGroup label="Album Title" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                  <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">Primary Artist</label>
                      <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 font-bold text-sm outline-none cursor-pointer">
                        <option value="">Choose Artist...</option>
                        {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                      </select>
                    </div>
                    <InputGroup label="Label" placeholder="Independent" value={formData.albumLabel} onChange={v => setFormData({...formData, albumLabel: v})} />
                  </div>
                  <div className="grid grid-cols-2 gap-6">
                    <InputGroup label="Year" type="number" value={formData.albumYear} onChange={v => setFormData({...formData, albumYear: v})} />
                    <InputGroup label="Style" placeholder="Neo-Soul" value={formData.albumGenre} onChange={v => setFormData({...formData, albumGenre: v})} />
                  </div>
                  <button onClick={saveAlbum} className="w-full py-4 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] transition-all shadow-xl">
                    {editingId ? 'Save Edits' : 'Deploy Archive'}
                  </button>
                </>
              )}

              {activeTab === 'track' && (
                <>
                  <InputGroup label="Track Title" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                  <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">Artist</label>
                      <select value={formData.trackArtistId} onChange={e => setFormData({...formData, trackArtistId: e.target.value, trackAlbumId: ''})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 font-bold text-sm outline-none cursor-pointer">
                        <option value="">Choose Artist...</option>
                        {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">Album</label>
                      <select value={formData.trackAlbumId} onChange={e => setFormData({...formData, trackAlbumId: e.target.value})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 font-bold text-sm outline-none cursor-pointer">
                        <option value="single">Single</option>
                        {albums.filter(a => a.artistId === formData.trackArtistId).map(a => <option key={a.id} value={a.id}>{a.title}</option>)}
                      </select>
                    </div>
                  </div>
                  <InputGroup label="Composer" placeholder="Full Name" value={formData.trackComposer} onChange={v => setFormData({...formData, trackComposer: v})} />
                  <div className="grid grid-cols-3 gap-6">
                    <InputGroup label="Duration" placeholder="3:30" value={formData.trackDuration} onChange={v => setFormData({...formData, trackDuration: v})} />
                    <InputGroup label="Plays" numeric value={formData.trackPlays} onChange={v => setFormData({...formData, trackPlays: v})} />
                    <InputGroup label="Likes" numeric value={formData.trackLikes} onChange={v => setFormData({...formData, trackLikes: v})} />
                  </div>
                  <div className="flex items-center gap-6 px-2">
                    <label className="flex items-center gap-3 cursor-pointer">
                       <input type="checkbox" checked={formData.trackExplicit} onChange={e => setFormData({...formData, trackExplicit: e.target.checked})} className="w-4 h-4 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0" />
                       <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Explicit Content</span>
                    </label>
                  </div>
                  <button onClick={saveTrack} className="w-full py-4 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] transition-all shadow-xl">
                    {editingId ? 'Apply Patch' : 'Release Signal'}
                  </button>
                </>
              )}
            </div>
          </div>
        )}

        {activeTab !== 'manage' && (
          <div className="space-y-8">
            <div className="bg-zinc-900/20 backdrop-blur-md p-6 rounded-[2rem] border border-zinc-800/50 text-center shadow-3xl">
              <h3 className="text-[10px] font-black text-zinc-600 mb-6 uppercase tracking-[0.2em]">Cover Identification</h3>
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="w-full aspect-square bg-zinc-800/40 rounded-3xl border-2 border-dashed border-zinc-700 flex flex-col items-center justify-center cursor-pointer hover:border-green-500 transition-all overflow-hidden relative shadow-inner"
              >
                {(activeTab === 'artist' ? formData.artistImg : formData.albumImg) ? (
                  <img src={activeTab === 'artist' ? formData.artistImg : formData.albumImg} className="w-full h-full object-cover" key={activeTab} />
                ) : (
                  <>
                    <ImageIcon className="w-10 h-10 text-zinc-700 mb-4" />
                    <p className="text-[8px] font-black text-zinc-600 uppercase tracking-widest">Target Image</p>
                  </>
                )}
                <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity">
                   <Upload className="w-8 h-8 text-white" />
                </div>
              </div>
              <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
            </div>

            {(activeTab === 'artist' || activeTab === 'track') && (
              <div className="bg-gradient-to-br from-green-500/10 to-transparent p-6 rounded-[2rem] border border-green-500/20 shadow-2xl">
                <h4 className="text-lg font-black mb-2 flex items-center gap-3 italic">
                  <Dices className="text-green-400 w-5 h-5" />
                  Magic Stats
                </h4>
                <p className="text-[10px] text-zinc-600 font-bold mb-6 leading-relaxed opacity-80">Pre-fill the form with realistic signal data based on current audio trends.</p>
                <button onClick={fillRealisticStats} className="w-full py-3 bg-green-500 text-black font-black text-xs rounded-xl hover:scale-105 active:scale-95 transition-all shadow-xl shadow-green-500/10 uppercase tracking-widest">
                  Generate Frequencies
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'manage' && (
          <div className="col-span-1 md:col-span-3 space-y-12 animate-in">
             <ManagementSection title="Artists" items={artists} onDelete={id => setArtists(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('artist', id)} icon={User} />
             <ManagementSection title="Albums" items={albums} onDelete={id => setAlbums(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('album', id)} icon={Disc} />
             <ManagementSection title="Tracks" items={tracks} onDelete={id => setTracks(prev => prev.filter(t => t.id !== id))} onEdit={id => handleEdit('track', id)} icon={Music} />
          </div>
        )}
      </div>
    </div>
  );
}

const InputGroup = ({ label, type = 'text', numeric, placeholder, value, onChange }: { label: string, type?: string, numeric?: boolean, placeholder?: string, value: any, onChange: (v: string) => void }) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (numeric) {
      const val = e.target.value.replace(/\D/g, '');
      const num = parseInt(val) || 0;
      onChange(formatNumber(num));
    } else {
      onChange(e.target.value);
    }
  };

  return (
    <div className="space-y-3">
      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">{label}</label>
      <input 
        type={numeric ? 'text' : type} 
        value={value} 
        onChange={handleChange}
        placeholder={placeholder} 
        className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 focus:border-green-400/50 outline-none transition-all text-sm font-bold tracking-tight"
      />
    </div>
  );
};

const ManagementSection = ({ title, items, onDelete, onEdit, icon: Icon }: { title: string, items: any[], onDelete: (id: string) => void, onEdit: (id: string) => void, icon: any }) => (
  <div className="space-y-6">
    <h3 className="text-xl font-black flex items-center gap-4 italic px-2">
      <Icon className="w-6 h-6 text-zinc-700" />
      {title} <span className="text-xs text-zinc-800 font-black">({items.length})</span>
    </h3>
    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
      {items.map(item => (
        <div key={item.id} className="bg-zinc-900/30 p-4 rounded-3xl border border-zinc-800/50 flex flex-col gap-4 group hover:bg-zinc-800/60 transition-all relative overflow-hidden shadow-lg">
          <div className="w-full aspect-square bg-zinc-800 rounded-2xl overflow-hidden shadow-inner">
            <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/200/200`} className="w-full h-full object-cover group-hover:scale-105 transition-all" />
          </div>
          <div className="min-w-0">
            <p className="text-sm font-bold truncate tracking-tight mb-0.5">{item.name || item.title}</p>
            <p className="text-[8px] text-zinc-600 font-black uppercase tracking-widest truncate">{item.genre || item.artistName || 'Creator'}</p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => onEdit(item.id)} className="flex-1 py-1.5 bg-zinc-800 rounded-lg text-[10px] font-black uppercase hover:bg-white hover:text-black transition-all">Edit</button>
            <button onClick={() => onDelete(item.id)} className="p-1.5 bg-red-500/10 text-red-500 rounded-lg hover:bg-red-500 hover:text-white transition-all">
              <Trash2 className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      ))}
      {items.length === 0 && <p className="text-xs font-black text-zinc-800 italic px-4 opacity-40">Section Standby.</p>}
    </div>
  </div>
);

function TrackPage({ id, tracks, albums, toggleLikeTrack, navigateTo }: TrackViewProps) {
  const track = tracks.find(t => t.id === id);
  if (!track) return <div className="p-20 text-center text-xl font-black italic">Signal Lost.</div>;
  const album = albums.find(a => a.id === track.albumId);

  return (
    <div className="min-h-full flex flex-col p-8 bg-gradient-to-b from-zinc-800/30 to-black animate-in">
      <div className="flex flex-col md:flex-row items-center gap-12 mt-12">
        <div className="w-64 h-64 md:w-80 md:h-80 shadow-2xl rounded-[2.5rem] overflow-hidden border-4 border-white/5 flex-shrink-0">
          <img src={album?.coverUrl || 'https://picsum.photos/seed/default/400/400'} className="w-full h-full object-cover" />
        </div>
        <div className="flex flex-col items-center md:items-start text-center md:text-left min-w-0">
          <span className="text-[10px] font-black uppercase tracking-[0.4em] mb-4 text-green-400">Signal Information</span>
          <h1 className="text-5xl md:text-7xl font-black mb-6 tracking-tighter leading-none italic break-words w-full">{track.title}</h1>
          <div 
            onClick={() => navigateTo('artist', { id: track.artistId })}
            className="flex items-center gap-4 text-xl font-black hover:text-green-400 cursor-pointer transition-all tracking-tighter mb-8"
          >
            <PenTool className="w-5 h-5 opacity-40" />
            {track.artistName}
          </div>
          <div className="flex flex-wrap gap-8 items-center text-zinc-500 font-black uppercase tracking-widest text-[10px]">
             <div className="flex flex-col gap-1">
               <span className="opacity-40">Plays</span>
               <span className="text-white text-xl tabular-nums">{formatNumber(track.plays)}</span>
             </div>
