                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Artists, songs, albums..." 
                  className="bg-zinc-800/60 hover:bg-zinc-800 border-none rounded-full py-2 pl-10 pr-6 w-80 text-sm font-bold tracking-tight focus:ring-4 focus:ring-green-500/10 transition-all outline-none"
                />
              </div>
            )}
          </div>
          <div className="flex items-center gap-4">
            <div className="bg-zinc-800/80 px-4 py-1.5 rounded-full text-[10px] font-black border border-white/5 flex items-center gap-2 cursor-default uppercase">
              <Zap className="w-3 h-3 text-green-400 fill-green-400" />
              Creator Mode
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto pb-40 scroll-smooth custom-scrollbar">
          {nav.view === 'home' && <HomeView artists={artists} albums={albums} navigateTo={navigateTo} />}
          {nav.view === 'artist' && <ArtistView id={nav.params?.id || ''} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'album' && <AlbumView id={nav.params?.id || ''} albums={albums} tracks={tracks} toggleLikeTrack={toggleLikeTrack} toggleLikeAlbum={toggleLikeAlbum} navigateTo={navigateTo} />}
          {nav.view === 'track' && <TrackPage id={nav.params?.id || ''} tracks={tracks} albums={albums} toggleLikeTrack={toggleLikeTrack} navigateTo={navigateTo} />}
          {nav.view === 'creator' && <CreatorHub artists={artists} setArtists={setArtists} albums={albums} setAlbums={setAlbums} tracks={tracks} setTracks={setTracks} />}
          {nav.view === 'library' && <LibraryView albums={albums} artists={artists} navigateTo={navigateTo} />}
          {nav.view === 'search' && <SearchView query={searchQuery} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
        </div>

        <div className="absolute bottom-0 left-0 right-0 h-24 bg-black/80 backdrop-blur-2xl border-t border-zinc-800/50 flex items-center justify-between px-8 z-[60]">
           <div className="flex items-center gap-4 w-1/3 min-w-0">
            <div className="w-14 h-14 bg-zinc-800 rounded-xl overflow-hidden shadow-xl flex-shrink-0 group relative">
              <img src="https://picsum.photos/seed/placeholder/200/200" alt="Current" className="w-full h-full object-cover" />
            </div>
            <div className="min-w-0">
              <p className="text-sm font-bold truncate tracking-tight">Select a track</p>
              <p className="text-xs text-zinc-500 font-bold uppercase tracking-widest truncate opacity-60">System Standby</p>
            </div>
          </div>

          <div className="flex flex-col items-center gap-2 w-1/3">
            <div className="flex items-center gap-6">
              <button className="text-zinc-600 hover:text-white transition-all"><Disc className="w-5 h-5" /></button>
              <button className="w-10 h-10 bg-white rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all">
                <Play className="w-5 h-5 text-black fill-black ml-0.5" />
              </button>
              <button className="text-zinc-600 hover:text-white transition-all"><MoreHorizontal className="w-5 h-5" /></button>
            </div>
            <div className="w-full max-w-sm flex items-center gap-3">
              <span className="text-[10px] font-bold text-zinc-700">0:00</span>
              <div className="flex-1 h-1 bg-zinc-800 rounded-full relative overflow-hidden">
                <div className="w-0 h-full bg-zinc-300"></div>
              </div>
              <span className="text-[10px] font-bold text-zinc-700">3:30</span>
            </div>
          </div>

          <div className="flex items-center justify-end gap-5 w-1/3 text-zinc-600">
             <Mic2 className="w-4 h-4 hover:text-white cursor-pointer" />
             <ListMusic className="w-4 h-4 hover:text-white cursor-pointer" />
             <div className="flex items-center gap-3">
               <Music className="w-4 h-4" />
               <div className="w-20 h-1 bg-zinc-800 rounded-full overflow-hidden">
                 <div className="w-3/4 h-full bg-zinc-500"></div>
               </div>
             </div>
          </div>
        </div>
      </main>
    </div>
  );
}

// --- Internal Views ---

function HomeView({ artists, albums, navigateTo }: HomeViewProps) {
  return (
    <div className="p-8 animate-in">
      <h2 className="text-4xl font-black mb-8 tracking-tighter italic">Library Discoveries</h2>

      {albums.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-12">
          {albums.slice(0, 6).map(album => (
            <div key={album.id} onClick={() => navigateTo('album', { id: album.id })} className="group flex items-center gap-4 bg-zinc-800/20 hover:bg-zinc-800/40 transition-all rounded-2xl overflow-hidden cursor-pointer border border-white/5">
              <div className="w-16 h-16 shadow-lg flex-shrink-0">
                <img src={album.coverUrl} className="w-full h-full object-cover" alt={album.title} />
              </div>
              <p className="font-bold text-sm flex-1 truncate pr-2">{album.title}</p>
              <div className="mr-4 w-10 h-10 bg-green-500 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0">
                 <Play className="text-black fill-black ml-0.5 w-5 h-5" />
              </div>
            </div>
          ))}
        </div>
      )}

      {artists.length > 0 && (
        <>
          <SectionTitle title="Artists" />
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-6">
            {artists.map(artist => (
              <div key={artist.id} onClick={() => navigateTo('artist', { id: artist.id })} className="bg-zinc-900/40 p-5 rounded-[2.5rem] hover:bg-zinc-800/60 transition-all cursor-pointer group shadow-xl">
                <div className="relative mb-4">
                  <img src={artist.imageUrl} className="w-full aspect-square object-cover rounded-full shadow-lg border-2 border-zinc-800/50" alt={artist.name} />
                  <div className="absolute bottom-1 right-1 w-10 h-10 bg-green-500 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all scale-75 group-hover:scale-100">
                    <Play className="text-black fill-black ml-0.5 w-5 h-5" />
                  </div>
                </div>
                <p className="font-bold truncate text-base tracking-tight mb-1">{artist.name}</p>
                <p className="text-zinc-600 text-[10px] font-black uppercase tracking-widest opacity-60">Verified</p>
              </div>
            ))}
