function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks }: CreatorHubProps) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>('artist');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '',
    albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '',
    trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: ''
  });
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetForm = () => {
    setFormData({
      artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '',
      albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '',
      trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: ''
    });
    setEditingId(null);
  };

  const handleEdit = (type: string, id: string) => {
    setEditingId(id);
    setActiveTab(type as any);
    if (type === 'artist') {
      const a = artists.find(i => i.id === id)!;
      setFormData({...formData, artistName: a.name, artistBio: a.bio, artistGenre: a.genre, artistFollowers: formatNumber(a.followers), artistVerified: a.verified, artistImg: a.imageUrl});
    } else if (type === 'album') {
      const a = albums.find(i => i.id === id)!;
      setFormData({...formData, albumTitle: a.title, albumArtistId: a.artistId, albumImg: a.coverUrl, albumYear: a.releaseYear, albumGenre: a.genre, albumLabel: a.label || ''});
    } else if (type === 'track') {
      const a = tracks.find(i => i.id === id)!;
      setFormData({...formData, trackTitle: a.title, trackArtistId: a.artistId, trackAlbumId: a.albumId, trackDuration: a.duration, trackPlays: formatNumber(a.plays), trackLikes: formatNumber(a.likes), trackComposer: a.composer || '', trackExplicit: a.isExplicit || false, trackImg: a.coverUrl || ''});
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const base64 = await fileToBase64(file);
      let field = '';
      if (activeTab === 'artist') field = 'artistImg';
      else if (activeTab === 'album') field = 'albumImg';
      else field = 'trackImg';
      setFormData({ ...formData, [field]: base64 });
    }
  };

  const saveArtist = () => {
    if (!formData.artistName) return;
    const followers = parseFormattedNumber(formData.artistFollowers);
    if (editingId) {
      setArtists(prev => prev.map(a => a.id === editingId ? { ...a, name: formData.artistName, bio: formData.artistBio, genre: formData.artistGenre, followers, verified: formData.artistVerified, imageUrl: formData.artistImg || a.imageUrl } : a));
    } else {
      const newArtist: Artist = {
        id: Math.random().toString(36).substr(2, 9),
        name: formData.artistName, bio: formData.artistBio, imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
        genre: formData.artistGenre, followers, verified: formData.artistVerified
      };
      setArtists([...artists, newArtist]);
    }
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId)!;
    if (editingId) {
      setAlbums(prev => prev.map(a => a.id === editingId ? { ...a, title: formData.albumTitle, artistId: artist.id, artistName: artist.name, coverUrl: formData.albumImg || a.coverUrl, releaseYear: Number(formData.albumYear), genre: formData.albumGenre, label: formData.albumLabel } : a));
    } else {
      const newAlbum: Album = {
        id: Math.random().toString(36).substr(2, 9), title: formData.albumTitle, artistId: artist.id, artistName: artist.name,
        coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`, releaseYear: Number(formData.albumYear),
        genre: formData.albumGenre, isLiked: false, label: formData.albumLabel
      };
      setAlbums([...albums, newAlbum]);
    }
    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId)!;
    const album = albums.find(a => a.id === formData.trackAlbumId);
    const plays = parseFormattedNumber(formData.trackPlays);
    const likes = parseFormattedNumber(formData.trackLikes);

    if (editingId) {
      setTracks(prev => prev.map(t => t.id === editingId ? { ...t, title: formData.trackTitle, artistId: artist.id, artistName: artist.name, albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays, likes, composer: formData.trackComposer, isExplicit: formData.trackExplicit, coverUrl: formData.trackImg || t.coverUrl } : t));
    } else {
      const newTrack: Track = {
        id: Math.random().toString(36).substr(2, 9), title: formData.trackTitle, artistId: artist.id, artistName: artist.name,
        albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays, likes,
        isLiked: false, composer: formData.trackComposer, isExplicit: formData.trackExplicit, coverUrl: formData.trackImg || `https://picsum.photos/seed/${formData.trackTitle}/400/400`
      };
      setTracks([...tracks, newTrack]);
    }
    resetForm();
  };

  const fillRealisticStats = () => {
    if (activeTab === 'artist') {
      setFormData({...formData, artistFollowers: formatNumber(getRandomValue(50000, 5000000))});
    } else if (activeTab === 'track') {
      const plays = getRandomValue(100000, 10000000); // 100k to 10M
      const likes = Math.floor(plays * (getRandomValue(2, 6) / 100)); // 2-6% like ratio
      setFormData({...formData, trackPlays: formatNumber(plays), trackLikes: formatNumber(likes)});
    }
  };

  const generateAIBio = async () => {
    if (!formData.artistName) return;
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Write a punchy futuristic musician bio for "${formData.artistName}" who plays ${formData.artistGenre}. 2 short sentences.`
      });
      setFormData({ ...formData, artistBio: response.text?.trim() });
    } catch (e) {
      setFormData({ ...formData, artistBio: "A sonic architect pushing boundaries." });
    } finally {
      setLoading(false);
    }
  };

  const exportDB = () => {
    const db = { artists, albums, tracks };
    const blob = new Blob([JSON.stringify(db, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `musaic_database_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
  };

  const importDB = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        try {
          const db = JSON.parse(ev.target?.result as string);
          if (db.artists) setArtists(db.artists);
          if (db.albums) setAlbums(db.albums);
          if (db.tracks) setTracks(db.tracks);
          alert("Database Synced Successfully.");
        } catch (e) {
          alert("Invalid Database File.");
        }
      };
      reader.readAsText(file);
    }
  };

  return (
    <div className="p-10 max-w-6xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-16 bg-zinc-900/40 p-10 rounded-[4rem] border border-zinc-800/50 backdrop-blur-3xl shadow-3xl">
        <div>
          <h2 className="text-5xl font-black tracking-tighter italic leading-none mb-3">Protocol Hub</h2>
          <p className="text-lg text-zinc-600 font-black italic tracking-tight">Direct Library Modification Sequence.</p>
        </div>
        <div className="flex gap-4 p-2 bg-black rounded-[2.5rem] border border-zinc-800">
          {['artist', 'album', 'track', 'manage'].map((t) => (
            <button 
              key={t}
              onClick={() => { setActiveTab(t as any); resetForm(); }}
              className={`px-8 py-3 rounded-2xl font-black text-base transition-all capitalize italic ${activeTab === t ? 'bg-zinc-700 text-white shadow-xl' : 'text-zinc-500 hover:text-white'}`}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-10">
            <div className="bg-zinc-900/20 backdrop-blur-md p-10 rounded-[4rem] border border-zinc-800/50 space-y-8 shadow-2xl">
              {activeTab === 'artist' && (
                <>
                  <InputGroup label="Creator Designation" placeholder="e.g. SOLARA" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                  <div className="grid grid-cols-2 gap-8">
                    <InputGroup label="Core Spectrum (Genre)" placeholder="Glitch-Pop" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                    <InputGroup label="Subscribers" numeric value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                  </div>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center px-4">
                      <label className="text-[11px] font-black text-zinc-500 uppercase tracking-widest italic opacity-80">Narrative Trace</label>
                      <button onClick={generateAIBio} disabled={loading} className="text-[11px] font-black text-green-400 flex items-center gap-3 hover:scale-105 transition-all italic">
                        {loading ? 'WEAVING...' : <><Sparkles className="w-4 h-4" /> AI DEPLOY</>}
                      </button>
                    </div>
