            <div key={genre} className="bg-zinc-800/40 aspect-video rounded-[3.5rem] p-10 relative overflow-hidden group cursor-pointer shadow-[0_40px_80px_-20px_rgba(0,0,0,0.8)] border border-white/5 hover:bg-zinc-700/40 transition-all">
              <span className="text-4xl lg:text-5xl font-black relative z-10 tracking-tighter italic leading-none">{genre}</span>
              <img src={`https://picsum.photos/seed/${genre}/600/400`} className="absolute bottom-0 right-0 w-44 h-44 rotate-[30deg] translate-x-12 translate-y-12 group-hover:scale-125 transition-transform opacity-40 mix-blend-screen grayscale group-hover:grayscale-0" alt={genre} />
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-12">
      {filteredArtists.length > 0 && (
        <div className="mb-20">
          <SectionTitle title="Detected Identities" />
          <div className="flex gap-10 overflow-x-auto pb-10 custom-scrollbar">
            {filteredArtists.map((a) => (
              <div key={a.id} onClick={() => navigateTo('artist', { id: a.id })} className="flex-shrink-0 w-64 bg-zinc-900/30 p-10 rounded-[3.5rem] hover:bg-zinc-800/50 transition-all cursor-pointer shadow-2xl">
                <img src={a.imageUrl} className="w-full aspect-square object-cover rounded-full mb-8 shadow-2xl" alt={a.name} />
                <p className="font-black truncate text-2xl tracking-tighter text-center italic uppercase">{a.name}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {filteredTracks.length > 0 && (
        <div className="mb-20">
          <SectionTitle title="Captured Signals" />
          <div className="space-y-2 max-w-5xl">
            {filteredTracks.map((t, i) => (
              <TrackRow key={t.id} track={t} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: t.id })} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

