function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks }: CreatorHubProps) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>('artist');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '',
    albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '',
    trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: ''
  });
  const [inlineTracks, setInlineTracks] = useState<{title: string, duration: string, explicit: boolean}[]>([]);
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetForm = () => {
    setFormData({
      artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '',
      albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '',
      trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: ''
    });
    setInlineTracks([]);
    setEditingId(null);
  };

  const handleEdit = (type: string, id: string) => {
    setEditingId(id);
    setActiveTab(type as any);
    if (type === 'artist') {
      const a = artists.find(i => i.id === id)!;
      setFormData({...formData, artistName: a.name, artistBio: a.bio, artistGenre: a.genre, artistFollowers: formatNumber(a.followers), artistVerified: a.verified, artistImg: a.imageUrl});
    } else if (type === 'album') {
      const a = albums.find(i => i.id === id)!;
      setFormData({...formData, albumTitle: a.title, albumArtistId: a.artistId, albumImg: a.coverUrl, albumYear: a.releaseYear, albumGenre: a.genre, albumLabel: a.label || ''});
    } else if (type === 'track') {
      const a = tracks.find(i => i.id === id)!;
      setFormData({...formData, trackTitle: a.title, trackArtistId: a.artistId, trackAlbumId: a.albumId, trackDuration: a.duration, trackPlays: formatNumber(a.plays), trackLikes: formatNumber(a.likes), trackComposer: a.composer || '', trackExplicit: a.isExplicit || false, trackImg: a.coverUrl || ''});
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const base64 = await fileToBase64(file);
      const field = activeTab === 'artist' ? 'artistImg' : (activeTab === 'album' ? 'albumImg' : 'trackImg');
      setFormData({ ...formData, [field]: base64 });
    }
  };

  const saveArtist = () => {
    if (!formData.artistName) return;
    const followers = parseFormattedNumber(formData.artistFollowers);
    if (editingId) {
      setArtists(prev => prev.map(a => a.id === editingId ? { ...a, name: formData.artistName, bio: formData.artistBio, genre: formData.artistGenre, followers, verified: formData.artistVerified, imageUrl: formData.artistImg || a.imageUrl } : a));
    } else {
      const newArtist: Artist = {
        id: Math.random().toString(36).substr(2, 9),
        name: formData.artistName, bio: formData.artistBio, imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
        genre: formData.artistGenre, followers, verified: formData.artistVerified
      };
      setArtists([...artists, newArtist]);
    }
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId)!;
    const albumId = editingId || Math.random().toString(36).substr(2, 9);

    if (editingId) {
      setAlbums(prev => prev.map(a => a.id === editingId ? { ...a, title: formData.albumTitle, artistId: artist.id, artistName: artist.name, coverUrl: formData.albumImg || a.coverUrl, releaseYear: Number(formData.albumYear), genre: formData.albumGenre, label: formData.albumLabel } : a));
    } else {
      const newAlbum: Album = {
        id: albumId, title: formData.albumTitle, artistId: artist.id, artistName: artist.name,
        coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`, releaseYear: Number(formData.albumYear),
        genre: formData.albumGenre, isLiked: false, label: formData.albumLabel
      };
      setAlbums([...albums, newAlbum]);
    }

    // Process inline tracks
    if (inlineTracks.length > 0) {
      const newTracks: Track[] = inlineTracks.map(t => ({
        id: Math.random().toString(36).substr(2, 9),
        title: t.title,
        artistId: artist.id,
        artistName: artist.name,
        albumId: albumId,
        albumTitle: formData.albumTitle,
        duration: t.duration,
        plays: getRandomValue(100000, 10000000),
        likes: getRandomValue(1000, 500000),
        isLiked: false,
        isExplicit: t.explicit,
        coverUrl: formData.albumImg || ''
      }));
      setTracks(prev => [...prev, ...newTracks]);
    }

    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId)!;
    const album = albums.find(a => a.id === formData.trackAlbumId);
    const plays = parseFormattedNumber(formData.trackPlays);
    const likes = parseFormattedNumber(formData.trackLikes);

    if (editingId) {
      setTracks(prev => prev.map(t => t.id === editingId ? { ...t, title: formData.trackTitle, artistId: artist.id, artistName: artist.name, albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays, likes, composer: formData.trackComposer, isExplicit: formData.trackExplicit, coverUrl: formData.trackImg || t.coverUrl } : t));
    } else {
      const newTrack: Track = {
        id: Math.random().toString(36).substr(2, 9), title: formData.trackTitle, artistId: artist.id, artistName: artist.name,
        albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays, likes,
        isLiked: false, composer: formData.trackComposer, isExplicit: formData.trackExplicit, coverUrl: formData.trackImg || `https://picsum.photos/seed/${formData.trackTitle}/400/400`
      };
      setTracks([...tracks, newTrack]);
    }
    resetForm();
  };

  const fillRealisticStats = () => {
    if (activeTab === 'artist') {
      setFormData({...formData, artistFollowers: formatNumber(getRandomValue(100000, 10000000))});
    } else if (activeTab === 'track') {
      const plays = getRandomValue(100000, 10000000);
      const likes = Math.floor(plays * (getRandomValue(2, 6) / 100)); 
      setFormData({...formData, trackPlays: formatNumber(plays), trackLikes: formatNumber(likes)});
    }
  };

  const addInlineTrack = () => {
    setInlineTracks([...inlineTracks, {title: '', duration: '3:30', explicit: false}]);
  };

  const exportDB = () => {
    const db = { artists, albums, tracks };
    const blob = new Blob([JSON.stringify(db, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `musaic_db_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
  };

  const importDB = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        try {
          const db = JSON.parse(ev.target?.result as string);
          if (db.artists) setArtists(db.artists);
          if (db.albums) setAlbums(db.albums);
          if (db.tracks) setTracks(db.tracks);
          alert("Database Synced.");
        } catch (e) { alert("Invalid File."); }
      };
      reader.readAsText(file);
    }
  };

  return (
    <div className="p-8 max-w-5xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-12 bg-zinc-900/30 p-8 rounded-[3rem] border border-zinc-800/50 backdrop-blur-3xl shadow-2xl">
        <div>
          <h2 className="text-4xl font-black tracking-tighter italic leading-none mb-2">Protocol Hub</h2>
          <p className="text-sm text-zinc-600 font-black italic tracking-tight">Signal Library Interface.</p>
        </div>
        <div className="flex gap-2 p-1 bg-black rounded-2xl border border-zinc-800">
          {['artist', 'album', 'track', 'manage'].map((t) => (
            <button 
              key={t}
              onClick={() => { setActiveTab(t as any); resetForm(); }}
              className={`px-6 py-2 rounded-xl font-black text-xs transition-all capitalize italic ${activeTab === t ? 'bg-zinc-700 text-white shadow-lg' : 'text-zinc-500 hover:text-white'}`}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-8">
            <div className="bg-zinc-900/20 backdrop-blur-md p-8 rounded-[3rem] border border-zinc-800/50 space-y-6 shadow-2xl">
              {activeTab === 'artist' && (
                <>
                  <InputGroup label="Creator Identity" placeholder="Artist Name" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                  <div className="grid grid-cols-2 gap-6">
                    <InputGroup label="Primary Genre" placeholder="Synth-Wave" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                    <InputGroup label="Nodes (Followers)" numeric value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                  </div>
                  <div className="flex items-center gap-4 px-2">
                    <label className="flex items-center gap-3 cursor-pointer group">
                      <input type="checkbox" checked={formData.artistVerified} onChange={e => setFormData({...formData, artistVerified: e.target.checked})} className="w-5 h-5 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500 group-hover:text-white transition-colors italic">Authorized Identity (Verified)</span>
                    </label>
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2 italic opacity-80">Manifesto (Bio)</label>
                    <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} rows={3} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 focus:border-green-400/50 outline-none transition-all resize-none text-base font-black tracking-tight italic" />
                  </div>
                  <button onClick={saveArtist} className="w-full py-5 bg-white text-black font-black text-xl rounded-2xl hover:scale-[1.02] active:scale-[0.98] transition-all shadow-xl">
                    {editingId ? 'Patch Protocol' : 'Deploy Identity'}
                  </button>
                </>
              )}

              {activeTab === 'album' && (
                <>
                  <InputGroup label="Collection Signal (Album)" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                  <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2 italic opacity-80">Assigned Artist</label>
                      <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 font-black text-sm outline-none cursor-pointer italic appearance-none">
                        <option value="">Choose Creator...</option>
                        {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                      </select>
                    </div>
                    <InputGroup label="Sub-Frequency (Genre)" value={formData.albumGenre} onChange={v => setFormData({...formData, albumGenre: v})} />
                  </div>

                  {!editingId && (
                    <div className="space-y-4 pt-4 border-t border-zinc-800/50">
                      <div className="flex items-center justify-between px-2">
                        <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest italic opacity-80">Signal Streams (Tracks)</label>
                        <button onClick={addInlineTrack} className="text-[10px] font-black text-green-400 flex items-center gap-1.5 hover:scale-105 transition-all">
                          <Plus className="w-3 h-3" /> ADD SIGNAL
                        </button>
                      </div>
                      <div className="space-y-2">
                        {inlineTracks.map((t, i) => (
                          <div key={i} className="grid grid-cols-[1fr_80px_40px] gap-3 items-center">
                            <input placeholder="Track Title" value={t.title} onChange={e => {
                              const next = [...inlineTracks];
                              next[i].title = e.target.value;
                              setInlineTracks(next);
                            }} className="bg-zinc-800/40 border-none rounded-xl p-3 text-xs font-black italic outline-none" />
                            <input placeholder="3:30" value={t.duration} onChange={e => {
                              const next = [...inlineTracks];
                              next[i].duration = e.target.value;
                              setInlineTracks(next);
                            }} className="bg-zinc-800/40 border-none rounded-xl p-3 text-xs font-black italic outline-none text-center" />
                            <button onClick={() => setInlineTracks(inlineTracks.filter((_, idx) => idx !== i))} className="text-zinc-600 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  <button onClick={saveAlbum} className="w-full py-5 bg-white text-black font-black text-xl rounded-2xl hover:scale-[1.02] transition-all shadow-xl">
                    {editingId ? 'Patch Archive' : 'Deploy Collection'}
                  </button>
                </>
              )}

              {activeTab === 'track' && (
                <>
                  <InputGroup label="Broadcast Signal (Track)" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                  <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2 italic opacity-80">Artist</label>
                      <select value={formData.trackArtistId} onChange={e => setFormData({...formData, trackArtistId: e.target.value, trackAlbumId: ''})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 font-black text-sm outline-none italic cursor-pointer appearance-none">
                        <option value="">Choose Creator...</option>
                        {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2 italic opacity-80">Archive Location</label>
                      <select value={formData.trackAlbumId} onChange={e => setFormData({...formData, trackAlbumId: e.target.value})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 font-black text-sm outline-none italic cursor-pointer appearance-none">
                        <option value="single">Isolated Signal (Single)</option>
                        {albums.filter(a => a.artistId === formData.trackArtistId).map(a => <option key={a.id} value={a.id}>{a.title}</option>)}
                      </select>
                    </div>
                  </div>
                  <div className="grid grid-cols-3 gap-6">
                    <InputGroup label="Duration" placeholder="3:30" value={formData.trackDuration} onChange={v => setFormData({...formData, trackDuration: v})} />
                    <InputGroup label="Plays" numeric value={formData.trackPlays} onChange={v => setFormData({...formData, trackPlays: v})} />
                    <InputGroup label="Likes" numeric value={formData.trackLikes} onChange={v => setFormData({...formData, trackLikes: v})} />
                  </div>
                  <button onClick={saveTrack} className="w-full py-5 bg-white text-black font-black text-xl rounded-2xl hover:scale-[1.02] transition-all shadow-xl">
                    {editingId ? 'Patch Stream' : 'Broadcast Capture'}
                  </button>
                </>
              )}
            </div>
          </div>
        )}

        {activeTab !== 'manage' && (
          <div className="space-y-8">
            <div className="bg-zinc-900/20 backdrop-blur-md p-8 rounded-[3rem] border border-zinc-800/50 text-center shadow-3xl">
              <h3 className="text-[10px] font-black text-zinc-600 mb-6 uppercase tracking-[0.2em] italic opacity-80">Visual Identification</h3>
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="w-full aspect-square bg-zinc-800/40 rounded-3xl border-2 border-dashed border-zinc-700 flex flex-col items-center justify-center cursor-pointer hover:border-green-500 transition-all overflow-hidden relative shadow-inner"
              >
                {(activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)) ? (
                  <img src={activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)} className="w-full h-full object-cover" key={activeTab + editingId} />
                ) : (
                  <>
                    <ImageIcon className="w-10 h-10 text-zinc-700 mb-4" />
                    <p className="text-[9px] font-black text-zinc-600 uppercase tracking-widest italic">Signal Cover</p>
                  </>
                )}
                <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity">
                   <Upload className="w-8 h-8 text-white" />
                </div>
              </div>
              <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
            </div>

            {(activeTab === 'artist' || activeTab === 'track') && (
              <div className="bg-gradient-to-br from-green-500/10 to-transparent p-8 rounded-[3rem] border border-green-500/20 shadow-2xl">
                <h4 className="text-xl font-black mb-2 flex items-center gap-3 italic">
                  <Dices className="text-green-400 w-5 h-5" />
                  Randomizer
                </h4>
                <p className="text-[10px] text-zinc-600 font-black mb-6 leading-relaxed italic opacity-80">Pre-fill realistic signal metrics (100k - 10M range) instantly.</p>
                <button onClick={fillRealisticStats} className="w-full py-3 bg-green-500 text-black font-black text-[10px] rounded-xl hover:scale-105 active:scale-95 transition-all shadow-xl shadow-green-500/10 uppercase tracking-widest italic">
                  Generate Logic
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'manage' && (
          <div className="col-span-1 md:col-span-3 space-y-12 animate-in">
             <div className="grid grid-cols-2 gap-4">
               <button onClick={exportDB} className="bg-zinc-800/40 p-5 rounded-2xl border border-zinc-700/50 flex items-center justify-center gap-3 hover:bg-zinc-800 transition-all group">
                 <Download className="w-5 h-5 text-green-400 group-hover:animate-bounce" />
                 <span className="text-sm font-black italic tracking-tighter">Export Archive (.json)</span>
               </button>
               <label className="bg-zinc-800/40 p-5 rounded-2xl border border-zinc-700/50 flex items-center justify-center gap-3 hover:bg-zinc-800 transition-all cursor-pointer group">
                 <FileUp className="w-5 h-5 text-green-400" />
                 <span className="text-sm font-black italic tracking-tighter">Import Archive</span>
                 <input type="file" className="hidden" accept=".json" onChange={importDB} />
               </label>
             </div>
             <ManagementSection title="Artists" items={artists} onDelete={id => setArtists(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('artist', id)} icon={User} />
             <ManagementSection title="Archives" items={albums} onDelete={id => setAlbums(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('album', id)} icon={Disc} />
             <ManagementSection title="Signals" items={tracks} onDelete={id => setTracks(prev => prev.filter(t => t.id !== id))} onEdit={id => handleEdit('track', id)} icon={Music} />
          </div>
        )}
      </div>
    </div>
  );
}

const InputGroup = ({ label, type = 'text', numeric, placeholder, value, onChange }: { label: string, type?: string, numeric?: boolean, placeholder?: string, value: any, onChange: (v: string) => void }) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (numeric) {
      const val = e.target.value.replace(/\D/g, '');
      const num = parseInt(val) || 0;
      onChange(formatNumber(num));
    } else {
      onChange(e.target.value);
    }
  };

  return (
    <div className="space-y-3">
      <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2 italic opacity-80">{label}</label>
      <input 
        type={numeric ? 'text' : type} 
        value={value} 
        onChange={handleChange}
        placeholder={placeholder} 
        className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-4 focus:border-green-400/50 outline-none transition-all text-base font-black tracking-tighter italic"
      />
    </div>
  );
};

const ManagementSection = ({ title, items, onDelete, onEdit, icon: Icon }: { title: string, items: any[], onDelete: (id: string) => void, onEdit: (id: string) => void, icon: any }) => (
  <div className="space-y-6">
    <h3 className="text-3xl font-black flex items-center gap-4 italic px-2 tracking-tighter">
      <Icon className="w-6 h-6 text-zinc-700" />
      {title} <span className="text-base text-zinc-800 font-black italic">({items.length})</span>
    </h3>
    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
      {items.map(item => (
        <div key={item.id} className="bg-zinc-900/30 p-4 rounded-3xl border border-zinc-800/50 flex flex-col gap-4 group hover:bg-zinc-800/60 transition-all relative overflow-hidden shadow-lg">
          <div className="w-full aspect-square bg-zinc-800 rounded-2xl overflow-hidden shadow-inner border border-white/5">
            <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/200/200`} className="w-full h-full object-cover group-hover:scale-105 transition-transform" />
          </div>
          <div className="min-w-0">
            <p className="text-base font-black truncate tracking-tighter italic mb-0.5">{item.name || item.title}</p>
            <p className="text-[9px] text-zinc-600 font-black uppercase tracking-widest truncate italic opacity-80">{item.genre || item.artistName || 'Creator'}</p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => onEdit(item.id)} className="flex-1 py-2 bg-zinc-800 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-white hover:text-black transition-all italic">Edit</button>
            <button onClick={() => onDelete(item.id)} className="p-2 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all">
              <Trash2 className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      ))}
    </div>
  </div>
);

function TrackPage({ id, tracks, albums, artists, toggleLikeTrack, navigateTo }: TrackViewProps) {
  const track = tracks.find(t => t.id === id);
  if (!track) return <div className="p-20 text-center text-3xl font-black italic opacity-20 tracking-widest">SIGNAL LOST</div>;
  const album = albums.find(a => a.id === track.albumId);
  const artist = artists.find(a => a.id === track.artistId);

  return (
    <div className="min-h-full flex flex-col p-10 bg-gradient-to-b from-zinc-800/20 via-black to-black animate-in">
      <div className="flex flex-col lg:flex-row items-center gap-16 mt-12 max-w-6xl">
        <div className="w-72 h-72 lg:w-[420px] lg:h-[420px] shadow-2xl rounded-[3.5rem] overflow-hidden border-8 border-white/5 flex-shrink-0 relative group">
          <img src={track.coverUrl || album?.coverUrl || 'https://picsum.photos/seed/capture/500/500'} className="w-full h-full object-cover" />
        </div>
        <div className="flex flex-col items-center lg:items-start text-center lg:text-left min-w-0 flex-1">
