const InputGroup = ({ label, type = 'text', numeric, placeholder, value, onChange }: { label: string, type?: string, numeric?: boolean, placeholder?: string, value: any, onChange: (v: string) => void }) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (numeric) {
      const val = e.target.value.replace(/\D/g, '');
      const num = parseInt(val) || 0;
      onChange(formatNumber(num));
    } else {
      onChange(e.target.value);
    }
  };

  return (
    <div className="space-y-4">
      <label className="text-[11px] font-bold text-zinc-600 uppercase tracking-widest px-3 opacity-80">{label}</label>
      <input 
        type={numeric ? 'text' : type} 
        value={value} 
        onChange={handleChange}
        placeholder={placeholder} 
        className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-2xl p-5 focus:border-green-400/50 outline-none transition-all text-base font-bold tracking-tight"
      />
    </div>
  );
};

