function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks }: CreatorHubProps) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>('artist');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '', artistCountry: '', artistTrending: false,
    albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '',
    trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: '', trackFit: ''
  });
  const [inlineTracks, setInlineTracks] = useState<{title: string, duration: string, explicit: boolean}[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetForm = () => {
    setFormData({
      artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '', artistCountry: '', artistTrending: false,
      albumTitle: '', albumArtistId: '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '',
      trackTitle: '', trackArtistId: '', trackAlbumId: '', trackDuration: '3:30', trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: '', trackFit: ''
    });
    setInlineTracks([]);
    setEditingId(null);
  };

  const handleEdit = (type: string, id: string) => {
    setEditingId(id);
    setActiveTab(type as any);
    if (type === 'artist') {
      const a = artists.find(i => i.id === id)!;
      setFormData({...formData, artistName: a.name, artistBio: a.bio, artistGenre: a.genre, artistFollowers: formatNumber(a.followers), artistVerified: a.verified, artistImg: a.imageUrl, artistCountry: a.country || '', artistTrending: a.isRisingStar || false});
    } else if (type === 'album') {
      const a = albums.find(i => i.id === id)!;
      setFormData({...formData, albumTitle: a.title, albumArtistId: a.artistId, albumImg: a.coverUrl, albumYear: a.releaseYear, albumGenre: a.genre, albumLabel: a.label || ''});
    } else if (type === 'track') {
      const a = tracks.find(i => i.id === id)!;
      setFormData({...formData, trackTitle: a.title, trackArtistId: a.artistId, trackAlbumId: a.albumId, trackDuration: a.duration, trackPlays: formatNumber(a.plays), trackLikes: formatNumber(a.likes), trackComposer: a.composer || '', trackExplicit: a.isExplicit || false, trackImg: a.coverUrl || '', trackFit: a.featuredArtist || ''});
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const base64 = await fileToBase64(file);
      const field = activeTab === 'artist' ? 'artistImg' : (activeTab === 'album' ? 'albumImg' : 'trackImg');
      setFormData({ ...formData, [field]: base64 });
    }
  };

  const saveArtist = () => {
    if (!formData.artistName) return;
    const followers = parseFormattedNumber(formData.artistFollowers);
    if (editingId) {
      setArtists(prev => prev.map(a => a.id === editingId ? { ...a, name: formData.artistName, bio: formData.artistBio, genre: formData.artistGenre, followers, verified: formData.artistVerified, imageUrl: formData.artistImg || a.imageUrl, country: formData.artistCountry, isRisingStar: formData.artistTrending } : a));
    } else {
      const newArtist: Artist = {
        id: Math.random().toString(36).substr(2, 9),
        name: formData.artistName, bio: formData.artistBio, imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
        genre: formData.artistGenre, followers, verified: formData.artistVerified, country: formData.artistCountry, isRisingStar: formData.artistTrending
      };
      setArtists([...artists, newArtist]);
    }
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId)!;
    const albumId = editingId || Math.random().toString(36).substr(2, 9);

    if (editingId) {
      setAlbums(prev => prev.map(a => a.id === editingId ? { ...a, title: formData.albumTitle, artistId: artist.id, artistName: artist.name, coverUrl: formData.albumImg || a.coverUrl, releaseYear: Number(formData.albumYear), genre: formData.albumGenre, label: formData.albumLabel } : a));
    } else {
      const newAlbum: Album = {
        id: albumId, title: formData.albumTitle, artistId: artist.id, artistName: artist.name,
        coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`, releaseYear: Number(formData.albumYear),
        genre: formData.albumGenre, isLiked: false, label: formData.albumLabel
      };
      setAlbums([...albums, newAlbum]);
    }

    if (inlineTracks.length > 0) {
      const newTracks: Track[] = inlineTracks.map(t => ({
        id: Math.random().toString(36).substr(2, 9),
        title: t.title,
        artistId: artist.id,
        artistName: artist.name,
        albumId: albumId,
        albumTitle: formData.albumTitle,
        duration: t.duration,
        plays: getRandomValue(10000, 1000000),
        likes: getRandomValue(100, 50000),
        isLiked: false,
        isExplicit: t.explicit,
        coverUrl: formData.albumImg || ''
      }));
      setTracks(prev => [...prev, ...newTracks]);
    }

    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId)!;
    const album = albums.find(a => a.id === formData.trackAlbumId);
    const plays = parseFormattedNumber(formData.trackPlays);
    const likes = parseFormattedNumber(formData.trackLikes);

    if (editingId) {
      setTracks(prev => prev.map(t => t.id === editingId ? { ...t, title: formData.trackTitle, artistId: artist.id, artistName: artist.name, albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays, likes, composer: formData.trackComposer, isExplicit: formData.trackExplicit, coverUrl: formData.trackImg || t.coverUrl, featuredArtist: formData.trackFit } : t));
    } else {
      const newTrack: Track = {
        id: Math.random().toString(36).substr(2, 9), title: formData.trackTitle, artistId: artist.id, artistName: artist.name,
        albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays, likes,
        isLiked: false, composer: formData.trackComposer, isExplicit: formData.trackExplicit, coverUrl: formData.trackImg || `https://picsum.photos/seed/${formData.trackTitle}/400/400`, featuredArtist: formData.trackFit
      };
      setTracks([...tracks, newTrack]);
    }
    resetForm();
  };

  const fillRealisticStats = () => {
    if (activeTab === 'artist') {
      setFormData({...formData, artistFollowers: formatNumber(getRandomValue(10000, 1000000))});
    } else if (activeTab === 'track') {
      const plays = getRandomValue(10000, 10000000);
      const likes = Math.floor(plays * (getRandomValue(2, 7) / 100)); 
      setFormData({...formData, trackPlays: formatNumber(plays), trackLikes: formatNumber(likes)});
    }
  };

  const addInlineTrack = () => {
    setInlineTracks([...inlineTracks, {title: '', duration: '3:30', explicit: false}]);
  };

  const exportDB = () => {
    const db = { artists, albums, tracks };
    const blob = new Blob([JSON.stringify(db, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `musaic_vault_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
  };

  const importDB = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        try {
          const db = JSON.parse(ev.target?.result as string);
          if (db.artists) setArtists(db.artists);
          if (db.albums) setAlbums(db.albums);
          if (db.tracks) setTracks(db.tracks);
          alert("Database Synced.");
        } catch (e) { alert("Format Error."); }
      };
      reader.readAsText(file);
    }
  };

  return (
    <div className="p-10 max-w-6xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-16 bg-zinc-900/30 p-12 rounded-[4rem] border border-zinc-800/50 backdrop-blur-2xl shadow-2xl">
        <div>
          <h2 className="text-5xl font-black tracking-tighter leading-none mb-3 italic uppercase">Studio hub</h2>
          <p className="text-base text-zinc-600 font-bold tracking-tight italic">Modify your library protocol.</p>
        </div>
        <div className="flex gap-4 p-2 bg-black rounded-[2.5rem] border border-zinc-800 shadow-xl">
          {['artist', 'album', 'track', 'manage'].map((t) => (
            <button 
              key={t}
              onClick={() => { setActiveTab(t as any); resetForm(); }}
              className={`px-10 py-3 rounded-2xl font-black text-xs transition-all capitalize italic ${activeTab === t ? 'bg-zinc-700 text-white shadow-xl' : 'text-zinc-500 hover:text-white'}`}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-16">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-12">
            <div className="bg-zinc-900/20 backdrop-blur-md p-12 rounded-[4rem] border border-zinc-800/50 space-y-8 shadow-2xl">
              {activeTab === 'artist' && (
                <>
                  <InputGroup label="Identity Name" placeholder="Artist Name" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                  <div className="grid grid-cols-2 gap-8">
                    <InputGroup label="Sonic Spectrum (Genre)" placeholder="Electronic" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                    <InputGroup label="Followers" numeric value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                  </div>
                  <div className="grid grid-cols-2 gap-8">
                    <InputGroup label="Origin (Country)" placeholder="USA" value={formData.artistCountry} onChange={v => setFormData({...formData, artistCountry: v})} />
                    <div className="flex flex-col gap-4 justify-center px-4">
                      <label className="flex items-center gap-4 cursor-pointer group">
                        <input type="checkbox" checked={formData.artistVerified} onChange={e => setFormData({...formData, artistVerified: e.target.checked})} className="w-6 h-6 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0 shadow-lg" />
                        <span className="text-xs font-black uppercase tracking-widest text-zinc-500 group-hover:text-white transition-colors italic">Verified Status</span>
                      </label>
                      <label className="flex items-center gap-4 cursor-pointer group">
                        <input type="checkbox" checked={formData.artistTrending} onChange={e => setFormData({...formData, artistTrending: e.target.checked})} className="w-6 h-6 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0 shadow-lg" />
                        <span className="text-xs font-black uppercase tracking-widest text-zinc-500 group-hover:text-white transition-colors italic">Rising Star Status</span>
                      </label>
                    </div>
                  </div>
                  <div className="space-y-5">
                    <label className="text-xs font-black text-zinc-600 uppercase tracking-[0.2em] px-4 opacity-80 italic">Manifesto (Bio)</label>
                    <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} rows={4} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[2.5rem] p-8 focus:border-green-400/50 outline-none transition-all resize-none text-lg font-black tracking-tighter italic" />
                  </div>
                  <button onClick={saveArtist} className="w-full py-7 bg-white text-black font-black text-2xl rounded-[2.5rem] hover:scale-[1.03] active:scale-[0.97] transition-all shadow-2xl">
                    {editingId ? 'Update Entity' : 'Broadcast Artist'}
                  </button>
                </>
              )}

              {activeTab === 'album' && (
                <>
                  <InputGroup label="Collection Title" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-5">
                      <label className="text-xs font-black text-zinc-600 uppercase tracking-[0.2em] px-4 opacity-80 italic">Assign Creator</label>
                      <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[2.5rem] p-6 font-black text-lg outline-none cursor-pointer appearance-none italic shadow-lg">
                        <option value="">Choose Identity...</option>
                        {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                      </select>
                    </div>
                    <InputGroup label="Distribution Genre" value={formData.albumGenre} onChange={v => setFormData({...formData, albumGenre: v})} />
                  </div>

                  {!editingId && (
                    <div className="space-y-8 pt-8 border-t border-zinc-800/50">
                      <div className="flex items-center justify-between px-4">
                        <label className="text-xs font-black text-zinc-600 uppercase tracking-[0.2em] opacity-80 italic">Signal Log (Tracks)</label>
                        <button onClick={addInlineTrack} className="text-xs font-black text-green-400 flex items-center gap-3 hover:scale-110 transition-all uppercase italic">
                          <Plus className="w-5 h-5" /> Add Log
                        </button>
                      </div>
                      <div className="space-y-4">
                        {inlineTracks.map((t, i) => (
                          <div key={i} className="grid grid-cols-[1fr_120px_60px] gap-6 items-center">
                            <input placeholder="Track Name" value={t.title} onChange={e => {
                              const next = [...inlineTracks];
                              next[i].title = e.target.value;
                              setInlineTracks(next);
                            }} className="bg-zinc-800/40 border-none rounded-[1.5rem] p-5 text-base font-black italic outline-none shadow-md" />
                            <input placeholder="3:30" value={t.duration} onChange={e => {
                              const next = [...inlineTracks];
                              next[i].duration = e.target.value;
                              setInlineTracks(next);
                            }} className="bg-zinc-800/40 border-none rounded-[1.5rem] p-5 text-base font-black italic outline-none text-center shadow-md" />
                            <button onClick={() => setInlineTracks(inlineTracks.filter((_, idx) => idx !== i))} className="text-zinc-600 hover:text-red-500 transition-colors"><Trash2 className="w-6 h-6" /></button>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  <button onClick={saveAlbum} className="w-full py-7 bg-white text-black font-black text-2xl rounded-[2.5rem] hover:scale-[1.03] transition-all shadow-2xl">
                    {editingId ? 'Modify Record' : 'Deploy Album'}
                  </button>
                </>
              )}

              {activeTab === 'track' && (
                <>
                  <InputGroup label="Track Designation" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-5">
                      <label className="text-xs font-black text-zinc-600 uppercase tracking-[0.2em] px-4 opacity-80 italic">Artist Identity</label>
                      <select value={formData.trackArtistId} onChange={e => setFormData({...formData, trackArtistId: e.target.value, trackAlbumId: ''})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[2.5rem] p-6 font-black text-lg outline-none italic cursor-pointer appearance-none shadow-lg">
                        <option value="">Choose Artist...</option>
                        {artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-5">
                      <label className="text-xs font-black text-zinc-600 uppercase tracking-[0.2em] px-4 opacity-80 italic">Linked Album</label>
                      <select value={formData.trackAlbumId} onChange={e => setFormData({...formData, trackAlbumId: e.target.value})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[2.5rem] p-6 font-black text-lg outline-none italic cursor-pointer appearance-none shadow-lg">
                        <option value="single">Isolated (Single)</option>
                        {albums.filter(a => a.artistId === formData.trackArtistId).map(a => <option key={a.id} value={a.id}>{a.title}</option>)}
                      </select>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-8">
                    <InputGroup label="Composer Code" placeholder="System" value={formData.trackComposer} onChange={v => setFormData({...formData, trackComposer: v})} />
                    <InputGroup label="Featured Identity (Fit)" placeholder="Artist Name" value={formData.trackFit} onChange={v => setFormData({...formData, trackFit: v})} />
                  </div>
                  <div className="grid grid-cols-3 gap-8">
                    <InputGroup label="Duration" placeholder="3:30" value={formData.trackDuration} onChange={v => setFormData({...formData, trackDuration: v})} />
                    <InputGroup label="Plays" numeric value={formData.trackPlays} onChange={v => setFormData({...formData, trackPlays: v})} />
                    <InputGroup label="Likes" numeric value={formData.trackLikes} onChange={v => setFormData({...formData, trackLikes: v})} />
                  </div>
                  <button onClick={saveTrack} className="w-full py-7 bg-white text-black font-black text-2xl rounded-[2.5rem] hover:scale-[1.03] transition-all shadow-2xl">
                    {editingId ? 'Modify Signal' : 'Broadcast Track'}
                  </button>
                </>
              )}
            </div>
          </div>
        )}

        {activeTab !== 'manage' && (
          <div className="space-y-12">
            <div className="bg-zinc-900/20 backdrop-blur-md p-10 rounded-[4rem] border border-zinc-800/50 text-center shadow-3xl">
              <h3 className="text-xs font-black text-zinc-600 mb-8 uppercase tracking-[0.3em] opacity-80 italic">Artwork Matrix</h3>
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="w-full aspect-square bg-zinc-800/40 rounded-[3rem] border-4 border-dashed border-zinc-700 flex flex-col items-center justify-center cursor-pointer hover:border-green-500 transition-all overflow-hidden relative shadow-inner"
              >
                {(activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)) ? (
                  <img src={activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)} className="w-full h-full object-cover" key={activeTab + editingId} />
                ) : (
                  <>
                    <ImageIcon className="w-16 h-16 text-zinc-700 mb-6" />
                    <p className="text-[11px] font-black text-zinc-600 uppercase tracking-widest italic">Signal Visual</p>
                  </>
                )}
                <div className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity">
                   <Upload className="w-12 h-12 text-white" />
                </div>
              </div>
              <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
            </div>

            {(activeTab === 'artist' || activeTab === 'track') && (
              <div className="bg-gradient-to-br from-green-500/10 to-transparent p-12 rounded-[4rem] border border-green-500/20 shadow-2xl">
                <h4 className="text-3xl font-black mb-4 flex items-center gap-5 italic tracking-tighter uppercase">
                  <Dices className="text-green-400 w-8 h-8" />
                  Randomizer
                </h4>
                <p className="text-sm text-zinc-600 font-bold mb-10 leading-relaxed opacity-80 italic">Fill realistic metrics instantly (10k - 10M range) for testing protocols.</p>
                <button onClick={fillRealisticStats} className="w-full py-5 bg-green-500 text-black font-black text-xs rounded-[1.5rem] hover:scale-105 active:scale-95 transition-all shadow-xl shadow-green-500/10 uppercase tracking-[0.2em] italic">
                  Generate Logic
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'manage' && (
          <div className="col-span-1 md:col-span-3 space-y-20 animate-in">
             <div className="grid grid-cols-2 gap-8">
               <button onClick={exportDB} className="bg-zinc-800/40 p-8 rounded-[3rem] border border-zinc-700/50 flex items-center justify-center gap-5 hover:bg-zinc-800 transition-all group shadow-2xl">
                 <Download className="w-8 h-8 text-green-400 group-hover:animate-bounce" />
                 <span className="text-xl font-black italic tracking-tighter uppercase">Export Vault (.json)</span>
               </button>
               <label className="bg-zinc-800/40 p-8 rounded-[3rem] border border-zinc-700/50 flex items-center justify-center gap-5 hover:bg-zinc-800 transition-all cursor-pointer group shadow-2xl">
                 <FileUp className="w-8 h-8 text-green-400" />
                 <span className="text-xl font-black italic tracking-tighter uppercase">Import Vault</span>
                 <input type="file" className="hidden" accept=".json" onChange={importDB} />
               </label>
             </div>
             <ManagementSection title="Artists" items={artists} onDelete={id => setArtists(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('artist', id)} icon={User} />
             <ManagementSection title="Albums" items={albums} onDelete={id => setAlbums(prev => prev.filter(a => a.id !== id))} onEdit={id => handleEdit('album', id)} icon={Disc} />
             <ManagementSection title="Tracks" items={tracks} onDelete={id => setTracks(prev => prev.filter(t => t.id !== id))} onEdit={id => handleEdit('track', id)} icon={Music} />
          </div>
        )}
      </div>
    </div>
  );
}

const InputGroup = ({ label, type = 'text', numeric, placeholder, value, onChange }: { label: string, type?: string, numeric?: boolean, placeholder?: string, value: any, onChange: (v: string) => void }) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (numeric) {
      const val = e.target.value.replace(/\D/g, '');
      const num = parseInt(val) || 0;
      onChange(formatNumber(num));
    } else {
      onChange(e.target.value);
    }
  };

  return (
    <div className="space-y-5">
      <label className="text-xs font-black text-zinc-600 uppercase tracking-[0.2em] px-4 opacity-80 italic">{label}</label>
      <input 
        type={numeric ? 'text' : type} 
        value={value} 
        onChange={handleChange}
        placeholder={placeholder} 
        className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[2.5rem] p-6 focus:border-green-400/50 outline-none transition-all text-xl font-black tracking-tighter italic shadow-lg"
      />
    </div>
  );
};

const ManagementSection = ({ title, items, onDelete, onEdit, icon: Icon }: { title: string, items: any[], onDelete: (id: string) => void, onEdit: (id: string) => void, icon: any }) => (
  <div className="space-y-10">
    <h3 className="text-5xl font-black flex items-center gap-6 tracking-tighter italic uppercase">
      <Icon className="w-12 h-12 text-zinc-700" />
      {title} <span className="text-xl text-zinc-800 font-black italic">({items.length})</span>
    </h3>
    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-8">
      {items.map(item => (
        <div key={item.id} className="bg-zinc-900/30 p-6 rounded-[3.5rem] border border-zinc-800/50 flex flex-col gap-6 group hover:bg-zinc-800/60 transition-all relative overflow-hidden shadow-2xl">
          <div className="w-full aspect-square bg-zinc-800 rounded-[2.5rem] overflow-hidden shadow-inner border border-white/5">
            <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/300/300`} className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
          </div>
          <div className="min-w-0">
            <p className="text-2xl font-black truncate tracking-tighter italic mb-1 uppercase">{item.name || item.title}</p>
            <p className="text-[10px] text-zinc-600 font-black uppercase tracking-widest truncate italic opacity-80">{item.genre || item.artistName || 'Creator'}</p>
          </div>
          <div className="flex gap-3">
            <button onClick={() => onEdit(item.id)} className="flex-1 py-3 bg-zinc-800 rounded-2xl text-[11px] font-black uppercase tracking-[0.2em] hover:bg-white hover:text-black transition-all italic">Edit</button>
            <button onClick={() => onDelete(item.id)} className="p-3 bg-red-500/10 text-red-500 rounded-2xl hover:bg-red-500 hover:text-white transition-all shadow-xl">
              <Trash2 className="w-5 h-5" />
            </button>
          </div>
        </div>
      ))}
    </div>
  </div>
);

function TrackPage({ id, tracks, albums, artists, toggleLikeTrack, navigateTo }: TrackViewProps) {
  const track = tracks.find(t => t.id === id);
  if (!track) return <div className="p-20 text-center text-5xl font-black italic opacity-20 uppercase tracking-tighter">Track lost</div>;
  const album = albums.find(a => a.id === track.albumId);
  const artist = artists.find(a => a.id === track.artistId);

  return (
    <div className="min-h-full flex flex-col p-12 bg-gradient-to-b from-zinc-800/20 via-black to-black animate-in">
      <div className="flex flex-col lg:flex-row items-center gap-24 mt-12 max-w-7xl mx-auto w-full">
        <div className="w-80 h-80 lg:w-[500px] lg:h-[500px] shadow-[0_80px_150px_-30px_rgba(0,0,0,0.9)] rounded-[4.5rem] overflow-hidden border-8 border-white/5 flex-shrink-0 relative group">
          <img src={track.coverUrl || album?.coverUrl || 'https://picsum.photos/seed/track/600/600'} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-1000" />
        </div>
        <div className="flex flex-col items-center lg:items-start text-center lg:text-left min-w-0 flex-1">
          <div className="bg-zinc-800/40 px-6 py-2.5 rounded-full border border-white/5 shadow-2xl mb-10">
