      {items.map(item => (
        <div key={item.id} className="bg-zinc-900/30 p-6 rounded-[3.5rem] border border-zinc-800/50 flex flex-col gap-6 group hover:bg-zinc-800/60 transition-all relative overflow-hidden shadow-2xl">
          <div className="w-full aspect-square bg-zinc-800 rounded-[2.5rem] overflow-hidden shadow-inner border border-white/5">
            <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/300/300`} className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
          </div>
          <div className="min-w-0">
            <p className="text-xl font-black truncate tracking-tighter italic mb-1 uppercase">{item.name || item.title}</p>
            <p className="text-[10px] text-zinc-600 font-black uppercase tracking-widest truncate italic opacity-80">{item.genre || item.artistName || 'Creator'}</p>
          </div>
          <div className="flex gap-3">
            <button onClick={() => onEdit(item.id)} className="flex-1 py-2.5 bg-zinc-800 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-white hover:text-black transition-all italic">Edit</button>
            <button onClick={() => onDelete(item.id)} className="p-2.5 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all shadow-xl">
              <Trash2 className="w-4 h-4" />
