                          <button onClick={() => setInlineTracks(inlineTracks.filter((_, idx) => idx !== i))}><Trash2 className="w-3.5 h-3.5 text-zinc-600 hover:text-red-500" /></button>
                        </div>
                      ))}
                    </div>
                  </div>
