              <input type="file" ref={fileInputRef} onChange={async (e) => { const f = e.target.files?.[0]; if (f) { const b = await fileToBase64(f); setFormData({...formData, [activeTab === 'artist' ? 'artistImg' : (activeTab === 'album' ? 'albumImg' : 'trackImg')]: b}); } }} className="hidden" accept="image/*" />
            </div>
            {(activeTab === 'artist' || activeTab === 'track') && (
