                <button onClick={fillRealisticStats} className="w-full py-4 bg-green-500 text-black font-black text-[10px] rounded-2xl hover:scale-105 transition-all shadow-xl shadow-green-500/10 uppercase italic">Run Protocol</button>
              </div>
            )}
          </div>
        )}
        {activeTab === 'manage' && (
          <div className="col-span-1 md:col-span-3 space-y-16 animate-in">
             <div className="grid grid-cols-2 gap-6"><button onClick={() => { const db = { artists, albums, tracks }; const b = new Blob([JSON.stringify(db)], { type: 'application/json' }); const u = URL.createObjectURL(b); const a = document.createElement('a'); a.href = u; a.download = 'musaic_vault.json'; a.click(); }} className="bg-zinc-800/40 p-6 rounded-2xl border border-zinc-700/50 flex items-center justify-center gap-4 hover:bg-zinc-800 transition-all uppercase italic font-bold"><Download className="w-6 h-6 text-green-400" /> Export</button><label className="bg-zinc-800/40 p-6 rounded-2xl border border-zinc-700/50 flex items-center justify-center gap-4 hover:bg-zinc-800 transition-all cursor-pointer uppercase italic font-bold"><FileUp className="w-6 h-6 text-green-400" /> Import<input type="file" className="hidden" accept=".json" onChange={e => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onload = ev => { const db = JSON.parse(ev.target?.result as string); if (db.artists) setArtists(db.artists); if (db.albums) setAlbums(db.albums); if (db.tracks) setTracks(db.tracks); }; r.readAsText(f); } }} /></label></div>
             <ManagementSection title="Artists" items={artists} onDelete={id => setArtists(prev => prev.filter(a => a.id !== id))} onEdit={(id) => { const a = artists.find(i => i.id === id)!; setEditingId(id); setActiveTab('artist'); setFormData({...formData, artistName: a.name, artistBio: a.bio, artistGenre: a.genre, artistFollowers: formatNumber(a.followers), artistVerified: a.verified, artistImg: a.imageUrl, artistCountry: a.country || '', artistTrending: a.isRisingStar || false}); }} icon={User} />
             <ManagementSection title="Albums" items={albums} onDelete={id => setAlbums(prev => prev.filter(a => a.id !== id))} onEdit={(id) => { const a = albums.find(i => i.id === id)!; setEditingId(id); setActiveTab('album'); setFormData({...formData, albumTitle: a.title, albumArtistId: a.artistId, albumImg: a.coverUrl, albumYear: a.releaseYear, albumGenre: a.genre, albumLabel: a.label || '', albumProducer: a.producer || ''}); }} icon={Disc} />
