function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks, initialTab = 'artist', targetId }: any) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>(initialTab);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '', artistCountry: '', artistTrending: false,
    albumTitle: '', albumArtistId: targetId || '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '', albumProducer: '',
    trackTitle: '', trackArtistId: targetId || '', trackAlbumId: '', trackDuration: getRandomDuration(), trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: '', trackFit: ''
  });
  const [inlineTracks, setInlineTracks] = useState<{title: string, duration: string, explicit: boolean, plays: string}[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const saveArtist = () => {
    if (!formData.artistName) return;
    const followers = parseFormattedNumber(formData.artistFollowers);
    const newArtist: Artist = {
      id: editingId || Math.random().toString(36).substr(2, 9),
      name: formData.artistName, bio: formData.artistBio, imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
      genre: formData.artistGenre, followers, verified: formData.artistVerified, country: formData.artistCountry, isRisingStar: formData.artistTrending
    };
    if (editingId) setArtists(prev => prev.map(a => a.id === editingId ? newArtist : a));
    else setArtists([...artists, newArtist]);
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId)!;
    const albumId = editingId || Math.random().toString(36).substr(2, 9);
    const newAlbum: Album = {
      id: albumId, title: formData.albumTitle, artistId: artist.id, artistName: artist.name,
      coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`, releaseYear: Number(formData.albumYear),
      genre: formData.albumGenre, isLiked: false, label: formData.albumLabel, producer: formData.albumProducer
    };
    if (editingId) setAlbums(prev => prev.map(a => a.id === editingId ? newAlbum : a));
    else setAlbums([...albums, newAlbum]);

    if (inlineTracks.length > 0) {
      const newTracks: Track[] = inlineTracks.map(t => ({
        id: Math.random().toString(36).substr(2, 9),
        title: t.title, artistId: artist.id, artistName: artist.name, albumId: albumId, albumTitle: formData.albumTitle,
        duration: t.duration || getRandomDuration(), plays: parseFormattedNumber(t.plays), likes: Math.floor(parseFormattedNumber(t.plays) * 0.05),
        isLiked: false, isExplicit: t.explicit, coverUrl: formData.albumImg || ''
      }));
      setTracks(prev => [...prev, ...newTracks]);
    }
    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId)!;
    const album = albums.find(a => a.id === formData.trackAlbumId);
    // Added missing isLiked property to correctly match Track type requirements
    const newTrack: Track = {
      id: editingId || Math.random().toString(36).substr(2, 9), title: formData.trackTitle, artistId: artist.id, artistName: artist.name,
      albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration, plays: parseFormattedNumber(formData.trackPlays), 
      likes: parseFormattedNumber(formData.trackLikes), isLiked: editingId ? (tracks.find(t => t.id === editingId)?.isLiked || false) : false, 
      composer: formData.trackComposer, isExplicit: formData.trackExplicit, 
      coverUrl: formData.trackImg || album?.coverUrl || `https://picsum.photos/seed/${formData.trackTitle}/400/400`, featuredArtist: formData.trackFit
    };
    if (editingId) setTracks(prev => prev.map(t => t.id === editingId ? newTrack : t));
    else setTracks([...tracks, newTrack]);
    resetForm();
  };

  const resetForm = () => {
    setFormData({ ...formData, artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', albumTitle: '', trackTitle: '', trackPlays: '0', trackLikes: '0', trackDuration: getRandomDuration() });
    setInlineTracks([]);
    setEditingId(null);
  };

  const fillRealisticStats = () => {
    if (activeTab === 'artist') setFormData({...formData, artistFollowers: formatNumber(getRandomValue(10000, 1000000))});
    else if (activeTab === 'track') setFormData({...formData, trackPlays: formatNumber(getRandomValue(10000, 10000000)), trackLikes: formatNumber(getRandomValue(100, 500000))});
  };

  return (
    <div className="p-8 max-w-6xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-12 bg-zinc-900/30 p-8 rounded-[3.5rem] border border-white/5 backdrop-blur-2xl shadow-2xl">
        <h2 className="text-3xl font-black uppercase italic tracking-tighter">Studio</h2>
        <div className="flex gap-2 p-1.5 bg-black rounded-2xl border border-zinc-800">
          {['artist', 'album', 'track', 'manage'].map(t => (
            <button key={t} onClick={() => { setActiveTab(t as any); resetForm(); }} className={`px-6 py-2 rounded-xl font-bold text-[10px] uppercase transition-all ${activeTab === t ? 'bg-zinc-700 text-white shadow-xl' : 'text-zinc-500 hover:text-white'}`}>{t}</button>
          ))}
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-8 bg-zinc-900/20 p-10 rounded-[3rem] border border-white/5 shadow-2xl">
            {activeTab === 'artist' && (
              <div className="space-y-6">
                <InputGroup label="Name" placeholder="Artist Name" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                <div className="grid grid-cols-2 gap-6">
                  <InputGroup label="Genre" placeholder="Electronic" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                  <InputGroup label="Followers" numeric value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                </div>
                <InputGroup label="Country" placeholder="USA" value={formData.artistCountry} onChange={v => setFormData({...formData, artistCountry: v})} />
                <div className="flex gap-6 px-3">
                  <label className="flex items-center gap-3 cursor-pointer"><input type="checkbox" checked={formData.artistVerified} onChange={e => setFormData({...formData, artistVerified: e.target.checked})} className="w-5 h-5 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0" /><span className="text-[10px] font-black uppercase tracking-widest text-zinc-500 italic">Verified</span></label>
                  <label className="flex items-center gap-3 cursor-pointer"><input type="checkbox" checked={formData.artistTrending} onChange={e => setFormData({...formData, artistTrending: e.target.checked})} className="w-5 h-5 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0" /><span className="text-[10px] font-black uppercase tracking-widest text-zinc-500 italic">Rising Star</span></label>
                </div>
                <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} placeholder="Manifesto..." rows={3} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[1.5rem] p-5 text-base font-medium tracking-tight italic outline-none focus:border-green-400/40" />
                <button onClick={saveArtist} className="w-full py-5 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] transition-all">{editingId ? 'Save' : 'Publish'}</button>
              </div>
            )}
            {activeTab === 'album' && (
              <div className="space-y-6">
                <InputGroup label="Title" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                <div className="grid grid-cols-2 gap-6">
                  <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[1.5rem] p-4 font-bold text-sm outline-none appearance-none italic shadow-lg"><option value="">Select Artist...</option>{artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
                  <InputGroup label="Producer" placeholder="Producer Name" value={formData.albumProducer} onChange={v => setFormData({...formData, albumProducer: v})} />
                </div>
                <div className="grid grid-cols-2 gap-6">
                  <InputGroup label="Genre" value={formData.albumGenre} onChange={v => setFormData({...formData, albumGenre: v})} />
                  <InputGroup label="Year" type="number" value={formData.albumYear} onChange={v => setFormData({...formData, albumYear: v})} />
                </div>
                {!editingId && (
                  <div className="pt-6 border-t border-white/5">
                    <div className="flex items-center justify-between mb-4"><span className="text-[9px] font-black uppercase text-zinc-600">Track Log</span><button onClick={() => setInlineTracks([...inlineTracks, {title: '', duration: getRandomDuration(), explicit: false, plays: formatNumber(getRandomValue(10000, 100000))}])} className="text-[9px] font-black text-green-400 uppercase">+ Add</button></div>
                    <div className="space-y-2">
                      {inlineTracks.map((t, i) => (
                        <div key={i} className="grid grid-cols-[1fr_80px_100px_30px] gap-3">
                          <input placeholder="Title" value={t.title} onChange={e => { const n = [...inlineTracks]; n[i].title = e.target.value; setInlineTracks(n); }} className="bg-zinc-800/40 border-none rounded-xl p-3 text-xs font-bold italic" />
                          <input placeholder="3:30" value={t.duration} onChange={e => { const n = [...inlineTracks]; n[i].duration = e.target.value; setInlineTracks(n); }} className="bg-zinc-800/40 border-none rounded-xl p-3 text-xs font-bold text-center" />
                          <div className="relative group">
                            <input placeholder="Plays" value={t.plays} onChange={e => { const n = [...inlineTracks]; n[i].plays = e.target.value; setInlineTracks(n); }} className="w-full bg-zinc-800/40 border-none rounded-xl p-3 text-xs font-bold text-right tabular-nums" />
                            <Dices onClick={() => { const n = [...inlineTracks]; n[i].plays = formatNumber(getRandomValue(10000, 1000000)); setInlineTracks(n); }} className="absolute left-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-zinc-600 hover:text-green-500 cursor-pointer" />
                          </div>
                          <button onClick={() => setInlineTracks(inlineTracks.filter((_, idx) => idx !== i))}><Trash2 className="w-3.5 h-3.5 text-zinc-600 hover:text-red-500" /></button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                <button onClick={saveAlbum} className="w-full py-5 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] transition-all">Save Collection</button>
              </div>
            )}
            {activeTab === 'track' && (
              <div className="space-y-6">
                <InputGroup label="Title" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                <div className="grid grid-cols-2 gap-6">
                  <select value={formData.trackArtistId} onChange={e => setFormData({...formData, trackArtistId: e.target.value, trackAlbumId: ''})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[1.5rem] p-4 font-bold text-sm outline-none appearance-none italic"><option value="">Select Artist...</option>{artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
                  <select value={formData.trackAlbumId} onChange={e => setFormData({...formData, trackAlbumId: e.target.value})} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[1.5rem] p-4 font-bold text-sm outline-none appearance-none italic"><option value="single">Isolated Stream</option>{albums.filter(a => a.artistId === formData.trackArtistId).map(a => <option key={a.id} value={a.id}>{a.title}</option>)}</select>
                </div>
                <div className="grid grid-cols-2 gap-6">
                  <InputGroup label="Composer" value={formData.trackComposer} onChange={v => setFormData({...formData, trackComposer: v})} />
                  <InputGroup label="Feature" placeholder="ft. Artist" value={formData.trackFit} onChange={v => setFormData({...formData, trackFit: v})} />
                </div>
                <div className="grid grid-cols-3 gap-6">
                  <InputGroup label="Duration" value={formData.trackDuration} onChange={v => setFormData({...formData, trackDuration: v})} />
                  <InputGroup label="Plays" numeric value={formData.trackPlays} onChange={v => setFormData({...formData, trackPlays: v})} />
                  <InputGroup label="Likes" numeric value={formData.trackLikes} onChange={v => setFormData({...formData, trackLikes: v})} />
                </div>
                <button onClick={saveTrack} className="w-full py-5 bg-white text-black font-black text-lg rounded-2xl hover:scale-[1.02] transition-all">Broadcast</button>
              </div>
            )}
          </div>
        )}
        {activeTab !== 'manage' && (
          <div className="space-y-10">
            <div className="bg-zinc-900/20 p-10 rounded-[3.5rem] border border-white/5 text-center shadow-3xl">
              <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-square bg-zinc-800/40 rounded-[2rem] border-4 border-dashed border-zinc-700 flex flex-col items-center justify-center cursor-pointer hover:border-green-500 transition-all overflow-hidden relative">
                {(activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)) ? <img src={activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)} className="w-full h-full object-cover" alt="" /> : <><ImageIcon className="w-12 h-12 text-zinc-700 mb-4" /><p className="text-[10px] font-black text-zinc-600 uppercase italic">Artwork</p></>}
                <div className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity"><Upload className="w-10 h-10 text-white" /></div>
              </div>
              <input type="file" ref={fileInputRef} onChange={async (e) => { const f = e.target.files?.[0]; if (f) { const b = await fileToBase64(f); setFormData({...formData, [activeTab === 'artist' ? 'artistImg' : (activeTab === 'album' ? 'albumImg' : 'trackImg')]: b}); } }} className="hidden" accept="image/*" />
            </div>
            {(activeTab === 'artist' || activeTab === 'track') && (
              <div className="bg-gradient-to-br from-green-500/10 to-transparent p-10 rounded-[3.5rem] border border-green-500/20 shadow-2xl">
                <h4 className="text-2xl font-black mb-4 flex items-center gap-5 italic uppercase"><Dices className="text-green-400 w-7 h-7" /> Random</h4>
                <p className="text-xs text-zinc-600 font-bold mb-8 leading-relaxed italic">Populate metrics instantly.</p>
                <button onClick={fillRealisticStats} className="w-full py-4 bg-green-500 text-black font-black text-[10px] rounded-2xl hover:scale-105 transition-all shadow-xl shadow-green-500/10 uppercase italic">Run Protocol</button>
              </div>
            )}
          </div>
        )}
        {activeTab === 'manage' && (
          <div className="col-span-1 md:col-span-3 space-y-16 animate-in">
             <div className="grid grid-cols-2 gap-6"><button onClick={() => { const db = { artists, albums, tracks }; const b = new Blob([JSON.stringify(db)], { type: 'application/json' }); const u = URL.createObjectURL(b); const a = document.createElement('a'); a.href = u; a.download = 'musaic_vault.json'; a.click(); }} className="bg-zinc-800/40 p-6 rounded-2xl border border-zinc-700/50 flex items-center justify-center gap-4 hover:bg-zinc-800 transition-all uppercase italic font-bold"><Download className="w-6 h-6 text-green-400" /> Export</button><label className="bg-zinc-800/40 p-6 rounded-2xl border border-zinc-700/50 flex items-center justify-center gap-4 hover:bg-zinc-800 transition-all cursor-pointer uppercase italic font-bold"><FileUp className="w-6 h-6 text-green-400" /> Import<input type="file" className="hidden" accept=".json" onChange={e => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onload = ev => { const db = JSON.parse(ev.target?.result as string); if (db.artists) setArtists(db.artists); if (db.albums) setAlbums(db.albums); if (db.tracks) setTracks(db.tracks); }; r.readAsText(f); } }} /></label></div>
             <ManagementSection title="Artists" items={artists} onDelete={id => setArtists(prev => prev.filter(a => a.id !== id))} onEdit={(id) => { const a = artists.find(i => i.id === id)!; setEditingId(id); setActiveTab('artist'); setFormData({...formData, artistName: a.name, artistBio: a.bio, artistGenre: a.genre, artistFollowers: formatNumber(a.followers), artistVerified: a.verified, artistImg: a.imageUrl, artistCountry: a.country || '', artistTrending: a.isRisingStar || false}); }} icon={User} />
             <ManagementSection title="Albums" items={albums} onDelete={id => setAlbums(prev => prev.filter(a => a.id !== id))} onEdit={(id) => { const a = albums.find(i => i.id === id)!; setEditingId(id); setActiveTab('album'); setFormData({...formData, albumTitle: a.title, albumArtistId: a.artistId, albumImg: a.coverUrl, albumYear: a.releaseYear, albumGenre: a.genre, albumLabel: a.label || '', albumProducer: a.producer || ''}); }} icon={Disc} />
             <ManagementSection title="Tracks" items={tracks} onDelete={id => setTracks(prev => prev.filter(t => t.id !== id))} onEdit={(id) => { const a = tracks.find(i => i.id === id)!; setEditingId(id); setActiveTab('track'); setFormData({...formData, trackTitle: a.title, trackArtistId: a.artistId, trackAlbumId: a.albumId, trackDuration: a.duration, trackPlays: formatNumber(a.plays), trackLikes: formatNumber(a.likes), trackComposer: a.composer || '', trackExplicit: a.isExplicit || false, trackImg: a.coverUrl || '', trackFit: a.featuredArtist || ''}); }} icon={Music} />
          </div>
        )}
      </div>
    </div>
  );
}

const InputGroup = ({ label, type = 'text', numeric, placeholder, value, onChange }: any) => (
  <div className="space-y-3">
    <label className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.2em] px-4 italic">{label}</label>
    <input type={numeric ? 'text' : type} value={value} onChange={e => { if (numeric) { const v = e.target.value.replace(/\D/g, ''); onChange(formatNumber(parseInt(v) || 0)); } else onChange(e.target.value); }} placeholder={placeholder} className="w-full bg-zinc-800/30 border-2 border-zinc-700/50 rounded-[1.5rem] p-4 text-lg font-black tracking-tighter italic outline-none focus:border-green-400/40 transition-all" />
  </div>
);

const ManagementSection = ({ title, items, onDelete, onEdit, icon: Icon }: any) => (
  <div className="space-y-8">
    <h3 className="text-4xl font-black flex items-center gap-5 tracking-tighter italic uppercase"><Icon className="w-10 h-10 text-zinc-700" />{title} <span className="text-xl text-zinc-800">({items.length})</span></h3>
    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-6">
      {items.map((item: any) => (
        <div key={item.id} className="bg-zinc-900/30 p-5 rounded-[3rem] border border-white/5 flex flex-col gap-4 group hover:bg-zinc-800/60 transition-all relative overflow-hidden shadow-2xl">
          <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/200/200`} className="w-full aspect-square bg-zinc-800 rounded-[2rem] object-cover group-hover:scale-110 transition-transform" alt="" />
          <div className="min-w-0"><p className="text-xl font-black truncate tracking-tighter italic uppercase">{item.name || item.title}</p><p className="text-[10px] text-zinc-600 font-bold uppercase truncate italic">{item.genre || item.artistName || 'Creator'}</p></div>
          <div className="flex gap-2"><button onClick={() => onEdit(item.id)} className="flex-1 py-2.5 bg-zinc-800 rounded-xl text-[10px] font-black uppercase hover:bg-white hover:text-black transition-all italic">Edit</button><button onClick={() => onDelete(item.id)} className="p-2.5 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"><Trash2 className="w-4 h-4" /></button></div>
        </div>
      ))}
    </div>
  </div>
);

function TrackPage({ id, tracks, albums, artists, navigateTo }: any) {
  const track = tracks.find((t: any) => t.id === id);
  if (!track) return <div className="p-20 text-center text-5xl font-black opacity-20 uppercase">Track lost</div>;
  const album = albums.find((a: any) => a.id === track.albumId);
  const artist = artists.find((a: any) => a.id === track.artistId);
  return (
    <div className="min-h-full flex flex-col p-12 bg-gradient-to-b from-zinc-800/20 via-black to-black animate-in">
      <div className="flex flex-col lg:flex-row items-center gap-20 mt-12 max-w-7xl mx-auto w-full">
        <div className="w-80 h-80 lg:w-[450px] lg:h-[450px] shadow-[0_80px_150px_-30px_rgba(0,0,0,0.9)] rounded-[4.5rem] overflow-hidden border-8 border-white/5 relative group"><img src={track.coverUrl || album?.coverUrl || 'https://picsum.photos/seed/track/600/600'} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-1000" alt="" /></div>
        <div className="flex flex-col items-center lg:items-start text-center lg:text-left min-w-0 flex-1">
          <div className="bg-zinc-800/40 px-5 py-2 rounded-full border border-white/5 shadow-2xl mb-8"><span className="text-[10px] font-black uppercase tracking-[0.5em] text-green-400 italic">Broadcast Details</span></div>
          <h1 className="text-5xl lg:text-[6vw] font-black mb-10 tracking-tighter leading-[0.85] drop-shadow-3xl truncate w-full italic uppercase">{track.title}</h1>
          <div onClick={() => navigateTo('artist', { id: track.artistId })} className="flex items-center gap-6 text-3xl font-black hover:text-green-400 cursor-pointer tracking-tighter mb-14 italic group uppercase"><div className="w-14 h-14 bg-zinc-800 rounded-full overflow-hidden border-2 border-white/10 group-hover:scale-110 transition-all shadow-2xl flex-shrink-0"><img src={artist?.imageUrl} className="w-full h-full object-cover" alt="" /></div>{track.artistName}</div>
          <div className="grid grid-cols-3 gap-14 text-zinc-500 font-black uppercase text-[11px] opacity-80 italic">
             <div className="flex flex-col gap-3"><span className="opacity-40">Streams</span><span className="text-white text-4xl tabular-nums tracking-tighter">{formatNumber(track.plays)}</span></div>
             <div className="flex flex-col gap-3"><span className="opacity-40">Composer</span><span className="text-white text-4xl truncate">{track.composer || 'Anon'}</span></div>
             <div className="flex flex-col gap-3"><span className="opacity-40">Album</span><span className="text-white text-4xl hover:underline cursor-pointer truncate" onClick={() => navigateTo('album', { id: track.albumId })}>{track.albumTitle}</span></div>
          </div>
        </div>
      </div>
    </div>
  );
}

function AlbumView({ id, albums, tracks, toggleLikeTrack, toggleLikeAlbum, navigateTo }: any) {
  const album = albums.find((a: any) => a.id === id);
  if (!album) return <div className="p-20 text-center text-4xl font-black opacity-20 uppercase">Album lost</div>;
  const albumTracks = tracks.filter((t: any) => t.albumId === id);
  return (
    <div className="bg-gradient-to-b from-zinc-800/20 via-black to-black min-h-full">
      <div className="p-10 pt-20 flex flex-col md:flex-row items-end gap-16 max-w-7xl mx-auto w-full">
        <div className="w-72 h-72 md:w-[420px] md:h-[420px] shadow-[0_100px_180px_-40px_rgba(0,0,0,1)] rounded-[4.5rem] overflow-hidden border-8 border-white/5 group cursor-pointer"><img src={album.coverUrl} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-1000" alt="" /></div>
        <div className="flex flex-col min-w-0 flex-1">
          <span className="text-[10px] font-black uppercase tracking-[0.5em] mb-8 text-zinc-500 italic opacity-80 uppercase">Collection</span>
          <h1 className="text-6xl md:text-[7vw] font-black mb-10 tracking-tighter leading-[0.85] drop-shadow-3xl break-words italic uppercase">{album.title}</h1>
          <div className="flex flex-wrap items-center gap-6 text-2xl font-black italic tracking-tighter text-zinc-200 uppercase"><span className="hover:text-green-400 transition-colors cursor-pointer underline underline-offset-[10px] decoration-white/20" onClick={() => navigateTo('artist', { id: album.artistId })}>{album.artistName}</span><span className="text-zinc-700">•</span><span className="tabular-nums">{album.releaseYear}</span><span className="text-zinc-700">•</span><span className="text-zinc-500 uppercase tracking-widest text-[10px] font-black">{albumTracks.length} recordings</span></div>
          {album.producer && <p className="mt-6 text-[9px] font-black text-zinc-600 uppercase tracking-widest">Produced by: {album.producer}</p>}
        </div>
      </div>
      <div className="max-w-7xl mx-auto p-12 mt-12"><div className="flex items-center gap-12 mb-20"><button className="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-2xl shadow-green-500/20"><Play className="text-black fill-black ml-1 w-9 h-9" /></button><Heart onClick={() => toggleLikeAlbum(album.id)} className={`w-10 h-10 cursor-pointer transition-all hover:scale-125 ${album.isLiked ? 'text-green-500 fill-green-500' : 'text-zinc-700 hover:text-white'}`} /><MoreHorizontal className="w-10 h-10 text-zinc-700" /></div><div className="grid grid-cols-[40px_1fr_140px_80px] gap-10 px-8 py-6 text-zinc-600 text-[10px] font-black uppercase border-b border-zinc-900/50 mb-10 italic opacity-60"><span>#</span><span>Track</span><span className="text-right">Streams</span><span className="flex justify-center"><Clock className="w-6 h-6" /></span></div><div className="space-y-1.5">{albumTracks.map((track: any, i: number) => <TrackRow key={track.id} track={track} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: track.id })} size="lg" />)}</div></div>
    </div>
  );
}

function SearchView({ query, artists, albums, tracks, navigateTo, toggleLikeTrack }: any) {
  const filteredArtists = artists.filter((a: any) => a.name.toLowerCase().includes(query.toLowerCase()));
  const filteredAlbums = albums.filter((a: any) => a.title.toLowerCase().includes(query.toLowerCase()));
  const filteredTracks = tracks.filter((t: any) => t.title.toLowerCase().includes(query.toLowerCase()));
  if (!query) {
    return <div className="p-12"><h3 className="text-5xl font-black mb-16 px-4 tracking-tighter uppercase italic">Categories</h3><div className="grid grid-cols-2 md:grid-cols-4 gap-10">{['Electronic', 'Acoustic', 'Hyper', 'Ambient', 'Techno', 'Deep', 'Neon', 'Industrial'].map(g => <div key={g} className="bg-zinc-800/40 aspect-video rounded-[3.5rem] p-10 relative overflow-hidden group cursor-pointer border border-white/5 hover:bg-zinc-700/40 transition-all shadow-2xl"><span className="text-4xl lg:text-5xl font-black relative z-10 tracking-tighter italic uppercase">{g}</span><img src={`https://picsum.photos/seed/${g}/600/400`} className="absolute bottom-0 right-0 w-44 h-44 rotate-[25deg] translate-x-12 translate-y-12 group-hover:scale-125 transition-transform opacity-30 mix-blend-screen grayscale group-hover:grayscale-0" alt="" /></div>)}</div></div>;
  }
  return (
    <div className="p-12">
      {filteredArtists.length > 0 && <div className="mb-24"><h3 className="text-4xl font-black mb-10 tracking-tighter italic uppercase">Artists</h3><div className="flex gap-10 overflow-x-auto pb-10">{filteredArtists.map((a: any) => <div key={a.id} onClick={() => navigateTo('artist', { id: a.id })} className="flex-shrink-0 w-64 bg-zinc-900/30 p-10 rounded-[3.5rem] hover:bg-zinc-800/50 transition-all cursor-pointer shadow-2xl"><img src={a.imageUrl} className="w-full aspect-square object-cover rounded-full mb-8 shadow-2xl" alt="" /><p className="font-black truncate text-2xl tracking-tighter text-center italic uppercase">{a.name}</p></div>)}</div></div>}
      {filteredTracks.length > 0 && <div className="mb-24"><h3 className="text-4xl font-black mb-10 tracking-tighter italic uppercase">Tracks</h3><div className="space-y-3 max-w-6xl">{filteredTracks.map((t: any, i: number) => <TrackRow key={t.id} track={t} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: t.id })} size="lg" />)}</div></div>}
    </div>
  );
}

