              </div>
            )}
          </div>
          <div className="bg-zinc-800/80 px-4 py-1.5 rounded-full text-[9px] font-black border border-white/5 flex items-center gap-2 uppercase tracking-widest italic">
            <Zap className="w-3 h-3 text-green-400 fill-green-400 animate-pulse" />
            Studio
          </div>
        </header>

        <div className="flex-1 overflow-y-auto pb-40 scroll-smooth custom-scrollbar">
          {nav.view === 'home' && <HomeView artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} />}
          {nav.view === 'artist' && <ArtistView id={nav.params?.id || ''} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'artist_tracks' && <ArtistTracksView id={nav.params?.id || ''} artists={artists} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'album' && <AlbumView id={nav.params?.id || ''} albums={albums} tracks={tracks} toggleLikeTrack={toggleLikeTrack} toggleLikeAlbum={toggleLikeAlbum} navigateTo={navigateTo} />}
          {nav.view === 'track' && <TrackPage id={nav.params?.id || ''} tracks={tracks} albums={albums} artists={artists} toggleLikeTrack={toggleLikeTrack} navigateTo={navigateTo} />}
          {nav.view === 'creator' && <CreatorHub artists={artists} setArtists={setArtists} albums={albums} setAlbums={setAlbums} tracks={tracks} setTracks={setTracks} initialTab={nav.params?.id ? (artists.find(a => a.id === nav.params?.id) ? 'album' : 'artist') : 'artist'} targetId={nav.params?.id} />}
          {nav.view === 'library' && <LibraryView albums={albums} artists={artists} tracks={tracks} navigateTo={navigateTo} />}
          {nav.view === 'search' && <SearchView query={searchQuery} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
        </div>

        {/* Player Bar */}
        <div className="absolute bottom-0 left-0 right-0 h-24 bg-black/90 backdrop-blur-2xl border-t border-zinc-900 flex items-center justify-between px-8 z-[60]">
           <div className="flex items-center gap-4 w-1/3 min-w-0">
            <div className="w-14 h-14 bg-zinc-800 rounded-xl overflow-hidden shadow-xl flex-shrink-0 group border border-white/5">
              <img src="https://picsum.photos/seed/placeholder/300/300" alt="" className="w-full h-full object-cover transition-transform group-hover:scale-110" />
            </div>
            <div className="min-w-0">
              <p className="text-sm font-bold truncate tracking-tight uppercase italic">Protocol Idle</p>
              <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest truncate opacity-60 italic leading-none">Global Link</p>
            </div>
