  const artistAlbums = albums.filter(a => a.artistId === id);
  const artistTracks = tracks.filter(t => t.artistId === id).slice(0, 10);

  return (
    <div className="relative animate-in bg-black min-h-full">
      {/* Dynamic Header */}
      <div className="h-[400px] bg-black flex flex-col justify-end p-12 relative overflow-hidden">
