             <div className="flex items-baseline gap-2.5">
               <span className="text-5xl font-black text-white tracking-tighter tabular-nums italic">{formatNumber(artist.followers)}</span>
               <span className="text-sm font-black uppercase tracking-[0.2em] text-zinc-500 italic opacity-80">Listeners</span>
             </div>
             {artist.country && <div className="flex items-center gap-2 text-zinc-600 font-bold text-xs uppercase italic mt-1"><Globe className="w-3.5 h-3.5" />{artist.country}</div>}
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-12 py-10 bg-black">
        {/* Actions Bar */}
        <div className="flex items-center gap-10 mb-16">
          <button className="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-[0_0_40px_rgba(34,197,94,0.2)]"><Play className="text-black fill-black ml-1 w-8 h-8" /></button>
          <button className="border-2 border-zinc-800 px-10 py-3.5 rounded-2xl font-black text-lg hover:border-white transition-all uppercase tracking-widest italic active:bg-zinc-900">Follow</button>
          <MoreHorizontal className="text-zinc-700 hover:text-white cursor-pointer w-8 h-8 transition-colors" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-20">
          {/* Tracks Section */}
          <div className="lg:col-span-2">
            <div className="flex items-center justify-between mb-8">
              <h3 onClick={() => navigateTo('artist_tracks', { id: artist.id })} className="text-3xl font-black tracking-tighter opacity-70 italic uppercase cursor-pointer hover:opacity-100 transition-all flex items-center gap-4">
                Top Signals <ArrowRight className="w-6 h-6" />
              </h3>
              <PlusCircle onClick={() => navigateTo('creator', { id: artist.id })} className="w-6 h-6 text-zinc-800 hover:text-green-500 cursor-pointer transition-colors" />
            </div>
            <div className="space-y-1.5">
              {artistTracks.map((track, i) => <TrackRow key={track.id} track={track} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: track.id })} size="lg" />)}
              {artistTracks.length === 0 && <p className="text-zinc-800 font-black italic p-12 text-center text-4xl uppercase opacity-20">No signals</p>}
            </div>
          </div>

          {/* About Section */}
          <div className="space-y-12">
            <h3 className="text-3xl font-black tracking-tighter opacity-70 italic uppercase">Log</h3>
            <div className="p-1">
               <p className="text-2xl font-bold leading-relaxed mb-8 opacity-90 italic text-zinc-300">{artist.bio || "No data recorded."}</p>
               <div className="flex flex-wrap gap-3"><div className="px-6 py-2 bg-zinc-900 rounded-full font-black text-[10px] uppercase tracking-widest border border-white/5 italic">#{artist.genre}</div></div>
            </div>
          </div>
        </div>

        {/* Albums Section */}
        <div className="mt-24">
          <div className="flex items-center justify-between mb-10">
            <h3 className="text-3xl font-black tracking-tighter opacity-70 italic uppercase">Archives</h3>
            <PlusCircle onClick={() => navigateTo('creator', { id: artist.id })} className="w-6 h-6 text-zinc-800 hover:text-green-500 cursor-pointer transition-colors" />
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-8">
            {artistAlbums.map(album => (
              <div key={album.id} onClick={() => navigateTo('album', { id: album.id })} className="group cursor-pointer">
                <div className="relative mb-4">
                  <img src={album.coverUrl} className="w-full aspect-square object-cover rounded-[2.5rem] shadow-2xl group-hover:scale-105 transition-all duration-700 border-2 border-transparent group-hover:border-zinc-800" alt="" />
                  <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity rounded-[2.5rem]"><Play className="w-12 h-12 text-white fill-white" /></div>
                </div>
                <p className="font-black truncate text-lg tracking-tighter mb-1 italic uppercase">{album.title}</p>
                <p className="text-zinc-500 text-[10px] font-black uppercase tracking-widest italic">{album.releaseYear}</p>
              </div>
            ))}
            {artistAlbums.length === 0 && <div className="col-span-full py-20 bg-zinc-900/10 rounded-[4rem] flex flex-col items-center justify-center border-2 border-dashed border-zinc-900 opacity-20"><Disc className="w-12 h-12 mb-4" /><p className="font-black italic uppercase tracking-widest">Empty Archives</p></div>}
          </div>
        </div>
      </div>
    </div>
  );
}

function ArtistTracksView({ id, artists, tracks, navigateTo, toggleLikeTrack }: any) {
  const artist = artists.find((a: any) => a.id === id);
  if (!artist) return <div className="p-20 text-center text-4xl font-black opacity-20 italic">LOST SIGNAL</div>;
  const artistTracks = tracks.filter((t: any) => t.artistId === id);

  return (
    <div className="p-12 animate-in bg-black min-h-full">
      <div className="flex items-center gap-8 mb-16 max-w-6xl mx-auto">
        <img src={artist.imageUrl} className="w-24 h-24 rounded-[3rem] object-cover border-4 border-white/5 shadow-2xl" alt="" />
        <div>
          <h2 className="text-6xl font-black italic uppercase tracking-tighter leading-none">{artist.name}</h2>
          <p className="text-zinc-600 text-lg font-bold uppercase tracking-widest italic mt-2 opacity-60">Complete Log ({artistTracks.length})</p>
        </div>
      </div>
      <div className="space-y-1 max-w-6xl mx-auto">
        {artistTracks.map((t: any, i: number) => <TrackRow key={t.id} track={t} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: t.id })} size="lg" />)}
      </div>
    </div>
  );
}

