               <span className="text-4xl font-black text-white tracking-tighter tabular-nums italic">{formatNumber(artist.followers)}</span>
               <span className="text-sm font-black uppercase tracking-[0.2em] text-zinc-400 italic opacity-80">Listeners</span>
             </div>
             {artist.country && <div className="flex items-center gap-2 text-zinc-500 font-bold text-xs uppercase italic mt-1.5"><Globe className="w-3.5 h-3.5" />{artist.country}</div>}
