      <div className="space-y-1 max-w-6xl">
        {artistTracks.map((t: any, i: number) => <TrackRow key={t.id} track={t} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: t.id })} size="lg" />)}
