import React, { useState, useEffect, useRef } from 'react';
import { 
  Home, 
  Search, 
  Library, 
  PlusCircle, 
  Heart, 
  Play, 
  MoreHorizontal, 
  Mic2, 
  Disc, 
  Music,
  ChevronLeft,
  ChevronRight,
  User,
  Sparkles,
  CheckCircle2,
  ListMusic,
  Clock,
  Trash2,
  Upload,
  Image as ImageIcon,
  Check,
  Zap,
  Dices,
  Settings2,
  Download,
  FileUp,
  Plus,
  Globe,
  TrendingUp,
  CircleCheck,
  ArrowRight
} from 'lucide-react';
import { Artist, Album, Track, ViewType, NavigationState, HomeViewProps, ArtistViewProps } from './types';
// Added GoogleGenAI import to leverage Gemini for creative features
import { GoogleGenAI } from "@google/genai";

// --- Helpers ---

const getRandomDuration = () => {
  const min = Math.floor(Math.random() * 4) + 1;
  const sec = Math.floor(Math.random() * 60).toString().padStart(2, '0');
  return `${min}:${sec}`;
};

const getRandomValue = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const formatNumber = (num: number) => num.toLocaleString('de-DE');

const parseFormattedNumber = (str: string) => {
  if (typeof str !== 'string') return 0;
  return parseInt(str.replace(/\./g, '')) || 0;
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// --- Sub-components ---

const TrackRow: React.FC<{ track: Track, index: number, toggleLike: (id: string) => void, onPlay: () => void, hideStats?: boolean, size?: 'sm' | 'lg' }> = ({ track, index, toggleLike, onPlay, hideStats, size = 'sm' }) => {
  const isLarge = size === 'lg';
  return (
    <div 
      onClick={onPlay}
      className={`group grid ${isLarge ? 'grid-cols-[40px_1fr_140px_100px]' : 'grid-cols-[30px_1fr_110px_70px]'} gap-4 items-center ${isLarge ? 'px-4 py-3.5' : 'px-3 py-2'} hover:bg-zinc-800/60 rounded-2xl transition-all cursor-pointer border border-transparent hover:border-white/5 active:bg-zinc-900`}
    >
      <div className={`${isLarge ? 'text-base' : 'text-sm'} text-zinc-500 group-hover:hidden font-bold`}>{index + 1}</div>
      <Play className={`hidden group-hover:block ${isLarge ? 'w-5 h-5' : 'w-4 h-4'} fill-white text-white`} />

      <div className="flex items-center gap-4 min-w-0">
        <div className={`${isLarge ? 'w-14 h-14' : 'w-10 h-10'} bg-zinc-800 rounded-xl overflow-hidden flex-shrink-0 shadow-lg border border-white/5`}>
           <img src={track.coverUrl || 'https://picsum.photos/seed/track/200/200'} className="w-full h-full object-cover" alt="" />
        </div>
        <div className="flex flex-col min-w-0">
          <div className="flex items-center gap-2">
            <span className={`${isLarge ? 'text-lg' : 'text-base'} font-bold truncate tracking-tight ${track.isLiked ? 'text-green-400' : 'text-zinc-100'} group-hover:text-white`}>{track.title}</span>
            {track.isExplicit && <span className="bg-zinc-700 text-[9px] font-bold px-1 rounded flex-shrink-0">E</span>}
          </div>
          <div className="flex items-center gap-2">
            <span className={`${isLarge ? 'text-sm' : 'text-xs'} text-zinc-400 font-semibold truncate group-hover:text-zinc-300`}>{track.artistName}</span>
            {track.featuredArtist && <span className="text-zinc-500 text-[10px] font-medium truncate italic">ft. {track.featuredArtist}</span>}
          </div>
        </div>
      </div>

      <div className={`${isLarge ? 'text-sm' : 'text-[11px]'} text-zinc-500 text-right tabular-nums font-bold`}>
        {!hideStats ? formatNumber(track.plays) : ''}
      </div>

      <div className="flex items-center justify-end gap-5">
        <Heart 
          onClick={(e) => { e.stopPropagation(); toggleLike(track.id); }}
          className={`w-4 h-4 transition-all hover:scale-125 ${track.isLiked ? 'text-green-500 fill-green-500' : 'opacity-0 group-hover:opacity-100 text-zinc-600 hover:text-white'}`} 
        />
        <span className="text-zinc-500 text-xs font-bold tabular-nums">{track.duration}</span>
      </div>
    </div>
  );
};

// --- Main App ---

export default function App() {
  const [nav, setNav] = useState<NavigationState>({ view: 'home' });
  const [artists, setArtists] = useState<Artist[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [history, setHistory] = useState<NavigationState[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [sidebarWidth, setSidebarWidth] = useState(240);
  const isResizing = useRef(false);

  useEffect(() => {
    const savedData = localStorage.getItem('musaic_master_db');
    if (savedData) {
      try {
        const { artists: a, albums: al, tracks: t } = JSON.parse(savedData);
        if (a) setArtists(a);
        if (al) setAlbums(al);
        if (t) setTracks(t);
      } catch (e) { console.error(e); }
    }

    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizing.current) return;
      setSidebarWidth(Math.max(200, Math.min(400, e.clientX)));
    };
    const handleMouseUp = () => { isResizing.current = false; document.body.style.cursor = 'default'; };
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  useEffect(() => {
    localStorage.setItem('musaic_master_db', JSON.stringify({ artists, albums, tracks }));
  }, [artists, albums, tracks]);

  const navigateTo = (view: ViewType, params?: { id?: string }) => {
    setHistory(prev => [...prev, nav]);
    setNav({ view, params });
  };

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setNav(prev);
    }
  };

  const toggleLikeTrack = (id: string) => {
    setTracks(prev => prev.map(t => t.id === id ? { ...t, isLiked: !t.isLiked, likes: t.isLiked ? t.likes - 1 : t.likes + 1 } : t));
  };

  const toggleLikeAlbum = (id: string) => {
    setAlbums(prev => prev.map(a => a.id === id ? { ...a, isLiked: !a.isLiked } : a));
  };

  const SidebarItem = ({ icon: Icon, label, active, onClick }: { icon: any, label: string, active: boolean, onClick: () => void }) => (
    <button onClick={onClick} className={`w-full flex items-center gap-4 px-4 py-3 rounded-2xl transition-all group ${active ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-500 hover:text-white hover:bg-zinc-900/50'}`}>
      <Icon className={`w-5 h-5 ${active ? 'text-green-400' : 'group-hover:text-green-400'}`} />
      <span className="font-bold text-sm tracking-tight uppercase">{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-black text-zinc-100 select-none overflow-hidden font-['Inter']">
      <aside style={{ width: `${sidebarWidth}px` }} className="bg-black p-4 flex flex-col gap-3 border-r border-zinc-900 z-50 relative">
        <div className="p-2 mb-4 cursor-pointer group" onClick={() => navigateTo('home')}>
          <h1 className="text-2xl font-black flex items-center gap-3 tracking-tighter uppercase italic group-hover:scale-105 transition-transform">
            <Sparkles className="text-green-400 fill-green-400 w-7 h-7 group-hover:rotate-12 transition-transform" />
            MUSAIC
          </h1>
        </div>
        <div className="space-y-1">
          <SidebarItem icon={Home} label="Home" active={nav.view === 'home'} onClick={() => navigateTo('home')} />
          <SidebarItem icon={Search} label="Search" active={nav.view === 'search'} onClick={() => navigateTo('search')} />
          <SidebarItem icon={Library} label="Library" active={nav.view === 'library'} onClick={() => navigateTo('library')} />
        </div>
        <div className="mt-8 space-y-1">
          <h3 className="px-4 text-[9px] font-black text-zinc-600 uppercase tracking-[0.2em] mb-2">Mastering</h3>
          <SidebarItem icon={Settings2} label="Editor Hub" active={nav.view === 'creator'} onClick={() => navigateTo('creator')} />
        </div>
        <div className="mt-auto p-5 bg-zinc-900/40 rounded-3xl border border-zinc-800/50 backdrop-blur-xl">
          <p className="text-[9px] text-zinc-500 font-bold uppercase tracking-widest mb-3 opacity-70 italic">Cloud Core</p>
          <div className="space-y-1 text-xs text-zinc-400 font-bold">
            <div className="flex justify-between"><span>Artists</span> <span className="text-white">{artists.length}</span></div>
            <div className="flex justify-between"><span>Albums</span> <span className="text-white">{albums.length}</span></div>
            <div className="flex justify-between"><span>Tracks</span> <span className="text-white">{tracks.length}</span></div>
          </div>
        </div>
        <div onMouseDown={() => { isResizing.current = true; document.body.style.cursor = 'col-resize'; }} className="absolute top-0 right-0 w-1 h-full cursor-col-resize hover:bg-green-500/20"></div>
      </aside>

      <main className="flex-1 flex flex-col bg-black overflow-hidden relative">
        <header className="h-16 flex items-center justify-between px-8 sticky top-0 z-40 bg-transparent">
          <div className="flex items-center gap-4">
            <button onClick={goBack} className="p-2 bg-black/40 rounded-full hover:bg-black transition-all border border-white/5"><ChevronLeft className="w-5 h-5" /></button>
            <button className="p-2 bg-black/10 rounded-full opacity-20 cursor-not-allowed"><ChevronRight className="w-5 h-5" /></button>
            {nav.view === 'search' && (
              <div className="relative ml-4">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600" />
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search..." className="bg-zinc-800/40 hover:bg-zinc-800 border-none rounded-full py-1.5 pl-10 pr-6 w-64 text-sm font-medium focus:ring-4 focus:ring-green-500/5 transition-all outline-none" />
              </div>
            )}
          </div>
          <div className="bg-zinc-800/80 px-4 py-1.5 rounded-full text-[9px] font-black border border-white/5 flex items-center gap-2 uppercase tracking-widest italic">
            <Zap className="w-3 h-3 text-green-400 fill-green-400 animate-pulse" />
            Studio
          </div>
        </header>

        <div className="flex-1 overflow-y-auto pb-40 scroll-smooth custom-scrollbar">
          {nav.view === 'home' && <HomeView artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} />}
          {nav.view === 'artist' && <ArtistView id={nav.params?.id || ''} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'artist_tracks' && <ArtistTracksView id={nav.params?.id || ''} artists={artists} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'album' && <AlbumView id={nav.params?.id || ''} albums={albums} tracks={tracks} toggleLikeTrack={toggleLikeTrack} toggleLikeAlbum={toggleLikeAlbum} navigateTo={navigateTo} />}
          {nav.view === 'track' && <TrackPage id={nav.params?.id || ''} tracks={tracks} albums={albums} artists={artists} toggleLikeTrack={toggleLikeTrack} navigateTo={navigateTo} />}
          {nav.view === 'creator' && <CreatorHub artists={artists} setArtists={setArtists} albums={albums} setAlbums={setAlbums} tracks={tracks} setTracks={setTracks} initialTab={nav.params?.id ? (artists.find(a => a.id === nav.params?.id) ? 'album' : 'artist') : 'artist'} targetId={nav.params?.id} />}
          {nav.view === 'library' && <LibraryView albums={albums} artists={artists} tracks={tracks} navigateTo={navigateTo} />}
          {nav.view === 'search' && <SearchView query={searchQuery} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
        </div>

        {/* Player Bar */}
        <div className="absolute bottom-0 left-0 right-0 h-24 bg-black/90 backdrop-blur-2xl border-t border-zinc-900 flex items-center justify-between px-8 z-[60]">
           <div className="flex items-center gap-4 w-1/3 min-w-0">
            <div className="w-14 h-14 bg-zinc-800 rounded-xl overflow-hidden shadow-xl flex-shrink-0 group border border-white/5">
              <img src="https://picsum.photos/seed/placeholder/300/300" alt="" className="w-full h-full object-cover transition-transform group-hover:scale-110" />
            </div>
            <div className="min-w-0">
              <p className="text-sm font-bold truncate tracking-tight uppercase italic">Protocol Idle</p>
              <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest truncate opacity-60 italic leading-none">Global Link</p>
            </div>
          </div>
          <div className="flex flex-col items-center gap-2 w-1/3">
            <div className="flex items-center gap-8">
              <button className="text-zinc-600 hover:text-white transition-all"><Disc className="w-5 h-5" /></button>
              <button className="w-10 h-10 bg-white rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-xl"><Play className="w-6 h-6 text-black fill-black ml-1" /></button>
              <button className="text-zinc-600 hover:text-white transition-all"><MoreHorizontal className="w-5 h-5" /></button>
            </div>
            <div className="w-full max-w-sm flex items-center gap-4">
              <span className="text-[10px] font-bold text-zinc-700 tabular-nums">0:00</span>
              <div className="flex-1 h-1 bg-zinc-800 rounded-full overflow-hidden group cursor-pointer"><div className="w-0 h-full bg-zinc-400 group-hover:bg-green-400 transition-colors"></div></div>
              <span className="text-[10px] font-bold text-zinc-700 tabular-nums">3:30</span>
            </div>
          </div>
          <div className="flex items-center justify-end gap-5 w-1/3 text-zinc-600">
             <Mic2 className="w-4 h-4 hover:text-white cursor-pointer" />
             <ListMusic className="w-4 h-4 hover:text-white cursor-pointer" />
             <div className="flex items-center gap-3">
               <Music className="w-4 h-4" />
               <div className="w-20 h-1 bg-zinc-800 rounded-full overflow-hidden"><div className="w-3/4 h-full bg-zinc-500"></div></div>
             </div>
          </div>
        </div>
      </main>
    </div>
  );
}

// --- Content Views ---

function HomeView({ artists, albums, tracks, navigateTo }: HomeViewProps) {
  return (
    <div className="p-8 animate-in bg-black">
      <h2 className="text-5xl font-black mb-10 tracking-tighter uppercase italic">Pulse Feed</h2>
      {albums.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 mb-14">
          {albums.slice(0, 6).map(album => (
            <div key={album.id} onClick={() => navigateTo('album', { id: album.id })} className="group flex items-center gap-5 bg-zinc-900/40 hover:bg-zinc-800/60 transition-all rounded-2xl overflow-hidden cursor-pointer border border-white/5">
              <div className="w-20 h-20 shadow-xl flex-shrink-0"><img src={album.coverUrl} className="w-full h-full object-cover" alt="" /></div>
              <p className="font-bold text-lg flex-1 truncate pr-4 tracking-tight uppercase italic">{album.title}</p>
              <div className="mr-5 w-10 h-10 bg-green-500 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0 shadow-lg"><Play className="text-black fill-black ml-1 w-6 h-6" /></div>
            </div>
          ))}
        </div>
      )}
      {tracks.length > 0 && (
        <div className="mb-14">
          <h3 className="text-3xl font-black mb-8 px-1 tracking-tighter uppercase italic">Signals</h3>
          <div className="space-y-2 max-w-5xl">
            {tracks.slice(0, 6).map((track, i) => <TrackRow key={track.id} track={track} index={i} toggleLike={() => {}} onPlay={() => navigateTo('track', { id: track.id })} size="lg" />)}
          </div>
        </div>
      )}
    </div>
  );
}

function ArtistView({ id, artists, albums, tracks, navigateTo, toggleLikeTrack }: ArtistViewProps) {
  const artist = artists.find(a => a.id === id);
  if (!artist) return <div className="p-20 text-center text-4xl font-black opacity-20 italic">ENTITY LOST</div>;
  const artistAlbums = albums.filter(a => a.artistId === id);
  const artistTracks = tracks.filter(t => t.artistId === id).slice(0, 10);

  return (
    <div className="relative animate-in bg-black min-h-full">
      {/* Dynamic Header */}
      <div className="h-[400px] bg-black flex flex-col justify-end p-12 relative overflow-hidden">
        <img src={artist.imageUrl} className="absolute inset-0 w-full h-full object-cover opacity-60 transition-opacity" alt="" />
        <div className="absolute inset-0 bg-gradient-to-t from-black via-black/30 to-transparent"></div>
        <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col items-start gap-4">
          <div className="flex items-center gap-4">
            <h1 className="text-6xl md:text-8xl font-black tracking-tighter leading-none italic uppercase">{artist.name}</h1>
            {artist.verified && <CircleCheck className="w-8 h-8 text-green-500 fill-black translate-y-1 shadow-[0_0_20px_rgba(34,197,94,0.4)]" />}
          </div>
          <div className="flex flex-col items-start gap-1">
             <div className="flex items-baseline gap-2.5">
               <span className="text-5xl font-black text-white tracking-tighter tabular-nums italic">{formatNumber(artist.followers)}</span>
               <span className="text-sm font-black uppercase tracking-[0.2em] text-zinc-500 italic opacity-80">Listeners</span>
             </div>
             {artist.country && <div className="flex items-center gap-2 text-zinc-600 font-bold text-xs uppercase italic mt-1"><Globe className="w-3.5 h-3.5" />{artist.country}</div>}
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-12 py-10 bg-black">
        {/* Actions Bar */}
