          {['all', 'artists', 'albums', 'tracks'].map(t => (
            <button key={t} onClick={() => setActiveTab(t as any)} className={`px-8 py-2.5 rounded-xl font-black text-xs uppercase transition-all italic ${activeTab === t ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-600 hover:text-white'}`}>{t}</button>
