            <div className="w-24 h-24 bg-zinc-800 rounded-full flex items-center justify-center group-hover:scale-110 transition-transform shadow-xl"><User className="w-12 h-12 text-green-500" /></div>
            <p className="text-3xl font-black uppercase italic tracking-tighter">Artists</p>
