          </div>
          <div onClick={() => setActiveTab('albums')} className="bg-zinc-900/30 p-12 rounded-[4rem] flex flex-col items-center justify-center gap-8 cursor-pointer border border-white/5 hover:bg-zinc-800/50 transition-all group shadow-2xl">
            <div className="w-24 h-24 bg-zinc-800 rounded-[2.5rem] flex items-center justify-center group-hover:scale-110 transition-transform shadow-xl"><Disc className="w-12 h-12 text-green-500" /></div>
            <p className="text-3xl font-black uppercase italic tracking-tighter">Albums</p>
            <p className="text-[11px] text-zinc-600 font-bold uppercase tracking-[0.3em] italic opacity-60">{albums.length} Archives</p>
          </div>
          <div onClick={() => setActiveTab('tracks')} className="bg-zinc-900/30 p-12 rounded-[4rem] flex flex-col items-center justify-center gap-8 cursor-pointer border border-white/5 hover:bg-zinc-800/50 transition-all group shadow-2xl">
            <div className="w-24 h-24 bg-zinc-800 rounded-3xl flex items-center justify-center group-hover:scale-110 transition-transform shadow-xl"><Music className="w-12 h-12 text-green-500" /></div>
