function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks, initialTab = 'artist', targetId }: any) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>(initialTab);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '', artistCountry: '', artistTrending: false,
    albumTitle: '', albumArtistId: targetId || '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '', albumProducer: '',
    trackTitle: '', trackArtistId: targetId || '', trackAlbumId: '', trackDuration: getRandomDuration(), trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: '', trackFit: ''
  });

  // Fix: Added missing fillRealisticStats function to populate metrics for artists and tracks
  const fillRealisticStats = () => {
    if (activeTab === 'artist') {
      const followers = getRandomValue(10000, 50000000);
      setFormData((prev: any) => ({ ...prev, artistFollowers: formatNumber(followers) }));
    } else if (activeTab === 'track') {
      const plays = getRandomValue(50000, 100000000);
      const likes = Math.floor(plays * (getRandomValue(1, 15) / 100));
      setFormData((prev: any) => ({ ...prev, trackPlays: formatNumber(plays), trackLikes: formatNumber(likes) }));
    }
  };

  // Added AI bio generation using Gemini API to enhance the creator experience
  const [isGeneratingBio, setIsGeneratingBio] = useState(false);
  const generateAIBio = async () => {
    if (!formData.artistName) return;
    setIsGeneratingBio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create a professional and futuristic music bio for an artist named "${formData.artistName}". Genre: ${formData.artistGenre || 'Contemporary'}. Keep it under 40 words, focus on a high-tech/cyberpunk aesthetic for the 'MUSAIC' brand.`,
      });
      if (response.text) {
        setFormData((prev: any) => ({ ...prev, artistBio: response.text.trim() }));
      }
    } catch (error) {
      console.error("AI Bio Generation failed:", error);
    } finally {
      setIsGeneratingBio(false);
    }
  };

  const [inlineTracks, setInlineTracks] = useState<{title: string, duration: string, explicit: boolean, plays: string}[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const saveArtist = () => {
    if (!formData.artistName) return;
    const followers = parseFormattedNumber(formData.artistFollowers);
    const id = editingId || Math.random().toString(36).substr(2, 9);
    const newArtist: Artist = {
      id,
      name: formData.artistName, bio: formData.artistBio, imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
      genre: formData.artistGenre, followers, verified: formData.artistVerified, country: formData.artistCountry, isRisingStar: formData.artistTrending
    };
    if (editingId) setArtists((prev: Artist[]) => prev.map(a => a.id === editingId ? newArtist : a));
    else setArtists([...artists, newArtist]);
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId);
    const albumId = editingId || Math.random().toString(36).substr(2, 9);
    const newAlbum: Album = {
      id: albumId, title: formData.albumTitle, artistId: formData.albumArtistId, artistName: artist?.name || 'Unknown',
      coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`, releaseYear: Number(formData.albumYear),
      genre: formData.albumGenre, isLiked: false, label: formData.albumLabel, producer: formData.albumProducer
    };
    if (editingId) setAlbums((prev: Album[]) => prev.map(a => a.id === editingId ? newAlbum : a));
    else setAlbums([...albums, newAlbum]);

    if (inlineTracks.length > 0) {
      const newTracksList: Track[] = inlineTracks.map(t => {
        const playsNum = parseFormattedNumber(t.plays);
        return {
          id: Math.random().toString(36).substr(2, 9),
          title: t.title || 'Untitled Stream', artistId: formData.albumArtistId, artistName: artist?.name || 'Unknown', albumId: albumId, albumTitle: formData.albumTitle,
          duration: t.duration || getRandomDuration(), plays: playsNum, likes: Math.floor(playsNum * 0.05),
          isLiked: false, isExplicit: t.explicit, coverUrl: formData.albumImg || ''
        };
      });
      setTracks((prev: Track[]) => [...prev, ...newTracksList]);
    }
    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId);
    const album = albums.find(a => a.id === formData.trackAlbumId);
    const id = editingId || Math.random().toString(36).substr(2, 9);
    const plays = parseFormattedNumber(formData.trackPlays);
    const newTrack: Track = {
      id, title: formData.trackTitle, artistId: formData.trackArtistId, artistName: artist?.name || 'Unknown',
      albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration || getRandomDuration(), plays, 
      likes: parseFormattedNumber(formData.trackLikes) || Math.floor(plays * 0.05), isLiked: editingId ? (tracks.find(t => t.id === editingId)?.isLiked || false) : false, 
      composer: formData.trackComposer, isExplicit: formData.trackExplicit, 
      coverUrl: formData.trackImg || album?.coverUrl || `https://picsum.photos/seed/${formData.trackTitle}/400/400`, featuredArtist: formData.trackFit
    };
    if (editingId) setTracks((prev: Track[]) => prev.map(t => t.id === editingId ? newTrack : t));
    else setTracks([...tracks, newTrack]);
    resetForm();
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ 
      ...formData, 
      artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', 
      albumTitle: '', albumProducer: '', albumImg: '', 
      trackTitle: '', trackPlays: '0', trackLikes: '0', trackFit: '', trackComposer: '', trackImg: '', 
      trackDuration: getRandomDuration() 
    });
    setInlineTracks([]);
  };

  const handleAddInlineTrack = () => {
    const artist = artists.find(a => a.id === formData.albumArtistId);
    const followers = artist ? artist.followers : 10000;
    // Random proportional plays: between 0.5% and 15% of followers
    const proportionalPlays = Math.floor(followers * (getRandomValue(5, 150) / 1000));
    setInlineTracks([...inlineTracks, {title: '', duration: getRandomDuration(), explicit: false, plays: formatNumber(proportionalPlays)}]);
  };

  return (
    <div className="p-8 max-w-6xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-16 bg-zinc-900/30 p-10 rounded-[4rem] border border-white/5 backdrop-blur-2xl shadow-2xl">
        <h2 className="text-4xl font-black uppercase italic tracking-tighter leading-none">Global Editor</h2>
        <div className="flex gap-2 p-2 bg-black rounded-3xl border border-zinc-800 shadow-xl">
          {['artist', 'album', 'track', 'manage'].map(t => (
            <button key={t} onClick={() => { setActiveTab(t as any); resetForm(); }} className={`px-8 py-2.5 rounded-2xl font-black text-xs uppercase transition-all italic ${activeTab === t ? 'bg-zinc-700 text-white shadow-xl' : 'text-zinc-600 hover:text-white'}`}>{t}</button>
          ))}
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-16">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-12 bg-zinc-900/10 p-12 rounded-[4.5rem] border border-white/5 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)]">
            {activeTab === 'artist' && (
              <div className="space-y-8">
                <InputGroup label="Entity Name" placeholder="Broadcast Name" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                <div className="grid grid-cols-2 gap-8">
                  <InputGroup label="Genre Spectrum" placeholder="Electronic" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                  <InputGroup label="Listeners Base" numeric value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                </div>
                <InputGroup label="Origin" placeholder="USA" value={formData.artistCountry} onChange={v => setFormData({...formData, artistCountry: v})} />
                <div className="flex gap-10 px-4">
                  <label className="flex items-center gap-4 cursor-pointer group"><input type="checkbox" checked={formData.artistVerified} onChange={e => setFormData({...formData, artistVerified: e.target.checked})} className="w-6 h-6 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0 shadow-xl" /><span className="text-xs font-black uppercase tracking-[0.2em] text-zinc-500 group-hover:text-white transition-all italic">Verified Unit</span></label>
                  <label className="flex items-center gap-4 cursor-pointer group"><input type="checkbox" checked={formData.artistTrending} onChange={e => setFormData({...formData, artistTrending: e.target.checked})} className="w-6 h-6 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0 shadow-xl" /><span className="text-xs font-black uppercase tracking-[0.2em] text-zinc-500 group-hover:text-white transition-all italic">Rising Signal</span></label>
                </div>
                {/* Enhanced Bio section with AI Manifest button */}
                <div className="relative group">
                  <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} placeholder="Signal Manifesto (Biography)..." rows={4} className="w-full bg-zinc-800/20 border-2 border-zinc-800/50 rounded-[2.5rem] p-8 text-xl font-bold tracking-tight italic outline-none focus:border-green-400/30 transition-all shadow-inner" />
                  <button 
                    onClick={generateAIBio}
                    disabled={isGeneratingBio}
                    className="absolute right-6 bottom-6 flex items-center gap-2 bg-zinc-900 border border-zinc-800 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] italic hover:border-green-400 hover:text-green-400 transition-all shadow-2xl disabled:opacity-50"
                  >
                    {isGeneratingBio ? <Zap className="w-3 h-3 animate-pulse text-green-400" /> : <Sparkles className="w-3 h-3" />}
                    {isGeneratingBio ? 'Syncing...' : 'AI Manifest'}
                  </button>
                </div>
                <button onClick={saveArtist} className="w-full py-7 bg-white text-black font-black text-2xl rounded-[2.5rem] hover:scale-[1.03] active:scale-[0.97] transition-all shadow-2xl uppercase italic">Synchronize</button>
              </div>
            )}
            {activeTab === 'album' && (
              <div className="space-y-8">
                <InputGroup label="Collection Title" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                <div className="grid grid-cols-2 gap-8">
                  <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-zinc-800/20 border-2 border-zinc-800/50 rounded-[2rem] p-6 font-black text-lg outline-none appearance-none italic shadow-xl focus:border-green-400/30"><option value="">Assign Creator Identity...</option>{artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
                  <InputGroup label="Master Producer" placeholder="Code Name" value={formData.albumProducer} onChange={v => setFormData({...formData, albumProducer: v})} />
                </div>
                <div className="grid grid-cols-2 gap-8">
                  <InputGroup label="Spectrum Genre" value={formData.albumGenre} onChange={v => setFormData({...formData, albumGenre: v})} />
                  <InputGroup label="Deployment Year" type="number" value={formData.albumYear} onChange={v => setFormData({...formData, albumYear: v})} />
                </div>
                {!editingId && (
                  <div className="pt-10 border-t border-white/5 space-y-8">
                    <div className="flex items-center justify-between px-4"><span className="text-xs font-black uppercase tracking-[0.3em] text-zinc-600 italic">Signal Log (Tracks)</span><button onClick={handleAddInlineTrack} className="text-xs font-black text-green-500 uppercase tracking-widest bg-zinc-900 px-6 py-2.5 rounded-full border border-green-500/20 hover:scale-105 transition-all shadow-lg">+ Add Signal</button></div>
                    <div className="space-y-4">
                      {inlineTracks.map((t, i) => (
                        <div key={i} className="grid grid-cols-[1fr_100px_140px_40px] gap-5 items-center bg-zinc-900/40 p-5 rounded-[2rem] border border-white/5 shadow-inner">
                          <input placeholder="Signal Title" value={t.title} onChange={e => { const n = [...inlineTracks]; n[i].title = e.target.value; setInlineTracks(n); }} className="bg-transparent border-none rounded-xl p-3 text-lg font-black italic outline-none" />
                          <input placeholder="0:00" value={t.duration} onChange={e => { const n = [...inlineTracks]; n[i].duration = e.target.value; setInlineTracks(n); }} className="bg-zinc-800/40 border-none rounded-2xl p-3 text-sm font-black text-center italic shadow-md" />
                          <div className="relative group">
                            <input placeholder="Plays" value={t.plays} onChange={e => { const n = [...inlineTracks]; n[i].plays = e.target.value.replace(/\D/g, ''); setInlineTracks(n); }} className="w-full bg-zinc-800/40 border-none rounded-2xl p-3 text-sm font-black text-right tabular-nums italic shadow-md pr-10" />
                            <Dices onClick={() => { 
                              const artist = artists.find(a => a.id === formData.albumArtistId);
                              const followers = artist ? artist.followers : 10000;
                              const n = [...inlineTracks]; 
                              n[i].plays = formatNumber(Math.floor(followers * (getRandomValue(1, 150) / 1000))); 
                              setInlineTracks(n); 
                            }} className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600 hover:text-green-500 cursor-pointer transition-colors" />
                          </div>
                          <button onClick={() => setInlineTracks(inlineTracks.filter((_, idx) => idx !== i))} className="p-2.5 bg-red-500/10 rounded-xl hover:bg-red-500 hover:text-white transition-all"><Trash2 className="w-5 h-5" /></button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                <button onClick={saveAlbum} className="w-full py-7 bg-white text-black font-black text-2xl rounded-[2.5rem] hover:scale-[1.03] transition-all shadow-2xl italic uppercase">Deploy Archive</button>
              </div>
            )}
            {activeTab === 'track' && (
              <div className="space-y-8">
                <InputGroup label="Signal Designation" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
