// --- Helpers ---

const getRandomDuration = () => {
  const min = Math.floor(Math.random() * 4) + 1;
  const sec = Math.floor(Math.random() * 60).toString().padStart(2, '0');
  return `${min}:${sec}`;
};

const getRandomValue = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const formatNumber = (num: number) => num.toLocaleString('de-DE');

const parseFormattedNumber = (str: string) => {
  if (typeof str !== 'string') return 0;
  return parseInt(str.replace(/\./g, '')) || 0;
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// --- Sub-components ---

const TrackRow: React.FC<{ track: Track, index: number, toggleLike: (id: string) => void, onPlay: () => void, hideStats?: boolean, size?: 'sm' | 'lg' }> = ({ track, index, toggleLike, onPlay, hideStats, size = 'sm' }) => {
  const isLarge = size === 'lg';
  return (
    <div 
      onClick={onPlay}
      className={`group grid ${isLarge ? 'grid-cols-[30px_1fr_40px_60px] md:grid-cols-[40px_1fr_140px_100px]' : 'grid-cols-[20px_1fr_40px_50px] md:grid-cols-[30px_1fr_110px_70px]'} gap-3 md:gap-4 items-center ${isLarge ? 'px-3 md:px-4 py-2.5 md:py-3.5' : 'px-2 md:px-3 py-2'} hover:bg-zinc-800/60 rounded-2xl transition-all cursor-pointer border border-transparent hover:border-white/5 active:bg-zinc-900`}
    >
      <div className={`${isLarge ? 'text-sm md:text-base' : 'text-xs md:text-sm'} text-zinc-500 group-hover:hidden font-bold`}>{index + 1}</div>
      <Play className={`hidden group-hover:block ${isLarge ? 'w-4 h-4 md:w-5 h-5' : 'w-3 h-3 md:w-4 h-4'} fill-white text-white`} />

      <div className="flex items-center gap-3 md:gap-4 min-w-0">
        <div className={`${isLarge ? 'w-10 h-10 md:w-14 h-14' : 'w-8 h-8 md:w-10 h-10'} bg-zinc-800 rounded-lg md:rounded-xl overflow-hidden flex-shrink-0 shadow-lg border border-white/5`}>
           <img src={track.coverUrl || 'https://picsum.photos/seed/track/200/200'} className="w-full h-full object-cover" alt="" />
        </div>
        <div className="flex flex-col min-w-0">
          <div className="flex items-center gap-1.5 md:gap-2">
            <span className={`${isLarge ? 'text-sm md:text-lg' : 'text-xs md:text-base'} font-bold truncate tracking-tight ${track.isLiked ? 'text-green-400' : 'text-zinc-100'} group-hover:text-white`}>{track.title}</span>
            {track.isExplicit && <span className="bg-zinc-700 text-[8px] md:text-[9px] font-bold px-1 rounded flex-shrink-0">E</span>}
          </div>
          <div className="flex items-center gap-1 md:gap-2">
            <span className={`${isLarge ? 'text-[10px] md:text-sm' : 'text-[9px] md:text-xs'} text-zinc-400 font-semibold truncate group-hover:text-zinc-300`}>{track.artistName}</span>
            {track.featuredArtist && <span className="hidden md:inline text-zinc-500 text-[10px] font-medium truncate italic">ft. {track.featuredArtist}</span>}
          </div>
        </div>
      </div>

      <div className={`${isLarge ? 'text-[10px] md:text-sm' : 'text-[9px] md:text-[11px]'} text-zinc-500 text-right tabular-nums font-bold hidden md:block`}>
        {!hideStats ? formatNumber(track.plays) : ''}
      </div>

      <div className="flex items-center justify-end gap-3 md:gap-5">
        <Heart 
          onClick={(e) => { e.stopPropagation(); toggleLike(track.id); }}
          className={`w-3.5 h-3.5 md:w-4 h-4 transition-all hover:scale-125 ${track.isLiked ? 'text-green-500 fill-green-500' : 'opacity-0 group-hover:opacity-100 text-zinc-600 hover:text-white'}`} 
        />
        <span className="text-zinc-500 text-[10px] md:text-xs font-bold tabular-nums">{track.duration}</span>
      </div>
    </div>
  );
};

