            <div className="md:hidden">
               <h1 className="text-xl font-black tracking-tighter uppercase italic text-white flex items-center gap-2" onClick={() => navigateTo('home')}>
                <Sparkles className="text-green-400 fill-green-400 w-5 h-5" />
                MUSAIC
