    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4 md:gap-8">
      {items.map((item: any) => (
        <div key={item.id} onClick={() => navigateTo(type === 'track' ? 'track' : (type === 'album' ? 'album' : 'artist'), { id: item.id })} className="bg-zinc-900/20 p-3 md:p-5 rounded-2xl md:rounded-[3.5rem] hover:bg-zinc-800/40 transition-all cursor-pointer group shadow-2xl border border-transparent hover:border-zinc-800">
          <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/300/300`} className={`w-full aspect-square object-cover mb-4 md:mb-6 shadow-2xl transition-all group-hover:scale-105 ${type === 'artist' ? 'rounded-full' : 'rounded-xl md:rounded-[2.5rem]'}`} alt="" />
          <p className="font-bold truncate text-sm md:text-lg tracking-tighter uppercase italic">{item.name || item.title}</p>
          <p className="text-zinc-600 text-[8px] md:text-[11px] font-bold uppercase tracking-widest italic opacity-60">{item.artistName || (type === 'artist' ? 'Confirmed Artist' : '')}</p>
        </div>
      ))}
    </div>
  );

  return (
    <div className="p-4 md:p-10 animate-in bg-black min-h-full">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between mb-8 md:mb-16 gap-4">
        <h2 className="text-4xl md:text-7xl font-black tracking-tighter uppercase italic">Vault</h2>
        <div className="flex gap-1.5 p-1 bg-zinc-900/50 rounded-xl md:rounded-2xl border border-white/5 shadow-2xl w-full md:w-auto">
          {['all', 'artists', 'albums', 'tracks'].map(t => (
            <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:flex-none px-4 md:px-8 py-2 md:py-2.5 rounded-lg md:rounded-xl font-black text-[10px] md:text-xs uppercase transition-all italic ${activeTab === t ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-600 hover:text-white'}`}>{t}</button>
          ))}
        </div>
      </div>

      {activeTab === 'all' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-10 mb-10 md:mb-20">
          <div onClick={() => setActiveTab('artists')} className="bg-zinc-900/30 p-8 md:p-12 rounded-[2.5rem] md:rounded-[4rem] flex flex-col items-center justify-center gap-4 md:gap-8 cursor-pointer border border-white/5 hover:bg-zinc-800/50 transition-all group shadow-2xl">
            <div className="w-16 h-16 md:w-24 h-24 bg-zinc-800 rounded-full flex items-center justify-center group-hover:scale-110 transition-transform shadow-xl"><User className="w-8 h-8 md:w-12 h-12 text-green-500" /></div>
            <p className="text-xl md:text-3xl font-black uppercase italic tracking-tighter">Artists</p>
            <p className="text-[9px] md:text-[11px] text-zinc-600 font-bold uppercase tracking-[0.3em] italic opacity-60">{artists.length} Units</p>
          </div>
          <div onClick={() => setActiveTab('albums')} className="bg-zinc-900/30 p-8 md:p-12 rounded-[2.5rem] md:rounded-[4rem] flex flex-col items-center justify-center gap-4 md:gap-8 cursor-pointer border border-white/5 hover:bg-zinc-800/50 transition-all group shadow-2xl">
            <div className="w-16 h-16 md:w-24 h-24 bg-zinc-800 rounded-2xl md:rounded-[2.5rem] flex items-center justify-center group-hover:scale-110 transition-transform shadow-xl"><Disc className="w-8 h-8 md:w-12 h-12 text-green-500" /></div>
            <p className="text-xl md:text-3xl font-black uppercase italic tracking-tighter">Albums</p>
            <p className="text-[9px] md:text-[11px] text-zinc-600 font-bold uppercase tracking-[0.3em] italic opacity-60">{albums.length} Archives</p>
          </div>
          <div onClick={() => setActiveTab('tracks')} className="bg-zinc-900/30 p-8 md:p-12 rounded-[2.5rem] md:rounded-[4rem] flex flex-col items-center justify-center gap-4 md:gap-8 cursor-pointer border border-white/5 hover:bg-zinc-800/50 transition-all group shadow-2xl">
            <div className="w-16 h-16 md:w-24 h-24 bg-zinc-800 rounded-2xl md:rounded-3xl flex items-center justify-center group-hover:scale-110 transition-transform shadow-xl"><Music className="w-8 h-8 md:w-12 h-12 text-green-500" /></div>
            <p className="text-xl md:text-3xl font-black uppercase italic tracking-tighter">Tracks</p>
            <p className="text-[9px] md:text-[11px] text-zinc-600 font-bold uppercase tracking-[0.3em] italic opacity-60">{tracks.length} Signals</p>
          </div>
        </div>
      )}

      {activeTab === 'artists' && <LibraryGrid items={artists} type="artist" />}
      {activeTab === 'albums' && <LibraryGrid items={albums} type="album" />}
      {activeTab === 'tracks' && <LibraryGrid items={tracks} type="track" />}
    </div>
  );
}

function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks, initialTab = 'artist', targetId }: any) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>(initialTab);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '', artistCountry: '', artistTrending: false,
    albumTitle: '', albumArtistId: targetId || '', albumImg: '', albumYear: new Date().getFullYear(), albumGenre: '', albumLabel: '', albumProducer: '',
    trackTitle: '', trackArtistId: targetId || '', trackAlbumId: '', trackDuration: getRandomDuration(), trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: '', trackFit: ''
  });

  const fillRealisticStats = () => {
    if (activeTab === 'artist') {
      const followers = getRandomValue(10000, 50000000);
      setFormData((prev: any) => ({ ...prev, artistFollowers: formatNumber(followers) }));
    } else if (activeTab === 'track') {
      const plays = getRandomValue(50000, 100000000);
      const likes = Math.floor(plays * (getRandomValue(1, 15) / 100));
      setFormData((prev: any) => ({ ...prev, trackPlays: formatNumber(plays), trackLikes: formatNumber(likes) }));
    }
  };

  const [isGeneratingBio, setIsGeneratingBio] = useState(false);
  const generateAIBio = async () => {
    if (!formData.artistName) return;
    setIsGeneratingBio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create a professional and futuristic music bio for an artist named "${formData.artistName}". Genre: ${formData.artistGenre || 'Contemporary'}. Keep it under 40 words, focus on a high-tech/cyberpunk aesthetic for the 'MUSAIC' brand.`,
      });
      if (response.text) {
        setFormData((prev: any) => ({ ...prev, artistBio: response.text.trim() }));
      }
    } catch (error) {
      console.error("AI Bio Generation failed:", error);
    } finally {
      setIsGeneratingBio(false);
    }
  };

  const [inlineTracks, setInlineTracks] = useState<{title: string, duration: string, explicit: boolean, plays: string}[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const saveArtist = () => {
    if (!formData.artistName) return;
    const followers = parseFormattedNumber(formData.artistFollowers);
    const id = editingId || Math.random().toString(36).substr(2, 9);
    const newArtist: Artist = {
      id,
      name: formData.artistName, bio: formData.artistBio, imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
      genre: formData.artistGenre, followers, verified: formData.artistVerified, country: formData.artistCountry, isRisingStar: formData.artistTrending
    };
    if (editingId) setArtists((prev: Artist[]) => prev.map(a => a.id === editingId ? newArtist : a));
    else setArtists([...artists, newArtist]);
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId);
    const albumId = editingId || Math.random().toString(36).substr(2, 9);
    const newAlbum: Album = {
      id: albumId, title: formData.albumTitle, artistId: formData.albumArtistId, artistName: artist?.name || 'Unknown',
      coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`, releaseYear: Number(formData.albumYear),
      genre: formData.albumGenre, isLiked: false, label: formData.albumLabel, producer: formData.albumProducer
    };
    if (editingId) setAlbums((prev: Album[]) => prev.map(a => a.id === editingId ? newAlbum : a));
    else setAlbums([...albums, newAlbum]);

    if (inlineTracks.length > 0) {
      const newTracksList: Track[] = inlineTracks.map(t => {
        const playsNum = parseFormattedNumber(t.plays);
        return {
          id: Math.random().toString(36).substr(2, 9),
          title: t.title || 'Untitled Stream', artistId: formData.albumArtistId, artistName: artist?.name || 'Unknown', albumId: albumId, albumTitle: formData.albumTitle,
          duration: t.duration || getRandomDuration(), plays: playsNum, likes: Math.floor(playsNum * 0.05),
          isLiked: false, isExplicit: t.explicit, coverUrl: formData.albumImg || ''
        };
      });
      setTracks((prev: Track[]) => [...prev, ...newTracksList]);
    }
    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId);
    const album = albums.find(a => a.id === formData.trackAlbumId);
    const id = editingId || Math.random().toString(36).substr(2, 9);
    const plays = parseFormattedNumber(formData.trackPlays);
    const newTrack: Track = {
      id, title: formData.trackTitle, artistId: formData.trackArtistId, artistName: artist?.name || 'Unknown',
      albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration || getRandomDuration(), plays, 
      likes: parseFormattedNumber(formData.trackLikes) || Math.floor(plays * 0.05), isLiked: editingId ? (tracks.find(t => t.id === editingId)?.isLiked || false) : false, 
      composer: formData.trackComposer, isExplicit: formData.trackExplicit, 
      coverUrl: formData.trackImg || album?.coverUrl || `https://picsum.photos/seed/${formData.trackTitle}/400/400`, featuredArtist: formData.trackFit
    };
    if (editingId) setTracks((prev: Track[]) => prev.map(t => t.id === editingId ? newTrack : t));
    else setTracks([...tracks, newTrack]);
    resetForm();
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ 
      ...formData, 
      artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', 
      albumTitle: '', albumProducer: '', albumImg: '', 
      trackTitle: '', trackPlays: '0', trackLikes: '0', trackFit: '', trackComposer: '', trackImg: '', 
      trackDuration: getRandomDuration() 
    });
    setInlineTracks([]);
  };

  const handleAddInlineTrack = () => {
    const artist = artists.find(a => a.id === formData.albumArtistId);
    const followers = artist ? artist.followers : 10000;
    const proportionalPlays = Math.floor(followers * (getRandomValue(5, 150) / 1000));
    setInlineTracks([...inlineTracks, {title: '', duration: getRandomDuration(), explicit: false, plays: formatNumber(proportionalPlays)}]);
  };

  return (
    <div className="p-4 md:p-8 max-w-6xl mx-auto min-h-screen">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between mb-8 md:mb-16 bg-zinc-900/30 p-6 md:p-10 rounded-3xl md:rounded-[4rem] border border-white/5 backdrop-blur-2xl shadow-2xl gap-6">
        <h2 className="text-2xl md:text-4xl font-black uppercase italic tracking-tighter leading-none">Global Editor</h2>
        <div className="flex gap-1 p-1 bg-black rounded-2xl md:rounded-3xl border border-zinc-800 shadow-xl w-full md:w-auto">
          {['artist', 'album', 'track', 'manage'].map(t => (
            <button key={t} onClick={() => { setActiveTab(t as any); resetForm(); }} className={`flex-1 md:flex-none px-3 md:px-8 py-2 md:py-2.5 rounded-lg md:rounded-2xl font-black text-[9px] md:text-xs uppercase transition-all italic ${activeTab === t ? 'bg-zinc-700 text-white shadow-xl' : 'text-zinc-600 hover:text-white'}`}>{t}</button>
          ))}
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8 md:gap-16">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-8 md:space-y-12 bg-zinc-900/10 p-6 md:p-12 rounded-3xl md:rounded-[4.5rem] border border-white/5 shadow-2xl">
            {activeTab === 'artist' && (
              <div className="space-y-6 md:space-y-8">
                <InputGroup label="Entity Name" placeholder="Broadcast Name" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
                  <InputGroup label="Genre Spectrum" placeholder="Electronic" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                  <InputGroup label="Listeners Base" numeric value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                </div>
                <InputGroup label="Origin" placeholder="USA" value={formData.artistCountry} onChange={v => setFormData({...formData, artistCountry: v})} />
                <div className="flex flex-col md:flex-row gap-4 md:gap-10 px-2 md:px-4">
                  <label className="flex items-center gap-3 md:gap-4 cursor-pointer group"><input type="checkbox" checked={formData.artistVerified} onChange={e => setFormData({...formData, artistVerified: e.target.checked})} className="w-5 h-5 md:w-6 h-6 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0 shadow-xl" /><span className="text-[10px] md:text-xs font-black uppercase tracking-[0.2em] text-zinc-500 group-hover:text-white transition-all italic">Verified Unit</span></label>
                  <label className="flex items-center gap-3 md:gap-4 cursor-pointer group"><input type="checkbox" checked={formData.artistTrending} onChange={e => setFormData({...formData, artistTrending: e.target.checked})} className="w-5 h-5 md:w-6 h-6 rounded bg-zinc-800 border-zinc-700 text-green-500 focus:ring-0 shadow-xl" /><span className="text-[10px] md:text-xs font-black uppercase tracking-[0.2em] text-zinc-500 group-hover:text-white transition-all italic">Rising Signal</span></label>
                </div>
                <div className="relative group">
                  <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} placeholder="Signal Manifesto (Biography)..." rows={4} className="w-full bg-zinc-800/20 border-2 border-zinc-800/50 rounded-2xl md:rounded-[2.5rem] p-4 md:p-8 text-sm md:text-xl font-bold tracking-tight italic outline-none focus:border-green-400/30 transition-all shadow-inner" />
                  <button onClick={generateAIBio} disabled={isGeneratingBio} className="absolute right-4 md:right-6 bottom-4 md:bottom-6 flex items-center gap-2 bg-zinc-900 border border-zinc-800 px-3 md:px-4 py-1.5 md:py-2 rounded-xl md:rounded-2xl text-[8px] md:text-[10px] font-black uppercase tracking-[0.2em] italic hover:border-green-400 hover:text-green-400 transition-all shadow-2xl disabled:opacity-50">
                    {isGeneratingBio ? <Zap className="w-2.5 h-2.5 md:w-3 h-3 animate-pulse text-green-400" /> : <Sparkles className="w-2.5 h-2.5 md:w-3 h-3" />}
                    {isGeneratingBio ? 'Syncing...' : 'AI Manifest'}
                  </button>
                </div>
                <button onClick={saveArtist} className="w-full py-4 md:py-7 bg-white text-black font-black text-lg md:text-2xl rounded-2xl md:rounded-[2.5rem] hover:scale-[1.03] active:scale-[0.97] transition-all shadow-2xl uppercase italic">Synchronize</button>
              </div>
            )}
            {activeTab === 'album' && (
              <div className="space-y-6 md:space-y-8">
                <InputGroup label="Collection Title" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
                  <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-zinc-800/20 border-2 border-zinc-800/50 rounded-xl md:rounded-[2rem] p-4 md:p-6 font-black text-sm md:text-lg outline-none appearance-none italic shadow-xl focus:border-green-400/30"><option value="">Assign Creator Identity...</option>{artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
                  <InputGroup label="Master Producer" placeholder="Code Name" value={formData.albumProducer} onChange={v => setFormData({...formData, albumProducer: v})} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
                  <InputGroup label="Spectrum Genre" value={formData.albumGenre} onChange={v => setFormData({...formData, albumGenre: v})} />
                  <InputGroup label="Deployment Year" type="number" value={formData.albumYear} onChange={v => setFormData({...formData, albumYear: v})} />
                </div>
                {!editingId && (
                  <div className="pt-6 md:pt-10 border-t border-white/5 space-y-6 md:space-y-8">
                    <div className="flex items-center justify-between px-2 md:px-4"><span className="text-[10px] md:text-xs font-black uppercase tracking-[0.3em] text-zinc-600 italic">Signal Log (Tracks)</span><button onClick={handleAddInlineTrack} className="text-[10px] md:text-xs font-black text-green-500 uppercase tracking-widest bg-zinc-900 px-4 md:px-6 py-1.5 md:py-2.5 rounded-full border border-green-500/20 hover:scale-105 transition-all shadow-lg">+ Add Signal</button></div>
                    <div className="space-y-3 md:space-y-4">
                      {inlineTracks.map((t, i) => (
                        <div key={i} className="grid grid-cols-[1fr_80px_100px_40px] gap-2 md:gap-5 items-center bg-zinc-900/40 p-3 md:p-5 rounded-xl md:rounded-[2rem] border border-white/5 shadow-inner">
                          <input placeholder="Signal Title" value={t.title} onChange={e => { const n = [...inlineTracks]; n[i].title = e.target.value; setInlineTracks(n); }} className="bg-transparent border-none rounded-lg p-1.5 md:p-3 text-sm md:text-lg font-black italic outline-none" />
                          <input placeholder="0:00" value={t.duration} onChange={e => { const n = [...inlineTracks]; n[i].duration = e.target.value; setInlineTracks(n); }} className="bg-zinc-800/40 border-none rounded-lg md:rounded-2xl p-2 md:p-3 text-[10px] md:text-sm font-black text-center italic shadow-md" />
                          <div className="relative group">
                            <input placeholder="Plays" value={t.plays} onChange={e => { const n = [...inlineTracks]; n[i].plays = e.target.value.replace(/\D/g, ''); setInlineTracks(n); }} className="w-full bg-zinc-800/40 border-none rounded-lg md:rounded-2xl p-2 md:p-3 text-[10px] md:text-sm font-black text-right tabular-nums italic shadow-md pr-8 md:pr-10" />
                            <Dices onClick={() => { 
                              const artist = artists.find(a => a.id === formData.albumArtistId);
                              const followers = artist ? artist.followers : 10000;
                              const n = [...inlineTracks]; 
                              n[i].plays = formatNumber(Math.floor(followers * (getRandomValue(1, 150) / 1000))); 
                              setInlineTracks(n); 
                            }} className="absolute right-2 md:right-3 top-1/2 -translate-y-1/2 w-3 md:w-4 h-3 md:h-4 text-zinc-600 hover:text-green-500 cursor-pointer transition-colors" />
                          </div>
                          <button onClick={() => setInlineTracks(inlineTracks.filter((_, idx) => idx !== i))} className="p-2 md:p-2.5 bg-red-500/10 rounded-lg md:rounded-xl hover:bg-red-500 hover:text-white transition-all"><Trash2 className="w-4 md:w-5 h-4 md:h-5" /></button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                <button onClick={saveAlbum} className="w-full py-4 md:py-7 bg-white text-black font-black text-lg md:text-2xl rounded-2xl md:rounded-[2.5rem] hover:scale-[1.03] transition-all shadow-2xl italic uppercase">Deploy Archive</button>
              </div>
            )}
            {activeTab === 'track' && (
              <div className="space-y-6 md:space-y-8">
                <InputGroup label="Signal Designation" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
                  <select value={formData.trackArtistId} onChange={e => setFormData({...formData, trackArtistId: e.target.value, trackAlbumId: ''})} className="w-full bg-zinc-800/20 border-2 border-zinc-800/50 rounded-xl md:rounded-[2rem] p-4 md:p-6 font-black text-sm md:text-lg outline-none appearance-none italic shadow-xl focus:border-green-400/30"><option value="">Assigned Identity...</option>{artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
                  <select value={formData.trackAlbumId} onChange={e => setFormData({...formData, trackAlbumId: e.target.value})} className="w-full bg-zinc-800/20 border-2 border-zinc-800/50 rounded-xl md:rounded-[2rem] p-4 md:p-6 font-black text-sm md:text-lg outline-none appearance-none italic shadow-xl focus:border-green-400/30"><option value="single">Isolated Broadcast (Single)</option>{albums.filter(a => a.artistId === formData.trackArtistId).map(a => <option key={a.id} value={a.id}>{a.title}</option>)}</select>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
                  <InputGroup label="Primary Composer" value={formData.trackComposer} onChange={v => setFormData({...formData, trackComposer: v})} />
                  <InputGroup label="Signal Feature (ft.)" placeholder="ft. Alias" value={formData.trackFit} onChange={v => setFormData({...formData, trackFit: v})} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-8">
                  <InputGroup label="Signal Length" value={formData.trackDuration} onChange={v => setFormData({...formData, trackDuration: v})} />
                  <InputGroup label="Broadcasts" numeric value={formData.trackPlays} onChange={v => setFormData({...formData, trackPlays: v})} />
                  <InputGroup label="Evaluations (Likes)" numeric value={formData.trackLikes} onChange={v => setFormData({...formData, trackLikes: v})} />
                </div>
                <button onClick={saveTrack} className="w-full py-4 md:py-7 bg-white text-black font-black text-lg md:text-2xl rounded-2xl md:rounded-[2.5rem] hover:scale-[1.03] transition-all shadow-2xl italic uppercase">Broadcast Signal</button>
              </div>
            )}
          </div>
        )}
        {activeTab !== 'manage' && (
          <div className="space-y-8 md:space-y-12">
            <div className="bg-zinc-900/20 p-6 md:p-10 rounded-3xl md:rounded-[4rem] border border-white/5 text-center shadow-3xl">
              <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-square bg-zinc-800/40 rounded-2xl md:rounded-[3rem] border-4 border-dashed border-zinc-700 flex flex-col items-center justify-center cursor-pointer hover:border-green-500 transition-all overflow-hidden relative shadow-inner">
                {(activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)) ? <img src={activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)} className="w-full h-full object-cover" alt="" /> : <><ImageIcon className="w-10 h-10 md:w-16 h-16 text-zinc-700 mb-4 md:mb-6" /><p className="text-[9px] md:text-[11px] font-black text-zinc-600 uppercase tracking-widest italic">Visual Data</p></>}
                <div className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity"><Upload className="w-8 h-8 md:w-12 h-12 text-white" /></div>
              </div>
