             <ManagementSection title="Albums" items={albums} onDelete={(id: string) => setAlbums(prev => prev.filter(a => a.id !== id))} onEdit={(id: string) => { const a = albums.find(i => i.id === id)!; setEditingId(id); setActiveTab('album'); setFormData({...formData, albumTitle: a.title, albumArtistId: a.artistId, albumImg: a.coverUrl, albumYear: a.releaseYear, albumGenre: a.genre, albumLabel: a.label || '', albumProducer: a.producer || ''}); }} icon={Disc} />
             <ManagementSection title="Tracks" items={tracks} onDelete={(id: string) => setTracks(prev => prev.filter(t => t.id !== id))} onEdit={(id: string) => { const a = tracks.find(i => i.id === id)!; setEditingId(id); setActiveTab('track'); setFormData({...formData, trackTitle: a.title, trackArtistId: a.artistId, trackAlbumId: a.albumId, trackDuration: a.duration, trackPlays: formatNumber(a.plays), trackLikes: formatNumber(a.likes), trackComposer: a.composer || '', trackExplicit: a.isExplicit || false, trackImg: a.coverUrl || '', trackFit: a.featuredArtist || ''}); }} icon={Music} />
          </div>
