// --- Helpers ---

const getRandomDuration = () => {
  const min = Math.floor(Math.random() * 4) + 1;
  const sec = Math.floor(Math.random() * 60).toString().padStart(2, '0');
  return `${min}:${sec}`;
};

const getRandomValue = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const formatNumber = (num: number) => num.toLocaleString('de-DE');

const parseFormattedNumber = (str: string) => {
  if (typeof str !== 'string') return 0;
  return parseInt(str.replace(/\./g, '')) || 0;
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// --- Sub-components ---

