  });

  const fillRealisticStats = () => {
    if (activeTab === 'artist') {
      setFormData((prev: any) => ({ ...prev, artistFollowers: formatNumber(getRandomValue(5000, 50000000)) }));
    } else if (activeTab === 'track') {
      const plays = getRandomValue(50000, 100000000);
      setFormData((prev: any) => ({ ...prev, trackPlays: formatNumber(plays), trackLikes: formatNumber(Math.floor(plays * 0.04)) }));
    }
  };

  const generateAIBio = async () => {
    if (!formData.artistName) return;
    setIsGeneratingBio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Music bio for "${formData.artistName}". Genre: ${formData.artistGenre || 'Unknown'}. Short, futuristic, cyberpunk vibe.`,
      });
      if (response.text) setFormData((prev: any) => ({ ...prev, artistBio: response.text.trim() }));
    } catch (e) { console.error(e); } finally { setIsGeneratingBio(false); }
  };

  const [inlineTracks, setInlineTracks] = useState<{title: string, duration: string, explicit: boolean, plays: string}[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const saveArtist = () => {
    if (!formData.artistName) return;
    const followers = parseFormattedNumber(formData.artistFollowers);
    const id = editingId || Math.random().toString(36).substr(2, 9);
    const newArtist: Artist = {
      id, name: formData.artistName, bio: formData.artistBio, imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
      genre: formData.artistGenre, followers, verified: formData.artistVerified, country: formData.artistCountry, isRisingStar: formData.artistTrending
    };
    if (editingId) setArtists((prev: any) => prev.map((a: any) => a.id === editingId ? newArtist : a));
    else setArtists([...artists, newArtist]);
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId);
    const albumId = editingId || Math.random().toString(36).substr(2, 9);
    const newAlbum: Album = {
      id: albumId, title: formData.albumTitle, artistId: formData.albumArtistId, artistName: artist?.name || 'Unknown',
      coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`, releaseYear: Number(formData.albumYear),
      genre: formData.albumGenre, isLiked: false, producer: formData.albumProducer
    };
    if (editingId) setAlbums((prev: any) => prev.map((a: any) => a.id === editingId ? newAlbum : a));
    else setAlbums([...albums, newAlbum]);

    if (inlineTracks.length > 0) {
      const newTracksList: Track[] = inlineTracks.map(t => ({
        id: Math.random().toString(36).substr(2, 9), title: t.title || 'Untitled', artistId: formData.albumArtistId, artistName: artist?.name || 'Unknown', albumId: albumId, albumTitle: formData.albumTitle,
        duration: t.duration || getRandomDuration(), plays: parseFormattedNumber(t.plays), likes: 0, isLiked: false, isExplicit: t.explicit, coverUrl: formData.albumImg || ''
      }));
      setTracks((prev: any) => [...prev, ...newTracksList]);
    }
    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId);
    const album = albums.find(a => a.id === formData.trackAlbumId);
    const id = editingId || Math.random().toString(36).substr(2, 9);
    const plays = parseFormattedNumber(formData.trackPlays);
    const newTrack: Track = {
      id, title: formData.trackTitle, artistId: formData.trackArtistId, artistName: artist?.name || 'Unknown',
      albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration || getRandomDuration(), plays, 
      likes: parseFormattedNumber(formData.trackLikes), isLiked: false, composer: formData.trackComposer, isExplicit: formData.trackExplicit, 
      coverUrl: formData.trackImg || album?.coverUrl || `https://picsum.photos/seed/${formData.trackTitle}/400/400`, featuredArtist: formData.trackFit
    };
    if (editingId) setTracks((prev: any) => prev.map((t: any) => t.id === editingId ? newTrack : t));
    else setTracks([...tracks, newTrack]);
    resetForm();
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ ...formData, artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', albumTitle: '', albumProducer: '', trackTitle: '', trackPlays: '0', trackDuration: getRandomDuration() });
    setInlineTracks([]);
  };

  return (
    <div className="p-4 md:p-8 max-w-6xl mx-auto">
      <div className="flex flex-col md:flex-row items-center justify-between mb-8 bg-zinc-950 p-6 md:p-10 rounded-3xl border border-zinc-900 gap-6">
        <h2 className="text-2xl md:text-4xl font-black uppercase italic tracking-tighter">Editor</h2>
        <div className="flex gap-1 p-1 bg-black rounded-xl border border-zinc-900 w-full md:w-auto overflow-x-auto">
          {['artist', 'album', 'track', 'manage'].map(t => (
            <button key={t} onClick={() => { setActiveTab(t as any); resetForm(); }} className={`flex-1 md:flex-none px-4 py-2 rounded-lg font-black text-[9px] md:text-xs uppercase transition-all italic ${activeTab === t ? 'bg-zinc-800 text-white' : 'text-zinc-700'}`}>{t}</button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-10">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-6 md:space-y-10 bg-zinc-950/50 p-6 md:p-12 rounded-3xl border border-zinc-900">
            {activeTab === 'artist' && (
              <div className="space-y-6">
                <InputGroup label="Entity Name" placeholder="System Code" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <InputGroup label="Genre" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                  <InputGroup label="Listeners" numeric value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                </div>
                <div className="relative">
                  <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} placeholder="Bio manifest..." rows={3} className="w-full bg-black border border-zinc-900 rounded-2xl p-4 text-xs md:text-lg font-bold italic outline-none focus:border-green-500/40" />
                  <button onClick={generateAIBio} disabled={isGeneratingBio} className="mt-2 text-[9px] font-black uppercase text-green-500 flex items-center gap-1.5"><Sparkles className="w-3 h-3" /> {isGeneratingBio ? 'Processing...' : 'AI Generate'}</button>
                </div>
                <button onClick={saveArtist} className="w-full py-4 bg-white text-black font-black rounded-2xl uppercase italic tracking-tighter">Sync Core</button>
              </div>
            )}
            {activeTab === 'album' && (
              <div className="space-y-6">
                <InputGroup label="Collection" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-black border border-zinc-900 rounded-xl p-4 font-black text-xs md:text-sm uppercase italic outline-none appearance-none"><option value="">Assign Unit...</option>{artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
                <div className="pt-6 border-t border-zinc-900">
                  <div className="flex justify-between items-center mb-4"><span className="text-[9px] font-black text-zinc-600 uppercase">Signals</span><button onClick={() => setInlineTracks([...inlineTracks, {title: '', duration: getRandomDuration(), explicit: false, plays: '0'}])} className="text-[9px] font-black text-green-500 uppercase">+ Add</button></div>
                  <div className="space-y-2">
                    {inlineTracks.map((t, i) => (
                      <div key={i} className="grid grid-cols-[1fr_80px_40px] gap-2 items-center">
                        <input placeholder="Title" value={t.title} onChange={e => { const n = [...inlineTracks]; n[i].title = e.target.value; setInlineTracks(n); }} className="bg-zinc-900 rounded-lg p-2.5 text-xs font-bold italic outline-none" />
                        <input placeholder="Duration" value={t.duration} onChange={e => { const n = [...inlineTracks]; n[i].duration = e.target.value; setInlineTracks(n); }} className="bg-zinc-900 rounded-lg p-2.5 text-xs font-bold text-center outline-none" />
                        <button onClick={() => setInlineTracks(inlineTracks.filter((_, idx) => idx !== i))} className="p-2.5 bg-red-500/10 text-red-500 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                      </div>
                    ))}
                  </div>
                </div>
                <button onClick={saveAlbum} className="w-full py-4 bg-white text-black font-black rounded-2xl uppercase italic">Deploy Archive</button>
              </div>
            )}
            {activeTab === 'track' && (
              <div className="space-y-6">
                <InputGroup label="Signal" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   <select value={formData.trackArtistId} onChange={e => setFormData({...formData, trackArtistId: e.target.value})} className="w-full bg-black border border-zinc-900 rounded-xl p-4 font-black text-xs uppercase italic outline-none"><option value="">Unit...</option>{artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
                   <select value={formData.trackAlbumId} onChange={e => setFormData({...formData, trackAlbumId: e.target.value})} className="w-full bg-black border border-zinc-900 rounded-xl p-4 font-black text-xs uppercase italic outline-none"><option value="single">Single</option>{albums.filter(a => a.artistId === formData.trackArtistId).map(a => <option key={a.id} value={a.id}>{a.title}</option>)}</select>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <InputGroup label="Duration" value={formData.trackDuration} onChange={v => setFormData({...formData, trackDuration: v})} />
                  <InputGroup label="Plays" numeric value={formData.trackPlays} onChange={v => setFormData({...formData, trackPlays: v})} />
                </div>
                <button onClick={saveTrack} className="w-full py-4 bg-white text-black font-black rounded-2xl uppercase italic">Broadcast</button>
              </div>
            )}
          </div>
        )}
        {activeTab !== 'manage' && (
          <div className="space-y-6">
            <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-square bg-zinc-950 rounded-3xl border border-zinc-900 flex flex-col items-center justify-center cursor-pointer overflow-hidden relative group">
              {(activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)) ? <img src={activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)} className="w-full h-full object-cover" alt="" /> : <><ImageIcon className="w-8 h-8 text-zinc-800 mb-4" /><span className="text-[9px] font-black text-zinc-700 uppercase italic">Artwork</span></>}
            </div>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={async (e) => { const f = e.target.files?.[0]; if (f) { const b = await fileToBase64(f); setFormData({...formData, [activeTab === 'artist' ? 'artistImg' : (activeTab === 'album' ? 'albumImg' : 'trackImg')]: b}); } }} />
            <button onClick={fillRealisticStats} className="w-full py-3 bg-zinc-900 text-zinc-400 font-black text-[9px] rounded-xl uppercase italic border border-white/5">Random Metrics</button>
          </div>
        )}
        {activeTab === 'manage' && (
          <div className="col-span-1 md:col-span-3 space-y-12">
            <ManagementSection title="Artists" items={artists} onDelete={(id: string) => setArtists(prev => prev.filter(a => a.id !== id))} icon={User} />
            <ManagementSection title="Albums" items={albums} onDelete={(id: string) => setAlbums(prev => prev.filter(a => a.id !== id))} icon={Disc} />
            <ManagementSection title="Tracks" items={tracks} onDelete={(id: string) => setTracks(prev => prev.filter(t => t.id !== id))} icon={Music} />
          </div>
        )}
      </div>
    </div>
  );
}

const InputGroup = ({ label, type = 'text', numeric, placeholder, value, onChange }: any) => (
  <div className="space-y-2">
    <label className="text-[8px] font-black text-zinc-600 uppercase tracking-widest px-1 italic">{label}</label>
    <input type={numeric ? 'text' : type} value={value} onChange={e => { if (numeric) { const v = e.target.value.replace(/\D/g, ''); onChange(formatNumber(parseInt(v) || 0)); } else onChange(e.target.value); }} placeholder={placeholder} className="w-full bg-black border border-zinc-900 rounded-xl p-3 text-xs md:text-sm font-black italic outline-none focus:border-green-500/40 transition-all shadow-inner" />
  </div>
);

const ManagementSection = ({ title, items, onDelete, icon: Icon }: any) => (
  <div className="space-y-6">
    <h3 className="text-xl md:text-4xl font-black italic uppercase leading-none">{title} <span className="text-zinc-800">({items.length})</span></h3>
    <div className="grid grid-cols-2 md:grid-cols-5 gap-3 md:gap-6">
      {items.map((item: any) => (
        <div key={item.id} className="bg-zinc-950 p-3 md:p-5 rounded-2xl border border-zinc-900 flex flex-col gap-3">
          <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/200/200`} className={`w-full aspect-square object-cover ${title === 'Artists' ? 'rounded-full' : 'rounded-lg'}`} alt="" />
          <p className="text-[11px] md:text-sm font-black truncate uppercase italic tracking-tighter">{item.name || item.title}</p>
          <button onClick={() => onDelete(item.id)} className="w-full py-2 bg-red-500/10 text-red-500 rounded-lg"><Trash2 className="w-3.5 h-3.5 mx-auto" /></button>
        </div>
      ))}
    </div>
  </div>
);

function TrackPage({ id, tracks, albums, artists, navigateTo }: any) {
  const track = tracks.find((t: any) => t.id === id);
  if (!track) return <div className="p-20 text-center text-2xl font-black opacity-10 uppercase italic">Lost Signal</div>;
  const artist = artists.find((a: any) => a.id === track.artistId);
  return (
    <div className="min-h-full flex flex-col p-4 md:p-16 bg-black animate-in">
      <div className="flex flex-col lg:flex-row items-center gap-10 md:gap-24 mt-6 md:mt-16 max-w-7xl mx-auto w-full">
        <div className="w-full max-w-[280px] md:w-96 md:h-96 lg:w-[500px] lg:h-[500px] shadow-2xl rounded-3xl md:rounded-[5rem] overflow-hidden border-[4px] md:border-[10px] border-zinc-900 shrink-0"><img src={track.coverUrl} className="w-full h-full object-cover" alt="" /></div>
        <div className="flex flex-col items-center lg:items-start text-center lg:text-left min-w-0">
          <span className="text-[9px] md:text-xs font-black uppercase tracking-[0.4em] text-green-500 italic mb-4">Signal Broadcast</span>
          <h1 className="text-3xl md:text-7xl lg:text-[7vw] font-black mb-6 md:mb-12 tracking-tighter leading-none italic uppercase truncate w-full">{track.title}</h1>
          <div onClick={() => navigateTo('artist', { id: track.artistId })} className="flex items-center gap-3 md:gap-6 text-xl md:text-4xl font-black hover:text-green-400 cursor-pointer tracking-tighter mb-10 md:mb-16 italic uppercase"><img src={artist?.imageUrl} className="w-10 h-10 md:w-16 h-16 rounded-full shrink-0 border-2 border-zinc-800" alt="" />{track.artistName}</div>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-6 md:gap-16 w-full max-w-lg">
             <div className="flex flex-col gap-1 md:gap-3"><span className="text-[8px] md:text-[10px] font-black text-zinc-600 uppercase tracking-widest italic leading-none">Plays</span><span className="text-xl md:text-5xl font-black tabular-nums tracking-tighter leading-none">{formatNumber(track.plays)}</span></div>
             <div className="flex flex-col gap-1 md:gap-3"><span className="text-[8px] md:text-[10px] font-black text-zinc-600 uppercase tracking-widest italic leading-none">Record</span><span className="text-xl md:text-5xl font-black truncate leading-none uppercase">{track.albumTitle}</span></div>
          </div>
        </div>
      </div>
    </div>
  );
}

function AlbumView({ id, albums, tracks, toggleLikeTrack, toggleLikeAlbum, navigateTo }: any) {
  const album = albums.find((a: any) => a.id === id);
  if (!album) return <div className="p-20 text-center text-2xl font-black opacity-10 uppercase italic">Void</div>;
  const albumTracks = tracks.filter((t: any) => t.albumId === id);
  return (
    <div className="bg-black min-h-full">
      <div className="p-6 md:p-14 flex flex-col md:flex-row items-center md:items-end gap-8 md:gap-24 max-w-7xl mx-auto">
        <div className="w-full max-w-[240px] md:w-80 md:h-80 lg:w-[480px] lg:h-[480px] shadow-2xl rounded-2xl md:rounded-[5rem] overflow-hidden border-[6px] md:border-[12px] border-zinc-900 shrink-0"><img src={album.coverUrl} className="w-full h-full object-cover" alt="" /></div>
        <div className="flex flex-col items-center md:items-start text-center md:text-left min-w-0 flex-1">
          <span className="text-[9px] md:text-xs font-black uppercase tracking-[0.5em] text-zinc-700 italic mb-4">Archives</span>
          <h1 className="text-3xl md:text-7xl lg:text-[7vw] font-black mb-6 md:mb-12 tracking-tighter leading-[0.9] italic uppercase break-words w-full">{album.title}</h1>
          <p onClick={() => navigateTo('artist', { id: album.artistId })} className="text-xl md:text-3xl font-black italic tracking-tighter text-zinc-300 uppercase leading-none hover:text-green-500 cursor-pointer">{album.artistName}</p>
          <div className="mt-4 flex items-center gap-4 text-[10px] md:text-sm font-black text-zinc-700 uppercase tracking-widest italic"><span>{album.releaseYear}</span><span>•</span><span>{albumTracks.length} recordings</span></div>
        </div>
      </div>
      <div className="max-w-7xl mx-auto px-4 md:px-14 pb-20">
        <div className="flex items-center gap-6 md:gap-12 mb-10 md:mb-20">
          <button className="w-12 h-12 md:w-16 h-16 bg-green-500 rounded-full flex items-center justify-center shadow-xl"><Play className="text-black fill-black ml-0.5 md:ml-1 w-6 h-6 md:w-8 h-8" /></button>
          <Heart onClick={() => toggleLikeAlbum(album.id)} className={`w-8 h-8 md:w-10 h-10 cursor-pointer transition-all ${album.isLiked ? 'text-green-500 fill-green-500' : 'text-zinc-800'}`} />
