function SearchView({ query, artists, albums, tracks, navigateTo, toggleLikeTrack }: any) {
  const filteredArtists = artists.filter((a: any) => a.name.toLowerCase().includes(query.toLowerCase()));
  const filteredTracks = tracks.filter((t: any) => t.title.toLowerCase().includes(query.toLowerCase()));
  if (!query) {
    return (
      <div className="p-4 md:p-12">
        <h3 className="text-xl md:text-5xl font-black mb-8 md:mb-16 tracking-tighter uppercase italic leading-none">Matrix Nodes</h3>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 md:gap-10">
          {['Electro', 'Neon', 'Deep Pulse', 'Industrial', 'Hyper', 'Ambient', 'Techno', 'Atmospheric'].map(g => (
            <div key={g} className="bg-zinc-950 aspect-video md:aspect-auto md:h-40 rounded-2xl md:rounded-[3rem] p-6 md:p-10 relative overflow-hidden group cursor-pointer border border-zinc-900 hover:bg-zinc-900 transition-all flex items-center">
              <span className="text-lg md:text-3xl lg:text-4xl font-black relative z-10 tracking-tighter italic uppercase leading-none">{g}</span>
              <img src={`https://picsum.photos/seed/${g}/600/400`} className="absolute inset-0 w-full h-full object-cover opacity-20 group-hover:scale-110 transition-transform duration-700 mix-blend-screen" alt="" />
              <div className="absolute inset-0 bg-gradient-to-r from-black/80 to-transparent z-[5]"></div>
            </div>
          ))}
        </div>
      </div>
    );
  }
  return (
    <div className="p-4 md:p-12">
      {filteredArtists.length > 0 && <div className="mb-16 md:mb-24"><h3 className="text-xl md:text-3xl font-black mb-6 md:mb-10 tracking-tighter uppercase italic leading-none">Units</h3><div className="flex gap-4 md:gap-10 overflow-x-auto pb-4 custom-scrollbar">{filteredArtists.map((a: any) => <div key={a.id} onClick={() => navigateTo('artist', { id: a.id })} className="shrink-0 w-36 md:w-64 bg-zinc-950 p-4 md:p-10 rounded-[2rem] md:rounded-[4rem] hover:bg-zinc-900 transition-all cursor-pointer border border-zinc-900"><img src={a.imageUrl} className="w-full aspect-square object-cover rounded-full mb-4 md:mb-8" alt="" /><p className="font-black truncate text-xs md:text-xl tracking-tighter text-center italic uppercase leading-none">{a.name}</p></div>)}</div></div>}
      {filteredTracks.length > 0 && <div className="mb-16"><h3 className="text-xl md:text-3xl font-black mb-6 md:mb-10 tracking-tighter uppercase italic leading-none">Signals</h3><div className="space-y-1.5 max-w-6xl">{filteredTracks.map((t: any, i: number) => <TrackRow key={t.id} track={t} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: t.id })} size="lg" />)}</div></div>}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Home, 
  Search, 
  Library, 
  PlusCircle, 
  Heart, 
  Play, 
  MoreHorizontal, 
  Mic2, 
  Disc, 
  Music,
  ChevronLeft,
  ChevronRight,
  User,
  Sparkles,
  CheckCircle2,
  ListMusic,
  Clock,
  Trash2,
  Upload,
  Image as ImageIcon,
  Check,
  Zap,
  Dices,
  Settings2,
  Download,
  FileUp,
  Plus,
  Globe,
  TrendingUp,
  CircleCheck,
  ArrowRight,
  Menu,
  X
} from 'lucide-react';
import { Artist, Album, Track, ViewType, NavigationState, HomeViewProps, ArtistViewProps } from './types';
import { GoogleGenAI } from "@google/genai";

// --- Helpers ---

const getRandomDuration = () => {
  const min = Math.floor(Math.random() * 4) + 1;
  const sec = Math.floor(Math.random() * 60).toString().padStart(2, '0');
  return `${min}:${sec}`;
};

const getRandomValue = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const formatNumber = (num: number) => num.toLocaleString('de-DE');

const parseFormattedNumber = (str: string) => {
  if (typeof str !== 'string') return 0;
  return parseInt(str.replace(/\./g, '')) || 0;
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// --- Sub-components ---

const TrackRow: React.FC<{ track: Track, index: number, toggleLike: (id: string) => void, onPlay: () => void, hideStats?: boolean, size?: 'sm' | 'lg' }> = ({ track, index, toggleLike, onPlay, hideStats, size = 'sm' }) => {
  const isLarge = size === 'lg';
  return (
    <div 
      onClick={onPlay}
      className={`group grid ${isLarge ? 'grid-cols-[30px_1fr_40px_50px] md:grid-cols-[40px_1fr_140px_100px]' : 'grid-cols-[20px_1fr_40px_45px] md:grid-cols-[30px_1fr_110px_70px]'} gap-2 md:gap-4 items-center ${isLarge ? 'px-2 md:px-4 py-2 md:py-3.5' : 'px-1.5 md:px-3 py-1.5'} hover:bg-zinc-800/60 rounded-xl md:rounded-2xl transition-all cursor-pointer border border-transparent hover:border-white/5 active:bg-zinc-900`}
    >
      <div className={`${isLarge ? 'text-xs md:text-base' : 'text-[10px] md:text-sm'} text-zinc-500 group-hover:hidden font-bold`}>{index + 1}</div>
      <Play className={`hidden group-hover:block ${isLarge ? 'w-3.5 h-3.5 md:w-5 h-5' : 'w-3 h-3 md:w-4 h-4'} fill-white text-white`} />

      <div className="flex items-center gap-2 md:gap-4 min-w-0">
        <div className={`${isLarge ? 'w-10 h-10 md:w-14 h-14' : 'w-8 h-8 md:w-10 h-10'} bg-zinc-800 rounded-lg md:rounded-xl overflow-hidden flex-shrink-0 shadow-lg border border-white/5`}>
           <img src={track.coverUrl || 'https://picsum.photos/seed/track/200/200'} className="w-full h-full object-cover" alt="" />
        </div>
        <div className="flex flex-col min-w-0">
          <div className="flex items-center gap-1 md:gap-2 overflow-hidden">
            <span className={`${isLarge ? 'text-sm md:text-lg' : 'text-[11px] md:text-base'} font-bold truncate tracking-tight ${track.isLiked ? 'text-green-400' : 'text-zinc-100'} group-hover:text-white`}>{track.title}</span>
            {track.isExplicit && <span className="bg-zinc-700 text-[7px] md:text-[9px] font-black px-1 rounded flex-shrink-0">E</span>}
          </div>
          <div className="flex items-center gap-1 md:gap-2">
            <span className={`${isLarge ? 'text-[9px] md:text-sm' : 'text-[8px] md:text-xs'} text-zinc-500 font-bold truncate uppercase tracking-tighter group-hover:text-zinc-300`}>{track.artistName}</span>
          </div>
        </div>
      </div>

      <div className={`${isLarge ? 'text-[9px] md:text-sm' : 'text-[8px] md:text-[11px]'} text-zinc-500 text-right tabular-nums font-bold hidden md:block`}>
        {!hideStats ? formatNumber(track.plays) : ''}
      </div>

      <div className="flex items-center justify-end gap-2 md:gap-5">
        <Heart 
          onClick={(e) => { e.stopPropagation(); toggleLike(track.id); }}
          className={`w-3 h-3 md:w-4 h-4 transition-all hover:scale-125 ${track.isLiked ? 'text-green-500 fill-green-500' : 'opacity-0 group-hover:opacity-100 text-zinc-700 hover:text-white'}`} 
        />
        <span className="text-zinc-600 text-[9px] md:text-xs font-bold tabular-nums">{track.duration}</span>
      </div>
    </div>
  );
};

// --- Main App ---

export default function App() {
  const [nav, setNav] = useState<NavigationState>({ view: 'home' });
  const [artists, setArtists] = useState<Artist[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [history, setHistory] = useState<NavigationState[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [sidebarWidth, setSidebarWidth] = useState(240);
  const isResizing = useRef(false);

  useEffect(() => {
    const savedData = localStorage.getItem('musaic_master_db');
    if (savedData) {
      try {
        const { artists: a, albums: al, tracks: t } = JSON.parse(savedData);
        if (a) setArtists(a);
        if (al) setAlbums(al);
        if (t) setTracks(t);
      } catch (e) { console.error(e); }
    }

    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizing.current) return;
      setSidebarWidth(Math.max(200, Math.min(400, e.clientX)));
    };
    const handleMouseUp = () => { isResizing.current = false; document.body.style.cursor = 'default'; };
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  useEffect(() => {
    localStorage.setItem('musaic_master_db', JSON.stringify({ artists, albums, tracks }));
  }, [artists, albums, tracks]);

  const navigateTo = (view: ViewType, params?: { id?: string }) => {
    setHistory(prev => [...prev, nav]);
    setNav({ view, params });
  };

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setNav(prev);
    }
  };

  const toggleLikeTrack = (id: string) => {
    setTracks(prev => prev.map(t => t.id === id ? { ...t, isLiked: !t.isLiked, likes: t.isLiked ? t.likes - 1 : t.likes + 1 } : t));
  };

  const toggleLikeAlbum = (id: string) => {
    setAlbums(prev => prev.map(a => a.id === id ? { ...a, isLiked: !a.isLiked } : a));
  };

  const SidebarItem = ({ icon: Icon, label, active, onClick, compact = false }: { icon: any, label: string, active: boolean, onClick: () => void, compact?: boolean }) => (
    <button 
      onClick={onClick} 
      className={`flex items-center transition-all group ${
        compact 
          ? 'flex-col gap-1 px-1 py-1 justify-center flex-1' 
          : 'w-full gap-4 px-4 py-3 rounded-2xl'
      } ${active ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-500 hover:text-white hover:bg-zinc-900/50'}`}
    >
      <Icon className={`${compact ? 'w-4 h-4' : 'w-5 h-5'} ${active ? 'text-green-400' : 'group-hover:text-green-400'}`} />
      <span className={`font-black tracking-tighter uppercase ${compact ? 'text-[8px]' : 'text-xs'}`}>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-black text-zinc-100 select-none overflow-hidden font-['Inter'] flex-col md:flex-row">
      <aside 
        style={{ width: `${sidebarWidth}px` }} 
        className="hidden md:flex bg-black p-4 flex-col gap-3 border-r border-zinc-900 z-50 relative shrink-0"
      >
        <div className="p-2 mb-4 cursor-pointer group" onClick={() => navigateTo('home')}>
          <h1 className="text-xl font-black flex items-center gap-2 tracking-tighter uppercase italic group-hover:scale-105 transition-transform">
            <Sparkles className="text-green-400 fill-green-400 w-6 h-6" />
            MUSAIC
          </h1>
        </div>
        <div className="space-y-1">
          <SidebarItem icon={Home} label="Home" active={nav.view === 'home'} onClick={() => navigateTo('home')} />
          <SidebarItem icon={Search} label="Search" active={nav.view === 'search'} onClick={() => navigateTo('search')} />
          <SidebarItem icon={Library} label="Library" active={nav.view === 'library'} onClick={() => navigateTo('library')} />
        </div>
        <div className="mt-6 space-y-1">
          <h3 className="px-4 text-[8px] font-black text-zinc-700 uppercase tracking-[0.3em] mb-2">Master</h3>
          <SidebarItem icon={Settings2} label="Editor Hub" active={nav.view === 'creator'} onClick={() => navigateTo('creator')} />
        </div>
        <div className="mt-auto p-4 bg-zinc-900/20 rounded-2xl border border-white/5 backdrop-blur-xl">
          <p className="text-[8px] text-zinc-600 font-black uppercase tracking-[0.2em] mb-3 opacity-70 italic text-center">Core Analytics</p>
          <div className="space-y-1 text-[10px] text-zinc-400 font-bold uppercase tracking-tighter">
            <div className="flex justify-between"><span>Artists</span> <span className="text-white">{artists.length}</span></div>
            <div className="flex justify-between"><span>Albums</span> <span className="text-white">{albums.length}</span></div>
            <div className="flex justify-between"><span>Tracks</span> <span className="text-white">{tracks.length}</span></div>
          </div>
        </div>
        <div onMouseDown={() => { isResizing.current = true; document.body.style.cursor = 'col-resize'; }} className="absolute top-0 right-0 w-1 h-full cursor-col-resize hover:bg-green-500/20"></div>
      </aside>

      <main className="flex-1 flex flex-col bg-black overflow-hidden relative">
        <header className="h-14 md:h-16 flex items-center justify-between px-4 md:px-8 sticky top-0 z-40 bg-black/80 backdrop-blur-xl md:bg-transparent">
          <div className="flex items-center gap-2 md:gap-4 overflow-hidden max-w-[70%]">
            <button onClick={goBack} className="p-1.5 md:p-2 bg-zinc-900/60 rounded-full hover:bg-black transition-all border border-white/5 shrink-0"><ChevronLeft className="w-4 h-4 md:w-5 h-5" /></button>
            <button className="hidden md:block p-2 bg-black/10 rounded-full opacity-20 cursor-not-allowed shrink-0"><ChevronRight className="w-5 h-5" /></button>
            {nav.view === 'search' && (
              <div className="relative shrink min-w-0">
                <Search className="absolute left-3 md:left-4 top-1/2 -translate-y-1/2 w-3.5 h-3.5 md:w-4 h-4 text-zinc-600" />
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search..." className="bg-zinc-800/40 hover:bg-zinc-800 border-none rounded-full py-1.5 pl-9 md:pl-10 pr-4 md:pr-6 w-full max-w-[200px] md:w-64 text-xs md:text-sm font-black italic outline-none focus:ring-2 focus:ring-green-500/20 transition-all" />
              </div>
            )}
            <div className="md:hidden shrink-0">
               <h1 className="text-sm font-black tracking-tighter uppercase italic text-white flex items-center gap-1.5" onClick={() => navigateTo('home')}>
                <Sparkles className="text-green-400 fill-green-400 w-4 h-4" />
                MUSAIC
              </h1>
            </div>
          </div>
          <div className="bg-zinc-900 border border-white/5 px-2.5 md:px-4 py-1.5 rounded-full text-[7px] md:text-[9px] font-black flex items-center gap-1.5 md:gap-2 uppercase tracking-[0.2em] italic shrink-0">
            <Zap className="w-2 md:w-3 h-2 md:h-3 text-green-400 fill-green-400 animate-pulse" />
            Studio
          </div>
        </header>

        <div className="flex-1 overflow-y-auto pb-40 scroll-smooth custom-scrollbar">
          {nav.view === 'home' && <HomeView artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} />}
          {nav.view === 'artist' && <ArtistView id={nav.params?.id || ''} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'artist_tracks' && <ArtistTracksView id={nav.params?.id || ''} artists={artists} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'album' && <AlbumView id={nav.params?.id || ''} albums={albums} tracks={tracks} toggleLikeTrack={toggleLikeTrack} toggleLikeAlbum={toggleLikeAlbum} navigateTo={navigateTo} />}
          {nav.view === 'track' && <TrackPage id={nav.params?.id || ''} tracks={tracks} albums={albums} artists={artists} toggleLikeTrack={toggleLikeTrack} navigateTo={navigateTo} />}
          {nav.view === 'creator' && <CreatorHub artists={artists} setArtists={setArtists} albums={albums} setAlbums={setAlbums} tracks={tracks} setTracks={setTracks} initialTab={nav.params?.id ? (artists.find(a => a.id === nav.params?.id) ? 'artist' : 'album') : 'artist'} targetId={nav.params?.id} />}
          {nav.view === 'library' && <LibraryView albums={albums} artists={artists} tracks={tracks} navigateTo={navigateTo} />}
          {nav.view === 'search' && <SearchView query={searchQuery} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
        </div>

        {/* Player Bar */}
        <div className="absolute bottom-16 md:bottom-0 left-0 right-0 h-16 md:h-24 bg-black/90 backdrop-blur-2xl border-t border-zinc-900 flex items-center justify-between px-3 md:px-8 z-[60]">
           <div className="flex items-center gap-2.5 md:gap-4 w-[60%] md:w-1/3 min-w-0">
            <div className="w-10 h-10 md:w-14 h-14 bg-zinc-800 rounded-lg md:rounded-xl overflow-hidden shadow-xl shrink-0 group border border-white/5">
              <img src="https://picsum.photos/seed/placeholder/300/300" alt="" className="w-full h-full object-cover transition-transform group-hover:scale-110" />
            </div>
            <div className="min-w-0">
              <p className="text-[11px] md:text-sm font-black truncate tracking-tighter uppercase italic">Protocol Idle</p>
              <p className="text-[8px] md:text-[10px] text-zinc-600 font-black uppercase tracking-[0.15em] truncate italic leading-none">External Link</p>
            </div>
          </div>
          <div className="flex flex-col items-center gap-1.5 md:gap-2 shrink-0">
            <div className="flex items-center gap-3 md:gap-8">
              <button className="hidden md:block text-zinc-600 hover:text-white transition-all"><Disc className="w-5 h-5" /></button>
              <button className="w-9 h-9 md:w-10 h-10 bg-white rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-xl"><Play className="w-5 h-5 md:w-6 h-6 text-black fill-black ml-0.5 md:ml-1" /></button>
              <button className="text-zinc-600 hover:text-white transition-all"><MoreHorizontal className="w-4 h-4 md:w-5 h-5" /></button>
            </div>
          </div>
          <div className="hidden md:flex items-center justify-end gap-5 w-1/3 text-zinc-600 shrink-0">
             <Mic2 className="w-4 h-4 hover:text-white cursor-pointer" />
             <ListMusic className="w-4 h-4 hover:text-white cursor-pointer" />
             <div className="flex items-center gap-3">
               <Music className="w-4 h-4" />
               <div className="w-20 h-1 bg-zinc-800 rounded-full overflow-hidden"><div className="w-3/4 h-full bg-zinc-500"></div></div>
             </div>
          </div>
