        {/* Mobile Navigation */}
        <nav className="md:hidden fixed bottom-0 left-0 right-0 h-16 bg-black border-t border-zinc-900 z-[70] flex items-center justify-around px-1">
          <SidebarItem icon={Home} label="Home" active={nav.view === 'home'} onClick={() => navigateTo('home')} compact />
          <SidebarItem icon={Search} label="Search" active={nav.view === 'search'} onClick={() => navigateTo('search')} compact />
          <SidebarItem icon={Library} label="Vault" active={nav.view === 'library'} onClick={() => navigateTo('library')} compact />
