// --- Helpers ---

const getRandomDuration = () => {
  const min = Math.floor(Math.random() * 4) + 1;
  const sec = Math.floor(Math.random() * 60).toString().padStart(2, '0');
  return `${min}:${sec}`;
};

const getRandomValue = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const formatNumber = (num: number) => {
  if (isNaN(num)) return '0';
  return num.toLocaleString('de-DE');
};

const parseFormattedNumber = (str: string) => {
  if (typeof str !== 'string') return 0;
  return parseInt(str.replace(/\./g, '')) || 0;
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

const getDynamicFontSize = (text: string, baseClasses: string, isAlbum: boolean = false) => {
  if (isAlbum) {
    if (text.length > 40) return baseClasses.replace(/lg:text-\[\d+vw\]/, 'lg:text-[5.5vw]');
    if (text.length > 25) return baseClasses.replace(/lg:text-\[\d+vw\]/, 'lg:text-[6.5vw]');
    return baseClasses;
  }
  if (text.length > 40) return baseClasses.replace(/md:text-\d+xl/, 'md:text-4xl').replace(/lg:text-\[\d+vw\]/, 'lg:text-[3.5vw]');
  if (text.length > 25) return baseClasses.replace(/md:text-\d+xl/, 'md:text-5xl').replace(/lg:text-\[\d+vw\]/, 'lg:text-[5vw]');
  return baseClasses;
};

const getRandomDateInYear = (year: number) => {
  const start = new Date(year, 0, 1);
  const end = new Date(year, 11, 31);
  const date = new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime()));
  return date.toISOString().split('T')[0];
};

const sortTracksByRelevance = (tracks: Track[]) => {
  return [...tracks].sort((a, b) => {
    const dateA = new Date(a.releaseDate).getTime();
    const dateB = new Date(b.releaseDate).getTime();
    if (dateA !== dateB) return dateB - dateA; // Newest first
    return b.plays - a.plays; // Then most plays
  });
};

