interface ThemeConfig {
  bgColor: string;
  accentColor: string;
  cardBg: string;
  textScale: number;
  uiScale: number;
  radiusFactor: number;
  blurIntensity: number;
  fontFamily: string;
  glowEnabled: boolean;
}

const DEFAULT_THEME: ThemeConfig = {
  bgColor: '#000000',
  accentColor: '#4ade80',
  cardBg: 'rgba(24, 24, 27, 0.4)',
