export default function App() {
  const [nav, setNav] = useState<NavigationState>({ view: 'home' });
  const [artists, setArtists] = useState<Artist[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [history, setHistory] = useState<NavigationState[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [sidebarWidth, setSidebarWidth] = useState(240);
  const [theme, setTheme] = useState<ThemeConfig>(DEFAULT_THEME);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const isResizing = useRef(false);

  useEffect(() => {
    // Load Data
    const savedData = localStorage.getItem('musaic_master_db');
    if (savedData) {
      try {
        const { artists: a, albums: al, tracks: t, theme: th } = JSON.parse(savedData);
        if (a) setArtists(a);
        if (al) setAlbums(al);
        if (t) setTracks(t);
        if (th) setTheme(th);
      } catch (e) { console.error(e); }
    }

    // Sidebar resize logic
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizing.current) return;
      setSidebarWidth(Math.max(200, Math.min(400, e.clientX)));
    };
    const handleMouseUp = () => { isResizing.current = false; document.body.style.cursor = 'default'; };
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  useEffect(() => {
    localStorage.setItem('musaic_master_db', JSON.stringify({ artists, albums, tracks, theme }));

    // Apply Theme to DOM
    const root = document.documentElement;
    root.style.setProperty('--bg-color', theme.bgColor);
    root.style.setProperty('--accent-color', theme.accentColor);
    root.style.setProperty('--accent-glow', `${theme.accentColor}${theme.glowEnabled ? '80' : '00'}`);
    root.style.setProperty('--text-scale', theme.textScale.toString());
    root.style.setProperty('--ui-scale', theme.uiScale.toString());
    root.style.setProperty('--radius-factor', theme.radiusFactor.toString());
    root.style.setProperty('--blur-intensity', `${theme.blurIntensity}px`);
    root.style.setProperty('--font-main', theme.fontFamily);
  }, [artists, albums, tracks, theme]);

  const navigateTo = (view: ViewType, params?: { id?: string }) => {
    setHistory(prev => [...prev, nav]);
    setNav({ view, params });
  };

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setNav(prev);
    }
  };

  const toggleLikeTrack = (id: string) => {
    setTracks(prev => prev.map(t => t.id === id ? { ...t, isLiked: !t.isLiked, likes: t.isLiked ? t.likes - 1 : t.likes + 1 } : t));
  };

  const toggleLikeAlbum = (id: string) => {
    setAlbums(prev => prev.map(a => a.id === id ? { ...a, isLiked: !a.isLiked } : a));
  };

  const SidebarItem = ({ icon: Icon, label, active, onClick, compact = false }: { icon: any, label: string, active: boolean, onClick: () => void, compact?: boolean }) => (
    <button 
      onClick={onClick} 
      className={`flex items-center transition-all group ${
        compact 
          ? 'flex-col gap-1 px-1 py-1 justify-center flex-1' 
          : 'w-full gap-4 px-4 py-3'
      } ${active ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-500 hover:text-white hover:bg-zinc-900/50'}`}
      style={{ borderRadius: `calc(1rem * var(--radius-factor))` }}
    >
      <Icon className={`${compact ? 'w-4 h-4' : 'w-5 h-5'} ${active ? 'theme-accent' : 'group-hover:theme-accent'}`} />
      <span className={`font-black tracking-tighter uppercase ${compact ? 'text-[8px]' : 'text-xs'}`}>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen text-zinc-100 select-none overflow-hidden flex-col md:flex-row bg-[var(--bg-color)]">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} theme={theme} setTheme={setTheme} />

      <aside 
        style={{ width: `${sidebarWidth}px` }} 
        className="hidden md:flex bg-[var(--bg-color)] p-4 flex-col gap-3 border-r border-white/5 z-50 relative shrink-0"
      >
        <div className="p-2 mb-4 cursor-pointer group" onClick={() => navigateTo('home')}>
          <h1 className="text-xl font-black flex items-center gap-2 tracking-tighter uppercase italic group-hover:scale-105 transition-transform">
            <Sparkles className="theme-accent theme-glow w-6 h-6 fill-current" />
            MUSAIC
          </h1>
        </div>
        <div className="space-y-1">
          <SidebarItem icon={Home} label="Home" active={nav.view === 'home'} onClick={() => navigateTo('home')} />
          <SidebarItem icon={Search} label="Search" active={nav.view === 'search'} onClick={() => navigateTo('search')} />
          <SidebarItem icon={Library} label="Library" active={nav.view === 'library'} onClick={() => navigateTo('library')} />
        </div>
        <div className="mt-6 space-y-1">
          <h3 className="px-4 text-[8px] font-black text-zinc-700 uppercase tracking-[0.3em] mb-2">Workspace</h3>
          <SidebarItem icon={Settings2} label="Editor Hub" active={nav.view === 'creator'} onClick={() => navigateTo('creator')} />
          <SidebarItem icon={Palette} label="Appearance" active={isSettingsOpen} onClick={() => setIsSettingsOpen(true)} />
