// --- Types & Constants ---

interface ThemeConfig {
  bgColor: string;
  accentColor: string;
  cardBg: string;
  textScale: number;
  uiScale: number;
  radiusFactor: number;
  blurIntensity: number;
  fontFamily: string;
  glowEnabled: boolean;
}

const DEFAULT_THEME: ThemeConfig = {
  bgColor: '#000000',
  accentColor: '#4ade80',
  cardBg: 'rgba(24, 24, 27, 0.4)',
  textScale: 1.0,
  uiScale: 1.0,
  radiusFactor: 1.0,
  blurIntensity: 20,
  fontFamily: "'Inter', sans-serif",
  glowEnabled: true,
};

// --- Helpers ---

// Add getRandomValue helper function to fix "Cannot find name 'getRandomValue'" errors
const getRandomValue = (min: number, max: number) => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

const getRandomDuration = () => {
  const min = Math.floor(Math.random() * 4) + 1;
  const sec = Math.floor(Math.random() * 60).toString().padStart(2, '0');
  return `${min}:${sec}`;
};

const formatNumber = (num: number) => {
  if (isNaN(num)) return '0';
  return num.toLocaleString('de-DE');
};

const parseFormattedNumber = (str: string) => {
  if (typeof str !== 'string') return 0;
  return parseInt(str.replace(/\./g, '')) || 0;
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

const getDynamicFontSize = (text: string, baseClasses: string, isAlbum: boolean = false) => {
  if (isAlbum) {
    if (text.length > 50) return baseClasses.replace(/lg:text-\[\d+vw\]/, 'lg:text-[4vw]');
    if (text.length > 30) return baseClasses.replace(/lg:text-\[\d+vw\]/, 'lg:text-[5.5vw]');
    if (text.length > 15) return baseClasses.replace(/lg:text-\[\d+vw\]/, 'lg:text-[6.5vw]');
    return baseClasses;
  }
  if (text.length > 50) return baseClasses.replace(/md:text-\d+xl/, 'md:text-3xl').replace(/lg:text-\[\d+vw\]/, 'lg:text-[3vw]');
  if (text.length > 30) return baseClasses.replace(/md:text-\d+xl/, 'md:text-4xl').replace(/lg:text-\[\d+vw\]/, 'lg:text-[4.5vw]');
  if (text.length > 15) return baseClasses.replace(/md:text-\d+xl/, 'md:text-5xl').replace(/lg:text-\[\d+vw\]/, 'lg:text-[6vw]');
  return baseClasses;
};

const sortTracksByRelevance = (tracks: Track[]) => {
  return [...tracks].sort((a, b) => {
    const dateA = new Date(a.releaseDate).getTime();
    const dateB = new Date(b.releaseDate).getTime();
    if (dateA !== dateB) return dateB - dateA;
    return b.plays - a.plays;
  });
};

