          <div className="flex items-center gap-1 md:gap-2 overflow-hidden">
            <span className={`${isLarge ? 'text-sm md:text-lg' : 'text-[11px] md:text-base'} font-bold truncate tracking-tight ${track.isLiked ? 'theme-accent' : 'text-zinc-100'} group-hover:text-white`}>{track.title}</span>
            {track.isExplicit && <span className="bg-zinc-700 text-[7px] md:text-[9px] font-black px-1 rounded flex-shrink-0">E</span>}
          </div>
          <div className="flex items-center gap-1 md:gap-2 overflow-hidden">
            <span className={`${isLarge ? 'text-[9px] md:text-sm' : 'text-[8px] md:text-xs'} text-zinc-500 font-bold truncate uppercase tracking-tighter group-hover:text-zinc-300`}>
              {track.artistName}
              {track.featuredArtist && <span className="text-zinc-600 ml-1">feat. {track.featuredArtist}</span>}
            </span>
          </div>
        </div>
      </div>

      <div className={`${isLarge ? 'text-[9px] md:text-sm' : 'text-[8px] md:text-[11px]'} text-zinc-500 text-right tabular-nums font-bold hidden md:block`}>
        {!hideStats ? formatNumber(track.plays) : ''}
      </div>

      <div className="flex items-center justify-end gap-2 md:gap-5">
        <Heart 
          onClick={(e) => { e.stopPropagation(); toggleLike(track.id); }}
          className={`w-3 h-3 md:w-4 h-4 transition-all hover:scale-125 ${track.isLiked ? 'theme-accent fill-current' : 'opacity-0 group-hover:opacity-100 text-zinc-700 hover:text-white'}`} 
        />
        <span className="text-zinc-600 text-[9px] md:text-xs font-bold tabular-nums">{track.duration}</span>
      </div>
    </div>
  );
};

