// --- Main App ---

export default function App() {
  const [nav, setNav] = useState<NavigationState>({ view: 'home' });
  const [artists, setArtists] = useState<Artist[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [history, setHistory] = useState<NavigationState[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [sidebarWidth, setSidebarWidth] = useState(240);
  const [theme, setTheme] = useState<ThemeConfig>(DEFAULT_THEME);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const isResizing = useRef(false);

  useEffect(() => {
    // Load Data
    const savedData = localStorage.getItem('musaic_master_db');
    if (savedData) {
      try {
        const { artists: a, albums: al, tracks: t, theme: th } = JSON.parse(savedData);
        if (a) setArtists(a);
        if (al) setAlbums(al);
        if (t) setTracks(t);
        if (th) setTheme(th);
      } catch (e) { console.error(e); }
    }

    // Sidebar resize logic
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizing.current) return;
      setSidebarWidth(Math.max(200, Math.min(400, e.clientX)));
    };
    const handleMouseUp = () => { isResizing.current = false; document.body.style.cursor = 'default'; };
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  useEffect(() => {
    localStorage.setItem('musaic_master_db', JSON.stringify({ artists, albums, tracks, theme }));

    // Apply Theme to DOM
    const root = document.documentElement;
    root.style.setProperty('--bg-color', theme.bgColor);
    root.style.setProperty('--accent-color', theme.accentColor);
    root.style.setProperty('--accent-glow', `${theme.accentColor}${theme.glowEnabled ? '80' : '00'}`);
    root.style.setProperty('--text-scale', theme.textScale.toString());
    root.style.setProperty('--ui-scale', theme.uiScale.toString());
    root.style.setProperty('--radius-factor', theme.radiusFactor.toString());
    root.style.setProperty('--blur-intensity', `${theme.blurIntensity}px`);
    root.style.setProperty('--font-main', theme.fontFamily);
  }, [artists, albums, tracks, theme]);

  const navigateTo = (view: ViewType, params?: { id?: string }) => {
    setHistory(prev => [...prev, nav]);
    setNav({ view, params });
  };

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setNav(prev);
    }
  };

  const toggleLikeTrack = (id: string) => {
    setTracks(prev => prev.map(t => t.id === id ? { ...t, isLiked: !t.isLiked, likes: t.isLiked ? t.likes - 1 : t.likes + 1 } : t));
  };

  const toggleLikeAlbum = (id: string) => {
    setAlbums(prev => prev.map(a => a.id === id ? { ...a, isLiked: !a.isLiked } : a));
  };

  const SidebarItem = ({ icon: Icon, label, active, onClick, compact = false }: { icon: any, label: string, active: boolean, onClick: () => void, compact?: boolean }) => (
    <button 
      onClick={onClick} 
      className={`flex items-center transition-all group ${
        compact 
          ? 'flex-col gap-1 px-1 py-1 justify-center flex-1' 
          : 'w-full gap-4 px-4 py-3'
      } ${active ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-500 hover:text-white hover:bg-zinc-900/50'}`}
      style={{ borderRadius: `calc(1rem * var(--radius-factor))` }}
    >
      <Icon className={`${compact ? 'w-4 h-4' : 'w-5 h-5'} ${active ? 'theme-accent' : 'group-hover:theme-accent'}`} />
      <span className={`font-black tracking-tighter uppercase ${compact ? 'text-[8px]' : 'text-xs'}`}>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen text-zinc-100 select-none overflow-hidden flex-col md:flex-row bg-[var(--bg-color)]">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} theme={theme} setTheme={setTheme} />

      <aside 
        style={{ width: `${sidebarWidth}px` }} 
        className="hidden md:flex bg-[var(--bg-color)] p-4 flex-col gap-3 border-r border-white/5 z-50 relative shrink-0"
      >
        <div className="p-2 mb-4 cursor-pointer group" onClick={() => navigateTo('home')}>
          <h1 className="text-xl font-black flex items-center gap-2 tracking-tighter uppercase italic group-hover:scale-105 transition-transform">
            <Sparkles className="theme-accent theme-glow w-6 h-6 fill-current" />
            MUSAIC
          </h1>
        </div>
        <div className="space-y-1">
          <SidebarItem icon={Home} label="Home" active={nav.view === 'home'} onClick={() => navigateTo('home')} />
          <SidebarItem icon={Search} label="Search" active={nav.view === 'search'} onClick={() => navigateTo('search')} />
          <SidebarItem icon={Library} label="Library" active={nav.view === 'library'} onClick={() => navigateTo('library')} />
        </div>
        <div className="mt-6 space-y-1">
          <h3 className="px-4 text-[8px] font-black text-zinc-700 uppercase tracking-[0.3em] mb-2">Workspace</h3>
          <SidebarItem icon={Settings2} label="Editor Hub" active={nav.view === 'creator'} onClick={() => navigateTo('creator')} />
          <SidebarItem icon={Palette} label="Appearance" active={isSettingsOpen} onClick={() => setIsSettingsOpen(true)} />
        </div>

        <div className="mt-auto p-4 bg-zinc-900/20 border border-white/5 backdrop-blur-xl" style={{ borderRadius: `calc(1rem * var(--radius-factor))` }}>
          <p className="text-[8px] text-zinc-600 font-black uppercase tracking-[0.2em] mb-3 opacity-70 italic text-center">Core Analytics</p>
          <div className="space-y-1 text-[10px] text-zinc-400 font-bold uppercase tracking-tighter">
            <div className="flex justify-between"><span>Artists</span> <span className="text-white">{artists.length}</span></div>
            <div className="flex justify-between"><span>Albums</span> <span className="text-white">{albums.length}</span></div>
            <div className="flex justify-between"><span>Tracks</span> <span className="text-white">{tracks.length}</span></div>
          </div>
        </div>
        <div onMouseDown={() => { isResizing.current = true; document.body.style.cursor = 'col-resize'; }} className="absolute top-0 right-0 w-1 h-full cursor-col-resize hover:theme-bg-accent opacity-20 transition-all"></div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-14 md:h-16 flex items-center justify-between px-4 md:px-8 sticky top-0 z-40 bg-black/40 backdrop-blur-xl">
          <div className="flex items-center gap-2 md:gap-4 overflow-hidden max-w-[70%]">
            <button onClick={goBack} className="p-1.5 md:p-2 bg-zinc-900/60 rounded-full hover:bg-black transition-all border border-white/5 shrink-0"><ChevronLeft className="w-4 h-4 md:w-5 h-5" /></button>
            <button className="hidden md:block p-2 bg-black/10 rounded-full opacity-20 cursor-not-allowed shrink-0"><ChevronRight className="w-5 h-5" /></button>
            {nav.view === 'search' && (
              <div className="relative shrink min-w-0">
                <Search className="absolute left-3 md:left-4 top-1/2 -translate-y-1/2 w-3.5 h-3.5 md:w-4 h-4 text-zinc-600" />
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search..." className="bg-zinc-800/40 hover:bg-zinc-800 border-none rounded-full py-1.5 pl-9 md:pl-10 pr-4 md:pr-6 w-full max-w-[200px] md:w-64 text-xs md:text-sm font-black italic outline-none focus:ring-2 focus:theme-border-accent transition-all" />
              </div>
            )}
          </div>
          <div className="bg-zinc-900 border border-white/5 px-2.5 md:px-4 py-1.5 rounded-full text-[7px] md:text-[9px] font-black flex items-center gap-1.5 md:gap-2 uppercase tracking-[0.2em] italic shrink-0">
            <Zap className="theme-accent fill-current w-2 md:w-3 h-2 md:h-3 animate-pulse" />
            Studio
          </div>
        </header>

        <div className="flex-1 overflow-y-auto pb-40 scroll-smooth custom-scrollbar">
          {nav.view === 'home' && <HomeView artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} />}
          {nav.view === 'artist' && <ArtistView id={nav.params?.id || ''} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'artist_tracks' && <ArtistTracksView id={nav.params?.id || ''} artists={artists} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
          {nav.view === 'album' && <AlbumView id={nav.params?.id || ''} albums={albums} tracks={tracks} toggleLikeTrack={toggleLikeTrack} toggleLikeAlbum={toggleLikeAlbum} navigateTo={navigateTo} />}
          {nav.view === 'track' && <TrackPage id={nav.params?.id || ''} tracks={tracks} albums={albums} artists={artists} toggleLikeTrack={toggleLikeTrack} navigateTo={navigateTo} />}
          {nav.view === 'creator' && <CreatorHub artists={artists} setArtists={setArtists} albums={albums} setAlbums={setAlbums} tracks={tracks} setTracks={setTracks} initialTab={nav.params?.id ? (artists.find(a => a.id === nav.params?.id) ? 'artist' : 'album') : 'artist'} targetId={nav.params?.id} />}
          {nav.view === 'library' && <LibraryView albums={albums} artists={artists} tracks={tracks} navigateTo={navigateTo} />}
          {nav.view === 'search' && <SearchView query={searchQuery} artists={artists} albums={albums} tracks={tracks} navigateTo={navigateTo} toggleLikeTrack={toggleLikeTrack} />}
        </div>

        {/* Player Bar */}
        <div className="absolute bottom-16 md:bottom-0 left-0 right-0 h-16 md:h-24 bg-black/60 backdrop-blur-[var(--blur-intensity)] border-t border-white/5 flex items-center justify-between px-3 md:px-8 z-[60]">
           <div className="flex items-center gap-2.5 md:gap-4 w-[60%] md:w-1/3 min-w-0">
            <div className="w-10 h-10 md:w-14 h-14 bg-zinc-800 rounded-lg md:rounded-xl overflow-hidden shadow-xl shrink-0 group border border-white/5" style={{ borderRadius: `calc(0.75rem * var(--radius-factor))` }}>
              <img src="https://picsum.photos/seed/placeholder/300/300" alt="" className="w-full h-full object-cover transition-transform group-hover:scale-110" />
            </div>
            <div className="min-w-0">
              <p className="text-[11px] md:text-sm font-black truncate tracking-tighter uppercase italic">Protocol Idle</p>
              <p className="text-[8px] md:text-[10px] text-zinc-600 font-black uppercase tracking-[0.15em] truncate italic leading-none">System Standby</p>
            </div>
          </div>
          <div className="flex flex-col items-center gap-1.5 md:gap-2 shrink-0">
            <div className="flex items-center gap-3 md:gap-8">
              <button className="hidden md:block text-zinc-600 hover:text-white transition-all"><Disc className="w-5 h-5" /></button>
              <button className="w-9 h-9 md:w-10 h-10 bg-white rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-xl"><Play className="w-5 h-5 md:w-6 h-6 text-black fill-black ml-0.5 md:ml-1" /></button>
              <button className="text-zinc-600 hover:text-white transition-all"><MoreHorizontal className="w-4 h-4 md:w-5 h-5" /></button>
            </div>
          </div>
          <div className="hidden md:flex items-center justify-end gap-5 w-1/3 text-zinc-600 shrink-0">
             <Mic2 className="w-4 h-4 hover:text-white cursor-pointer" />
             <ListMusic className="w-4 h-4 hover:text-white cursor-pointer" />
             <div className="flex items-center gap-3">
               <Music className="w-4 h-4" />
               <div className="w-20 h-1 bg-zinc-800 rounded-full overflow-hidden"><div className="w-3/4 h-full bg-zinc-500"></div></div>
             </div>
          </div>
        </div>

        {/* Mobile Navigation */}
        <nav className="md:hidden fixed bottom-0 left-0 right-0 h-16 bg-black border-t border-white/5 z-[70] flex items-center justify-around px-1">
          <SidebarItem icon={Home} label="Home" active={nav.view === 'home'} onClick={() => navigateTo('home')} compact />
          <SidebarItem icon={Search} label="Search" active={nav.view === 'search'} onClick={() => navigateTo('search')} compact />
          <SidebarItem icon={Library} label="Vault" active={nav.view === 'library'} onClick={() => navigateTo('library')} compact />
          <SidebarItem icon={Settings2} label="Editor" active={nav.view === 'creator'} onClick={() => navigateTo('creator')} compact />
        </nav>
      </main>
    </div>
  );
}

// --- Content Views ---

function HomeView({ artists, albums, tracks, navigateTo }: HomeViewProps) {
  return (
    <div className="p-scale animate-in">
      <h2 className="text-2xl md:text-5xl font-black mb-6 md:mb-10 tracking-tighter uppercase italic leading-none">Pulse Feed</h2>
      {albums.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-scale mb-10 md:mb-14">
          {albums.slice(0, 6).map(album => (
            <div key={album.id} onClick={() => navigateTo('album', { id: album.id })} className="group flex items-center gap-3 md:gap-5 theme-card hover:bg-zinc-800/40 transition-all overflow-hidden cursor-pointer border border-white/5">
              <div className="w-14 h-14 md:w-20 h-20 shadow-xl shrink-0"><img src={album.coverUrl} className="w-full h-full object-cover" alt="" /></div>
              <p className="font-black text-xs md:text-lg flex-1 truncate pr-2 md:pr-4 tracking-tighter uppercase italic">{album.title}</p>
              <div className="mr-2 md:mr-5 w-7 h-7 md:w-10 h-10 theme-bg-accent rounded-full flex items-center justify-center opacity-0 md:group-hover:opacity-100 transition-all md:translate-y-2 md:group-hover:translate-y-0 shadow-lg shrink-0"><Play className="text-black fill-black ml-0.5 md:ml-1 w-3 h-3 md:w-6 h-6" /></div>
            </div>
          ))}
        </div>
      )}
      {tracks.length > 0 && (
        <div className="mb-10 md:mb-14">
          <h3 className="text-xl md:text-3xl font-black mb-4 md:mb-8 px-1 tracking-tighter uppercase italic leading-none">Signals</h3>
          <div className="space-y-1 md:space-y-2 max-w-5xl">
            {tracks.slice(0, 8).map((track, i) => <TrackRow key={track.id} track={track} index={i} toggleLike={() => {}} onPlay={() => navigateTo('track', { id: track.id })} size="lg" />)}
          </div>
        </div>
      )}
    </div>
  );
}

function ArtistView({ id, artists, albums, tracks, navigateTo, toggleLikeTrack }: ArtistViewProps) {
  const artist = artists.find(a => a.id === id);
  if (!artist) return <div className="p-20 text-center text-xl font-black opacity-20 italic">ENTITY LOST</div>;
  const artistAlbums = albums.filter(a => a.artistId === id);
  const artistTracks = sortTracksByRelevance(tracks.filter(t => t.artistId === id)).slice(0, 10);

  return (
    <div className="relative animate-in min-h-full">
      <div className="h-[220px] md:h-[400px] flex flex-col justify-end p-4 md:p-12 relative overflow-hidden">
        <img src={artist.imageUrl} className="absolute inset-0 w-full h-full object-cover opacity-50" alt="" />
        <div className="absolute inset-0 bg-gradient-to-t from-[var(--bg-color)] via-[var(--bg-color)]/40 to-transparent"></div>
