          <div className="flex items-baseline gap-1.5 md:gap-2.5">
             <span className="text-xl md:text-5xl font-black text-white tracking-tighter tabular-nums italic">{formatNumber(artist.followers)}</span>
             <span className="text-[8px] md:text-sm font-black uppercase tracking-[0.2em] text-zinc-500 italic opacity-80">Listeners</span>
