      <div className="max-w-7xl mx-auto px-4 md:px-12 py-6 md:py-10">
        <div className="flex items-center gap-4 md:gap-10 mb-10 md:mb-16">
          <button className="w-12 h-12 md:w-16 h-16 theme-bg-accent rounded-full flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-xl"><Play className="text-black fill-black ml-0.5 md:ml-1 w-6 h-6 md:w-8 h-8" /></button>
          <button className="border-2 border-white/10 px-6 md:px-10 py-2.5 md:py-3.5 rounded-xl md:rounded-2xl font-black text-xs md:text-lg hover:theme-border-accent transition-all uppercase tracking-[0.1em] italic">Follow</button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 md:gap-20">
          <div className="lg:col-span-2">
            <div className="flex items-center justify-between mb-6">
              <h3 onClick={() => navigateTo('artist_tracks', { id: artist.id })} className="text-xl md:text-3xl font-black tracking-tighter opacity-70 italic uppercase cursor-pointer hover:opacity-100 flex items-center gap-2">
                Signals <ArrowRight className="w-4 h-4" />
              </h3>
            </div>
            <div className="space-y-1 mb-16">
              {artistTracks.map((track, i) => <TrackRow key={track.id} track={track} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: track.id })} size="lg" />)}
            </div>

            {artistAlbums.length > 0 && (
              <div className="mb-16">
                <h3 className="text-xl md:text-3xl font-black mb-8 tracking-tighter opacity-70 italic uppercase">Discography</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-8">
                  {artistAlbums.map(album => (
                    <div key={album.id} onClick={() => navigateTo('album', { id: album.id })} className="theme-card p-3 md:p-5 hover:bg-zinc-800/40 transition-all cursor-pointer group border border-transparent">
                      <div className="aspect-square w-full rounded-2xl overflow-hidden mb-4 shadow-xl border border-white/5">
                        <img src={album.coverUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110 duration-500" alt="" />
                      </div>
                      <p className="font-black truncate text-xs md:text-lg tracking-tighter uppercase italic leading-none">{album.title}</p>
                      <p className="text-zinc-600 text-[9px] md:text-xs font-black uppercase tracking-widest italic mt-1">{album.releaseYear}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
          <div className="space-y-8">
            <h3 className="text-xl md:text-3xl font-black tracking-tighter opacity-70 italic uppercase">Log</h3>
            <p className="text-sm md:text-2xl font-bold leading-relaxed opacity-90 italic text-zinc-400">{artist.bio || "No description recorded."}</p>
          </div>
        </div>
      </div>
    </div>
  );
}

