          <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/300/300`} className={`w-full aspect-square object-cover mb-3 md:mb-6 shadow-2xl transition-all ${type === 'artist' ? 'rounded-full' : 'rounded-xl'}`} style={{ borderRadius: type === 'artist' ? '50%' : 'calc(1.5rem * var(--radius-factor))' }} alt="" />
          <p className="font-black truncate text-[11px] md:text-lg tracking-tighter uppercase italic leading-none">{item.name || item.title}</p>
          <p className="text-zinc-700 text-[8px] md:text-[11px] font-black uppercase tracking-[0.1em] italic mt-1">{item.artistName || (type === 'artist' ? 'Confirmed' : '')}</p>
