        <div className="flex gap-1 p-1 bg-black/40 rounded-xl border border-white/5 w-full md:w-auto overflow-hidden">
          {['all', 'artists', 'albums', 'tracks'].map(t => (
            <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:flex-none px-3 md:px-8 py-2 rounded-lg font-black text-[9px] md:text-xs uppercase transition-all italic ${activeTab === t ? 'bg-zinc-800 text-white shadow-lg' : 'text-zinc-700 hover:text-white'}`}>{t}</button>
          ))}
        </div>
      </div>

      {activeTab === 'all' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-scale">
          {['artists', 'albums', 'tracks'].map((type) => (
            <div key={type} onClick={() => setActiveTab(type as any)} className="bg-black/20 p-6 md:p-12 rounded-[2rem] flex flex-col items-center gap-3 md:gap-8 cursor-pointer border border-white/5 hover:bg-zinc-900/40 transition-all group" style={{ borderRadius: `calc(4rem * var(--radius-factor))` }}>
              <div className="w-12 h-12 md:w-24 h-24 bg-zinc-900/40 rounded-full flex items-center justify-center shrink-0">
                {type === 'artists' ? <User className="w-6 h-6 md:w-12 md:h-12 theme-accent" /> : type === 'albums' ? <Disc className="w-6 h-6 md:w-12 md:h-12 theme-accent" /> : <Music className="w-6 h-6 md:w-12 md:h-12 theme-accent" />}
              </div>
              <p className="text-xl md:text-3xl font-black uppercase italic tracking-tighter leading-none">{type}</p>
            </div>
          ))}
