      {activeTab === 'artists' && <LibraryGrid items={artists} type="artist" />}
      {activeTab === 'albums' && <LibraryGrid items={albums} type="album" />}
      {activeTab === 'tracks' && <LibraryGrid items={tracks} type="track" />}
    </div>
