}

function CreatorHub({ artists, setArtists, albums, setAlbums, tracks, setTracks, initialTab = 'artist', targetId }: any) {
  const [activeTab, setActiveTab] = useState<'artist' | 'album' | 'track' | 'manage'>(initialTab);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isGeneratingBio, setIsGeneratingBio] = useState(false);

  const [formData, setFormData] = useState<any>({
    artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', artistVerified: true, artistImg: '', artistCountry: '', artistTrending: false,
    albumTitle: '', albumArtistId: targetId || '', albumImg: '', albumYear: new Date().getFullYear(), albumDate: '', albumGenre: '', albumLabel: '', albumProducer: '',
    trackTitle: '', trackArtistId: targetId || '', trackAlbumId: '', trackDuration: getRandomDuration(), trackPlays: '0', trackLikes: '0', trackComposer: '', trackExplicit: false, trackImg: '', trackFit: '', trackYear: new Date().getFullYear(), trackDate: ''
  });

  const fillRealisticStats = () => {
    if (activeTab === 'artist') {
      setFormData((prev: any) => ({ ...prev, artistFollowers: formatNumber(getRandomValue(5000, 50000000)) }));
    } else if (activeTab === 'track') {
      const plays = getRandomValue(50000, 100000000);
      setFormData((prev: any) => ({ ...prev, trackPlays: formatNumber(plays), trackLikes: formatNumber(Math.floor(plays * 0.04)) }));
    }
  };

  const generateAIBio = async () => {
    if (!formData.artistName) return;
    setIsGeneratingBio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Music bio for "${formData.artistName}". Genre: ${formData.artistGenre || 'Unknown'}. Short, futuristic, cyberpunk vibe.`,
      });
      if (response.text) setFormData((prev: any) => ({ ...prev, artistBio: response.text.trim() }));
    } catch (e) { console.error(e); } finally { setIsGeneratingBio(false); }
  };

  const [inlineTracks, setInlineTracks] = useState<{title: string, duration: string, explicit: boolean, plays: string, featuredArtist: string}[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resetForm = () => {
    setEditingId(null);
    setFormData({ ...formData, artistName: '', artistBio: '', artistGenre: '', artistFollowers: '0', albumTitle: '', albumProducer: '', trackTitle: '', trackPlays: '0', trackDuration: getRandomDuration(), trackFit: '', albumDate: '', trackDate: '' });
    setInlineTracks([]);
  };

  const saveArtist = () => {
    if (!formData.artistName) return;
    const followers = parseFormattedNumber(formData.artistFollowers);
    const id = editingId || Math.random().toString(36).substr(2, 9);
    const newArtist: Artist = {
      id, name: formData.artistName, bio: formData.artistBio, imageUrl: formData.artistImg || `https://picsum.photos/seed/${formData.artistName}/600/600`,
      genre: formData.artistGenre, followers, verified: formData.artistVerified, country: formData.artistCountry, isRisingStar: formData.artistTrending
    };
    if (editingId) setArtists((prev: any) => prev.map((a: any) => a.id === editingId ? newArtist : a));
    else setArtists([...artists, newArtist]);
    resetForm();
  };

  const saveAlbum = () => {
    if (!formData.albumTitle || !formData.albumArtistId) return;
    const artist = artists.find(a => a.id === formData.albumArtistId);
    const albumId = editingId || Math.random().toString(36).substr(2, 9);
    const releaseYear = Number(formData.albumYear);
    const releaseDate = formData.albumDate || `${releaseYear}-01-01`;

    const newAlbum: Album = {
      id: albumId, title: formData.albumTitle, artistId: formData.albumArtistId, artistName: artist?.name || 'Unknown',
      coverUrl: formData.albumImg || `https://picsum.photos/seed/${formData.albumTitle}/600/600`, releaseYear, releaseDate,
      genre: formData.albumGenre, isLiked: false, producer: formData.albumProducer
    };

    if (inlineTracks.length > 0) {
      const newTracksList: Track[] = inlineTracks.map(t => {
        const playsNum = parseFormattedNumber(t.plays);
        return {
          id: Math.random().toString(36).substr(2, 9), 
          title: t.title || 'Untitled Signal', 
          artistId: formData.albumArtistId, 
          artistName: artist?.name || 'Unknown', 
          albumId: albumId, 
          albumTitle: formData.albumTitle,
          duration: t.duration || getRandomDuration(), 
          plays: playsNum, 
          likes: Math.floor(playsNum * 0.05), 
          isLiked: false, 
          isExplicit: t.explicit, 
          coverUrl: formData.albumImg || '',
          featuredArtist: t.featuredArtist || undefined,
          releaseDate: releaseDate
        };
      });
      setTracks((prev: any) => [...prev, ...newTracksList]);
    }

    if (editingId) setAlbums((prev: any) => prev.map((a: any) => a.id === editingId ? newAlbum : a));
    else setAlbums([...albums, newAlbum]);
    resetForm();
  };

  const saveTrack = () => {
    if (!formData.trackTitle || !formData.trackArtistId) return;
    const artist = artists.find(a => a.id === formData.trackArtistId);
    const album = albums.find(a => a.id === formData.trackAlbumId);
    const id = editingId || Math.random().toString(36).substr(2, 9);
    const plays = parseFormattedNumber(formData.trackPlays);
    const releaseYear = Number(formData.trackYear);
    const releaseDate = formData.trackDate || (album ? album.releaseDate : `${releaseYear}-01-01`);

    const newTrack: Track = {
      id, title: formData.trackTitle, artistId: formData.trackArtistId, artistName: artist?.name || 'Unknown',
      albumId: album?.id || 'single', albumTitle: album?.title || 'Single', duration: formData.trackDuration || getRandomDuration(), plays, 
      likes: parseFormattedNumber(formData.trackLikes), isLiked: false, composer: formData.trackComposer, isExplicit: formData.trackExplicit, 
      coverUrl: formData.trackImg || album?.coverUrl || `https://picsum.photos/seed/${formData.trackTitle}/400/400`, featuredArtist: formData.trackFit,
      releaseDate
    };
    if (editingId) setTracks((prev: any) => prev.map((t: any) => t.id === editingId ? newTrack : t));
    else setTracks([...tracks, newTrack]);
    resetForm();
  };

  return (
    <div className="p-scale max-w-6xl mx-auto">
      <div className="flex flex-col md:flex-row items-center justify-between mb-8 bg-black/20 p-6 md:p-10 rounded-3xl border border-white/5 gap-6">
        <h2 className="text-2xl md:text-4xl font-black uppercase italic tracking-tighter">Editor</h2>
        <div className="flex gap-1 p-1 bg-black/40 rounded-xl border border-white/5 w-full md:w-auto overflow-x-auto">
          {['artist', 'album', 'track', 'manage'].map(t => (
            <button key={t} onClick={() => { setActiveTab(t as any); resetForm(); }} className={`flex-1 md:flex-none px-4 py-2 rounded-lg font-black text-[9px] md:text-xs uppercase transition-all italic ${activeTab === t ? 'bg-zinc-800 text-white' : 'text-zinc-700'}`}>{t}</button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-scale">
        {activeTab !== 'manage' && (
          <div className="md:col-span-2 space-y-6 md:space-y-10 theme-card p-6 md:p-12 border border-white/5">
            {activeTab === 'artist' && (
              <div className="space-y-6">
                <InputGroup label="Entity Name" value={formData.artistName} onChange={v => setFormData({...formData, artistName: v})} />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <InputGroup label="Genre" value={formData.artistGenre} onChange={v => setFormData({...formData, artistGenre: v})} />
                  <InputGroup label="Listeners" numeric value={formData.artistFollowers} onChange={v => setFormData({...formData, artistFollowers: v})} />
                </div>
                <div className="relative">
                  <textarea value={formData.artistBio} onChange={e => setFormData({...formData, artistBio: e.target.value})} placeholder="Bio manifest..." rows={3} className="w-full bg-black/40 border border-white/10 rounded-2xl p-4 text-xs md:text-lg font-bold italic outline-none focus:theme-border-accent" />
                  <button onClick={generateAIBio} disabled={isGeneratingBio} className="mt-2 text-[9px] font-black uppercase theme-accent flex items-center gap-1.5"><Sparkles className="w-3 h-3" /> {isGeneratingBio ? 'Processing...' : 'AI Generate'}</button>
                </div>
                <button onClick={saveArtist} className="w-full py-4 bg-white text-black font-black rounded-2xl uppercase italic tracking-tighter shadow-lg">Sync Core</button>
              </div>
            )}
            {activeTab === 'album' && (
              <div className="space-y-6">
                <InputGroup label="Collection" value={formData.albumTitle} onChange={v => setFormData({...formData, albumTitle: v})} />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <select value={formData.albumArtistId} onChange={e => setFormData({...formData, albumArtistId: e.target.value})} className="w-full bg-black/40 border border-white/10 rounded-xl p-4 font-black text-xs md:text-sm uppercase italic outline-none appearance-none"><option value="">Assign Unit...</option>{artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
                  <div className="grid grid-cols-2 gap-2">
                    <InputGroup label="Year" numeric value={formData.albumYear.toString()} onChange={v => setFormData({...formData, albumYear: v})} />
                    <InputGroup label="Date" type="date" value={formData.albumDate} onChange={v => setFormData({...formData, albumDate: v})} />
                  </div>
                </div>
                <button onClick={saveAlbum} className="w-full py-4 bg-white text-black font-black rounded-2xl uppercase italic">Deploy Archive</button>
              </div>
            )}
            {activeTab === 'track' && (
              <div className="space-y-6">
                <InputGroup label="Signal" value={formData.trackTitle} onChange={v => setFormData({...formData, trackTitle: v})} />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   <select value={formData.trackArtistId} onChange={e => setFormData({...formData, trackArtistId: e.target.value})} className="w-full bg-black/40 border border-white/10 rounded-xl p-4 font-black text-xs uppercase italic outline-none"><option value="">Unit...</option>{artists.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select>
                   <select value={formData.trackAlbumId} onChange={e => setFormData({...formData, trackAlbumId: e.target.value})} className="w-full bg-black/40 border border-white/10 rounded-xl p-4 font-black text-xs uppercase italic outline-none"><option value="single">Single</option>{albums.filter(a => a.artistId === formData.trackArtistId).map(a => <option key={a.id} value={a.id}>{a.title}</option>)}</select>
                </div>
                <button onClick={saveTrack} className="w-full py-4 bg-white text-black font-black rounded-2xl uppercase italic">Broadcast</button>
              </div>
            )}
          </div>
        )}
        {activeTab !== 'manage' && (
          <div className="space-y-6">
            <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-square bg-black/40 border border-white/10 flex flex-col items-center justify-center cursor-pointer overflow-hidden relative group" style={{ borderRadius: `calc(2rem * var(--radius-factor))` }}>
              {(activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)) ? <img src={activeTab === 'artist' ? formData.artistImg : (activeTab === 'album' ? formData.albumImg : formData.trackImg)} className="w-full h-full object-cover" alt="" /> : <><ImageIcon className="w-8 h-8 text-zinc-800 mb-4" /><span className="text-[9px] font-black text-zinc-700 uppercase italic">Artwork</span></>}
            </div>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={async (e) => { const f = e.target.files?.[0]; if (f) { const b = await fileToBase64(f); setFormData({...formData, [activeTab === 'artist' ? 'artistImg' : (activeTab === 'album' ? 'albumImg' : 'trackImg')]: b}); } }} />
            <button onClick={fillRealisticStats} className="w-full py-3 bg-zinc-900 text-zinc-400 font-black text-[9px] rounded-xl uppercase italic border border-white/5">Random Metrics</button>
          </div>
        )}
      </div>
    </div>
  );
}

const InputGroup = ({ label, type = 'text', numeric, value, onChange }: any) => (
  <div className="space-y-2">
    <label className="text-[8px] font-black text-zinc-600 uppercase tracking-widest px-1 italic">{label}</label>
    <input type={type} value={value} onChange={e => { if (numeric) { const v = e.target.value.replace(/\D/g, ''); onChange(formatNumber(parseInt(v) || 0)); } else onChange(e.target.value); }} className="w-full bg-black/40 border border-white/10 rounded-xl p-3 text-xs md:text-sm font-black italic outline-none focus:theme-border-accent transition-all" />
  </div>
);

const ManagementSection = ({ title, items, onDelete, icon: Icon }: any) => (
  <div className="space-y-6">
    <h3 className="text-xl md:text-4xl font-black italic uppercase leading-none">{title} <span className="theme-accent opacity-40">({items.length})</span></h3>
    <div className="grid grid-cols-2 md:grid-cols-5 gap-scale">
      {items.map((item: any) => (
        <div key={item.id} className="theme-card p-3 md:p-5 border border-white/5 flex flex-col gap-3">
          <img src={item.imageUrl || item.coverUrl || `https://picsum.photos/seed/${item.id}/200/200`} className={`w-full aspect-square object-cover ${title === 'Artists' ? 'rounded-full' : 'rounded-lg'}`} alt="" />
          <p className="text-[11px] md:text-sm font-black truncate uppercase italic tracking-tighter">{item.name || item.title}</p>
          <button onClick={() => onDelete(item.id)} className="w-full py-2 bg-red-500/10 text-red-500 rounded-lg hover:bg-red-500 hover:text-white transition-all"><Trash2 className="w-3.5 h-3.5 mx-auto" /></button>
        </div>
      ))}
    </div>
  </div>
);

function TrackPage({ id, tracks, albums, artists, navigateTo }: any) {
  const track = tracks.find((t: any) => t.id === id);
  if (!track) return <div className="p-20 text-center text-2xl font-black opacity-10 uppercase italic">Lost Signal</div>;
  const artist = artists.find((a: any) => a.id === track.artistId);
  return (
    <div className="min-h-full flex flex-col p-scale animate-in">
      <div className="flex flex-col lg:flex-row items-center gap-10 md:gap-24 mt-6 md:mt-16 max-w-[1400px] mx-auto w-full">
        <div className="relative group shrink-0">
          <div className="absolute -inset-4 bg-white/5 blur-3xl rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-1000 theme-glow" style={{ backgroundColor: 'var(--accent-glow)' }}></div>
          <div className="relative w-full max-w-[300px] md:w-[400px] lg:w-[500px] aspect-square shadow-2xl overflow-hidden border-[4px] md:border-[12px] border-white/5 backdrop-blur-sm" style={{ borderRadius: `calc(5rem * var(--radius-factor))` }}>
              <img src={track.coverUrl} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-700" alt="" />
          </div>
        </div>
        <div className="flex flex-col items-center lg:items-start text-center lg:text-left min-w-0 flex-1">
          <span className="text-[9px] md:text-xs font-black uppercase tracking-[0.4em] theme-accent italic mb-4 shrink-0">Signal Broadcast</span>
          <h1 className={`${getDynamicFontSize(track.title, 'text-3xl md:text-7xl lg:text-[7vw]')} font-black mb-6 md:mb-12 tracking-tighter leading-none italic uppercase break-words w-full shrink-0`}>{track.title}</h1>
          <div onClick={() => navigateTo('artist', { id: track.artistId })} className="flex items-center gap-3 md:gap-6 text-xl md:text-4xl font-black hover:theme-accent cursor-pointer tracking-tighter mb-10 md:mb-16 italic uppercase shrink-0">
            <img src={artist?.imageUrl} className="w-10 h-10 md:w-16 h-16 rounded-full shrink-0 border-2 border-white/5 shadow-lg" alt="" />
            <div className="flex flex-col lg:flex-row lg:items-baseline lg:gap-3">
              <span>{track.artistName}</span>
              {track.featuredArtist && <span className="text-zinc-600 text-sm md:text-2xl font-bold tracking-tight">feat. {track.featuredArtist}</span>}
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-8 md:gap-20 w-full max-w-4xl shrink-0">
             <div className="flex flex-col gap-2 md:gap-4">
                <span className="text-[8px] md:text-[10px] font-black text-zinc-600 uppercase tracking-[0.2em] italic leading-none">Plays</span>
                <span className="text-xl md:text-4xl lg:text-5xl font-black tabular-nums tracking-tighter leading-none">{formatNumber(track.plays)}</span>
             </div>
             <div className="flex flex-col gap-2 md:gap-4 min-w-0">
                <span className="text-[8px] md:text-[10px] font-black text-zinc-600 uppercase tracking-[0.2em] italic leading-none">Record</span>
                <span className="text-xl md:text-3xl lg:text-4xl font-black truncate leading-none uppercase italic tracking-tighter">{track.albumTitle}</span>
             </div>
             <div className="flex flex-col gap-2 md:gap-4">
                <span className="text-[8px] md:text-[10px] font-black text-zinc-600 uppercase tracking-[0.2em] italic leading-none">Date</span>
                <span className="text-xl md:text-3xl lg:text-4xl font-black tabular-nums tracking-tighter leading-none italic">{track.releaseDate}</span>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function AlbumView({ id, albums, tracks, toggleLikeTrack, toggleLikeAlbum, navigateTo }: any) {
  const album = albums.find((a: any) => a.id === id);
  if (!album) return <div className="p-20 text-center text-2xl font-black opacity-10 uppercase italic">Void</div>;
  const albumTracks = sortTracksByRelevance(tracks.filter((t: any) => t.albumId === id));
  return (
    <div className="min-h-full">
      <div className="p-scale flex flex-col md:flex-row items-center md:items-end gap-8 md:gap-24 max-w-[1400px] mx-auto">
        <div className="relative group shrink-0">
          <div className="absolute -inset-4 blur-3xl rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-1000 theme-glow" style={{ backgroundColor: 'var(--accent-glow)' }}></div>
          <div className="relative w-full max-w-[280px] md:w-[380px] lg:w-[480px] aspect-square shadow-2xl overflow-hidden border-[4px] md:border-[12px] border-white/5 backdrop-blur-sm" style={{ borderRadius: `calc(6rem * var(--radius-factor))` }}>
              <img src={album.coverUrl} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-700" alt="" />
          </div>
        </div>
        <div className="flex flex-col items-center md:items-start text-center md:text-left min-w-0 flex-1 overflow-hidden">
          <span className="text-[9px] md:text-xs font-black uppercase tracking-[0.5em] text-zinc-700 italic mb-4">Archives</span>
          <h1 className={`${getDynamicFontSize(album.title, 'text-3xl md:text-7xl lg:text-[8vw]', true)} font-black mb-6 md:mb-12 tracking-tighter leading-[0.9] italic uppercase break-words w-full`}>{album.title}</h1>
          <p onClick={() => navigateTo('artist', { id: album.artistId })} className="text-xl md:text-3xl font-black italic tracking-tighter text-zinc-300 uppercase leading-none hover:theme-accent cursor-pointer">{album.artistName}</p>
          <div className="mt-4 flex items-center gap-4 text-[10px] md:text-sm font-black text-zinc-700 uppercase tracking-widest italic">
            <span className="flex items-center gap-1.5"><Calendar className="w-3.5 h-3.5" /> {album.releaseDate}</span>
            <span>•</span>
            <span>{albumTracks.length} recordings</span>
          </div>
        </div>
      </div>
      <div className="max-w-7xl mx-auto px-4 md:px-14 pb-20">
        <div className="flex items-center gap-6 md:gap-12 mb-10 md:mb-20">
          <button className="w-12 h-12 md:w-16 h-16 theme-bg-accent rounded-full flex items-center justify-center shadow-xl"><Play className="text-black fill-black ml-0.5 md:ml-1 w-6 h-6 md:w-8 h-8" /></button>
          <Heart onClick={() => toggleLikeAlbum(album.id)} className={`w-8 h-8 md:w-10 h-10 cursor-pointer transition-all ${album.isLiked ? 'theme-accent fill-current' : 'text-zinc-800'}`} />
        </div>
        <div className="space-y-1">
          {albumTracks.map((track: any, i: number) => <TrackRow key={track.id} track={track} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: track.id })} size="lg" />)}
        </div>
      </div>
    </div>
  );
}

function SearchView({ query, artists, albums, tracks, navigateTo, toggleLikeTrack }: any) {
  const filteredArtists = artists.filter((a: any) => a.name.toLowerCase().includes(query.toLowerCase()));
  const filteredTracks = tracks.filter((t: any) => t.title.toLowerCase().includes(query.toLowerCase()));
  if (!query) {
    return (
      <div className="p-scale">
        <h3 className="text-xl md:text-5xl font-black mb-8 md:mb-16 tracking-tighter uppercase italic leading-none">Matrix Nodes</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-scale">
          {['Electro', 'Neon', 'Deep Pulse', 'Industrial', 'Hyper', 'Ambient', 'Techno', 'Atmospheric'].map(g => (
            <div key={g} className="theme-card aspect-video md:aspect-auto md:h-40 p-6 md:p-10 relative overflow-hidden group cursor-pointer border border-white/5 hover:bg-zinc-800/40 transition-all flex items-center">
              <span className="text-lg md:text-2xl lg:text-4xl font-black relative z-10 tracking-tighter italic uppercase leading-none overflow-hidden truncate whitespace-nowrap">{g}</span>
              <img src={`https://picsum.photos/seed/${g}/600/400`} className="absolute inset-0 w-full h-full object-cover opacity-20 group-hover:scale-110 transition-transform duration-700 mix-blend-screen" alt="" />
              <div className="absolute inset-0 bg-gradient-to-r from-[var(--bg-color)]/80 to-transparent z-[5]"></div>
            </div>
          ))}
        </div>
      </div>
    );
  }
  return (
    <div className="p-scale">
      {filteredArtists.length > 0 && <div className="mb-16 md:mb-24"><h3 className="text-xl md:text-3xl font-black mb-6 md:mb-10 tracking-tighter uppercase italic leading-none">Units</h3><div className="flex gap-4 md:gap-10 overflow-x-auto pb-4 custom-scrollbar">{filteredArtists.map((a: any) => <div key={a.id} onClick={() => navigateTo('artist', { id: a.id })} className="shrink-0 w-36 md:w-64 theme-card p-4 md:p-10 hover:bg-zinc-900/40 transition-all cursor-pointer border border-white/5"><img src={a.imageUrl} className="w-full aspect-square object-cover rounded-full mb-4 md:mb-8 shadow-xl" alt="" /><p className="font-black truncate text-xs md:text-xl tracking-tighter text-center italic uppercase leading-none">{a.name}</p></div>)}</div></div>}
      {filteredTracks.length > 0 && <div className="mb-16"><h3 className="text-xl md:text-3xl font-black mb-6 md:mb-10 tracking-tighter uppercase italic leading-none">Signals</h3><div className="space-y-1.5 max-w-6xl">{filteredTracks.map((t: any, i: number) => <TrackRow key={t.id} track={t} index={i} toggleLike={toggleLikeTrack} onPlay={() => navigateTo('track', { id: t.id })} size="lg" />)}</div></div>}
    </div>
  );
}
